<template>
  <div class="md-lookup-root">
    <q-card-section>
    <div class="row">
      <div class="row col-12">
        <template v-for="(item, index) in advance_filters" :key="index">
          <div class="row mb-10">
            <div class="col-auto q-ml-md q-mr-sm">
              <q-select
                outlined
                class="ms-select"
                clearable
                v-model="item['field']"
                :options="tableColumns"
                emit-value
                map-options
              >
                <template v-slot:append>
                  <q-icon
                    v-if="item['validate_field_name']"
                    flat
                    dense
                    name="error"
                    color="red"
                  >
                    <q-tooltip class="bg-red line-error-tooltip">
                      {{ $t('FIELD_REQUIRED') }}
                    </q-tooltip>
                  </q-icon>
                </template>
                <template v-slot:selected-item="scope">
                  <div class="ellipsis">{{ scope.opt.label }}</div>
                </template>
              </q-select>
            </div>

            <div class="col-auto q-mr-sm">
              <q-select
                outlined
                class="ms-select ms-select-operator left-border-none"
                clearable
                v-model="item['operator']"
                :options="search_operators"
                emit-value
                map-options
              >
                <template v-slot:append>
                  <q-icon
                    v-if="item['validate_operator']"
                    flat
                    dense
                    name="error"
                    color="red"
                  >
                    <q-tooltip class="bg-red line-error-tooltip">
                      {{ $t('FIELD_REQUIRED') }}
                    </q-tooltip>
                  </q-icon>
                </template>
                <template v-slot:selected-item="scope">
                  <div class="ellipsis">{{ scope.opt.label }}</div>
                </template>
              </q-select>
            </div>

            <div class="col">
              <q-input
                borderless
                v-model="item['search_text']"
                @keyup.enter="searchBySelectedColumns"
                :class="
                  'ms-search-input left-border-none ' +
                  (item['validate'] ? 'column-error-border' : '')
                "
                @mousedown.stop
              >
                <template v-slot:append>
                  <q-icon
                    v-if="item['validate'] == true"
                    flat
                    dense
                    name="error"
                    color="red"
                  >
                    <q-tooltip class="bg-red line-error-tooltip">
                      {{ $t('FIELD_REQUIRED') }}
                    </q-tooltip>
                  </q-icon>
                </template>
              </q-input>
            </div>

            <q-btn
              class="q-ml-sm"
              icon="close"
              @click="removeFilter(index)"
              flat
              round
              dense
            ></q-btn>
          </div>
        </template>
      </div>
    </div>

    <div class="row mb-10">
      <div class="col-auto q-ml-md q-mr-sm">
        <q-checkbox
          class="all-columns q-mr-md"
          :label="$t('match_all_filters')"
          v-model="match_all_filters"
          size="30px"
        />
      </div>
    </div>

    <div class="full-width">
      <f-btn
        @click="searchBySelectedColumns"
        @keyup.enter="searchBySelectedColumns"
        :label="$t('search')"
        class="q-ml-md"
      >
        <q-tooltip>{{ $t('search') }}</q-tooltip>
      </f-btn>
      <f-btn
        appearance="secondary"
        @click="addNewAdvanceSearchRow"
        :label="$t('add_new_filter')"
        class="q-ml-sm"
      >
        <q-tooltip>{{ $t('add_new_filter') }}</q-tooltip>
      </f-btn>
      <div class="float-right">
        <f-btn
          class="q-ml-sm"
          :label="$t('proceed')"
          @click="selectedRowProceed()"
          :disable="disableSelectionButton"
        />
        <CreateTaskBtn />
      </div>

    </div>
    <savedSortByBadges />

    <q-checkbox
      class="all-columns q-mr-md"
      :label="$t('display_all_columns')"
      v-model="show_all_columns"
      @update:model-value="
        (val: any) => {
          showAllColumns(val);
        }
      "
      size="30px"
    />

    <div class="q-pl-md q-pr-md q-pt-md">
      <DocBitsTable
        ref="docBitsTableRef"
        :rows="tableRows"
        :columns="tableColumns"
        table-id="data-look-up-table"
        row-key="id"
        :loading="loading"
        :features="{ sorting: true, clientSideSort: false, pagination: false, columnReorder: true }"
        :pagination="{ sortBy: currentSortColumn, descending: currentSortDescending }"
        table-height="390px"
        :no-data-label="$t('no_data_found')"
        dense
        @row-click="({ row }: any) => dblClickSelect(row)"
        @update:sorting="onSortChange"
        @update:filters="onTableFilterChange"
      />
      <div class="back-white flex justify-end">
        <div class="row" style="margin-right: 0">
          <q-pagination
            v-model="current_page"
            color="primary"
            :max="total_pages"
            class="q-py-xs q-mx-md pagination-input"
            :max-pages="6"
            input
            boundary-links
            @update:model-value="nexPageClicked()"
          />
        </div>
      </div>
    </div>
    </q-card-section>

    <q-inner-loading :showing="loading" class="md-lookup-loading">
      <img class="md-lookup-loader" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </div>
</template>

<script lang="ts">
// @ts-nocheck
import { notify } from 'src/components/notifications/notify';
import { uid } from 'quasar';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { masterDataPrefix } from 'src/constants';
import { masterDataApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import dragDropColumn from 'src/mixins/dragDropColumn';
import CreateTaskBtn from 'src/pages/Tasks/CreateBtn.vue';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import savedSortByBadges from './MasterData/saved-sortby-badges.vue';
import { isObjectEmtpy, isUndefinedOrNull } from 'src/utils/general';
import { makeOrderByJsonForApi, convertLabel } from 'src/utils/ms_utlis';
import {
  useDocMasterDataLookUpStore,
  useMasterDataLookupStore,
  useDocumentStore,
  useSettingStore,
  useFormBuilderStore,
} from 'src/store/main';

export default defineComponent({
  emits: ['populatePopupData'],
  mixins: [displayFieldLabel, dragDropColumn, dateUtils],
  props: {
    page: {
      type: Number,
      default: 1,
    },
    attributeKey: {
      type: String,
      default: 'field_name', // possible value are field_name, column_name (field_name will be used for header value, column_name will be used for line values)
    },
  },
  watch: {
    quickSearchText: {
      handler: function (newVal, oldVal) {
        this.updateFilters();
      },
    },
  },
  components: {
    DocBitsTable,
    CreateTaskBtn,
    savedSortByBadges,
  },
  computed: {
    currentSortColumn(): string | null {
      if (this.orderByMap.size === 0) return null;
      const sortField = this.orderByMap.keys().next().value;
      // orderByMap stores col.field, but DocBitsTable expects col.name for the sort indicator
      const col = this.tableColumns.find((c: any) => c.field === sortField);
      return col ? col.name : sortField ?? null;
    },
    currentSortDescending(): boolean {
      if (this.orderByMap.size === 0) return false;
      return this.orderByMap.values().next().value === 'desc';
    },
  },
  data() {
    return {
      columnListPreferenc: [] as any,
    };
  },
  mounted: function () {
    this.validateViewVariables();
    this.getOrderByColumns(this.master_lookup_type);
    this.searchByField();
    (<any>window).msl = this;
    document.addEventListener('ms_search', this.searchEvent);
    document.addEventListener('keydown', this.onKeyup);
    this.initailizeDragColumnsById('data-look-up-table');
    document.addEventListener(
      'data-look-up-table-column-drop',
      this.onDropColumns,
    );
  },
  unmounted: function () {
    document.removeEventListener('ms_search', this.searchEvent);
    document.removeEventListener('keydown', this.onKeyup);
    document.removeEventListener(
      'data-look-up-table-column-drop',
      this.onDropColumns,
    );
    this.show_all_columns = false;
    this.showAllColumns(this.show_all_columns);
  },

  methods: {
    onDropColumns(event: any) {
      const reorderedColumns = event?.detail?.tableColumns;
      if (!Array.isArray(reorderedColumns) || reorderedColumns.length === 0) {
        return;
      }
      const columnList = reorderedColumns
        .filter((column: any) => column && column.name !== '__actions__')
        .map((column: any) => column.field);
      this.tableColumns = reorderedColumns.filter(
        (column: any) => column && column.name !== '__actions__',
      );
      this.setColumnsByType(this.master_lookup_type, this.tableColumns);
      this.saveOrderColumns(columnList);
    },
    async saveOrderColumns(columns: any) {
      try {
        this.loading = true;
        let keyName = masterDataPrefix + this.master_lookup_type.toUpperCase();
        await this.updateSetting(keyName, JSON.stringify(columns));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    removeFilter(index: any) {
      delete this.advance_filters[index];
    },
    searchEvent() {
      this.searchBySelectedColumns();
    },

    addNewAdvanceSearchRow() {
      const id = uid();
      this.advance_filters[id] = {
        field: null,
        search_text: '',
        validate: false,
        operator: this.search_operator,
        validate_field_name: false,
      };
    },

    updateFilters() {
      for (let [index, column] of Object.entries(this.advance_filters)) {
        const is_field_selected =
          column.hasOwnProperty('field') && column.field;
        const is_text_entered =
          column.search_text && column.search_text.length > 0;

        // delete if there is no field selected and no text entered
        if (!is_field_selected && !is_text_entered) {
          delete this.advance_filters[index];
          continue;
        }

        const is_operator_selected =
          column.hasOwnProperty('operator') && column.operator;
        if (!is_operator_selected) {
          column.operator = this.search_operator;
        }
      }
    },

    validateSearchFilters() {
      let is_valid = true;
      for (let [index, column] of Object.entries(this.advance_filters)) {
        column.validate = false;
        column.validate_field_name = false;
        const is_field_selected =
          column.hasOwnProperty('field') && column.field;
        const is_text_entered =
          column.search_text && column.search_text.length > 0;

        if (!is_field_selected && is_text_entered) {
          column.validate_field_name = true;
          is_valid = false;
        }

        if (!is_text_entered && is_field_selected) {
          column.validate = true;
          is_valid = false;
        }
      }

      return is_valid;
    },

    makeSearchJsonFromFilters() {
      let filters = [] as dynamicObj[];

      for (let [index, column] of Object.entries(this.advance_filters)) {
        if (column.search_text) {
          // add operator
          filters.push({
            field: column.field.field,
            operator: column.operator,
            value: column.search_text,
          });
        }
      }

      return filters;
    },

    prepareFiltersForApiCall() {
      let data = {} as dynamicObj;
      data['data_type'] = this.master_lookup_type;
      data['filter_data_json'] = '';
      let filter_data_json = {} as dynamicObj;
      filter_data_json['match_all'] = this.match_all_filters;

      const filters = this.makeSearchJsonFromFilters();

      if (filters.length > 0) {
        filter_data_json['filters'] = filters;
      }
      data['filter_data_json'] = JSON.stringify(filter_data_json);

      return data;
    },

    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.searchBySelectedColumns();
      }
    },

    async searchBySelectedColumns() {
      try {
        this.loading = true;
        this.updateFilters();
        if (this.validateSearchFilters() === false) {
          return;
        }

        this.syncFiltersToTableHeader();

        this.tableRows = [];
        this.resetPagination();

        const data = this.prepareFiltersForApiCall();
        this.search_params = data;
        this.last_search_params = data;
        await this.fetchFromServer(data);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    setInitialSearch() {
      for (let [index, fieldDef] of Object.entries(this.advance_filters)) {
        let lookup_field = fieldDef.fuzzy_field;
        const selected_field = this.tableColumns.find(
          (x: any) => x.field.toLowerCase() == lookup_field.toLowerCase(),
        );

        if (!selected_field) {
          continue;
        }

        fieldDef.field = selected_field;

        // if no operator is selected, set default operator
        if (!fieldDef.operator) {
          fieldDef.operator = this.search_operator;
        }
      }
    },

    async searchByField() {
      try {
        this.loading = true;
        await this.populateTableColumns();
        await this.setDefaultSearchOperator();
        this.setInitialSearch();
        this.updateFilters();
        const data = this.prepareFiltersForApiCall();
        this.search_params = data;
        this.last_search_params = data;
        let response = await this.fetchFromServer(data);
        return response;
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    async populateTableColumns() {
      const saved_columns = this.getColumnsByType(this.master_lookup_type);
      if (saved_columns.length > 0) {
        this.tableColumns = saved_columns;
        this.populateColumnMsMapping();
        this.applyColumnSort();
        return;
      }

      await this.getColumnSortPreference();
      this.getColumnsfromFieldsMapping();
    },

    populateColumnMsMapping() {
      if (!this.master_data_fields_map.has(this.master_lookup_type)) {
        return;
      }
      const fields = this.master_data_fields_map.get(
        this.master_lookup_type,
      ).fields;
      for (const field of fields) {
        const fieldName = field[this.attributeKey];
        const lookup_field = field.lookup_field.toLowerCase();
        this.column_ms_mapping[lookup_field] = fieldName;
      }
    },

    getColumnsfromFieldsMapping() {
      if (!this.master_data_fields_map.has(this.master_lookup_type)) {
        return;
      }
      const fields = this.master_data_fields_map.get(
        this.master_lookup_type,
      ).fields;

      for (const [index, field] of fields.entries()) {
        const fieldName = field[this.attributeKey];
        const lookup_field = field.lookup_field.toLowerCase();
        let label = this.getColumnLabel(fieldName);

        this.column_ms_mapping[lookup_field] = fieldName;
        this.tableColumns.push({
          name: fieldName,
          label: label,
          field: lookup_field,
          align: 'left',
        });
      }

      this.applyColumnSort();
      this.setColumnsByType(this.master_lookup_type, this.tableColumns);
    },

    getColumnLabel(field_name: string) {
      let label = '';
      if (this.formBuilderConfigModel[field_name]) {
        let label = this.displayFieldLabel(
          this.formBuilderConfigModel[field_name],
        );
      }
      if (!label || label == '') {
        label = field_name;
      }
      if (label == field_name) {
        // replace underscore with space and make first letter capital
        label = convertLabel(label);
      }

      return label;
    },

    setRequestFields(filters: any) {
      filters = JSON.parse(filters).filters;
      if (
        this.master_data_fields_map.size == 0 ||
        !this.master_data_fields_map.has(this.master_lookup_type)
      ) {
        return '';
      }
      if (
        this.master_data_fields_map
          .get(this.master_lookup_type)
          .hasOwnProperty('request_fields')
      ) {
        const fields = this.master_data_fields_map.get(
          this.master_lookup_type,
        ).request_fields;
        const field_name = this.master_data_fields_map.get(
          this.master_lookup_type,
        ).field_name;
        const lookup_field = this.master_data_fields_map.get(
          this.master_lookup_type,
        ).lookup_field;

        if (typeof fields === 'object') {
          let request_fields = {} as dynamicObj;

          this.record.fields.forEach((field: dynamicObj) => {
            for (const [key, value] of Object.entries(fields)) {
              if (field.name == value) {
                request_fields[field.name] = field.formatted_value;
              }
            }
          });

          if(!filters || filters.length == 0) {
            return '';
          }
          filters.forEach((filter: dynamicObj) => {
            if (filter.field == lookup_field) {
              request_fields[field_name] = filter.value;
            }
          });

          return JSON.stringify(request_fields);
        }
      }
      return '';
    },

    async fetchFromServer(search_data: dynamicObj) {
      try {
        this.loading = true;
        const data = {} as dynamicObj;
        data['data_type'] = search_data['data_type'];
        data['skip'] = this.offset;
        data['limit'] = this.page_size;

        const form_data = {} as dynamicObj;
        form_data['document_fields_data'] = this.setRequestFields(
          search_data['filter_data_json'],
        );

        const order_by = this.makeOrderByForCall();
        if (order_by.length > 0) {
          data['sort_order_json'] = JSON.stringify(order_by);
        }

        if (this.doc_loaded) {
          data['amounts_format'] = this.amount_format_locale;
        }

        let sub_org_id = this.getDocSubOrgId();
        if (!isUndefinedOrNull(sub_org_id) && sub_org_id != '') {
          data['sub_org_id'] = sub_org_id;
        }

        let response = {} as dynamicObj;
        response = await masterDataApiService.getData_V2(
          data,
          search_data['filter_data_json'],
          form_data,
        );

        if (response.success == false) {
          throw response;
        }

        if (
          !response.data ||
          !Array.isArray(response.data) ||
          response.data.length == 0
        ) {
          logError('No Data From server');
          return;
        }

        this.tableRows = [];
        if (response.hasOwnProperty('total_records')) {
          this.total_records = response.total_records;
          this.setTotalPages();
        }

        this.populateRows(response.data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async nexPageClicked() {
      try {
        this.calculateOffset();
        await this.fetchFromServer(this.search_params);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
      this.offset = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    populateRows(response: any) {
      Array.from(response).forEach((tableRow: any, index: any) => {
        let newRow: dynamicObj = {};
        for (let [key, value] of Object.entries(tableRow)) {
          key = key.toLowerCase();
          newRow[key] = value;

          if (key === 'last_modified_on' || key === 'order_date') {
            newRow[key] = this.formatDateAccordingToPreference(
              String(value),
              true,
            );
          }
        }

        this.tableRows.push(newRow);
      });

      this.$forceUpdate();
    },

    // set selected row data into the main form
    selectedRowProceed() {
      let row = JSON.parse(JSON.stringify(this.selectedRow));
      this.selected_row = JSON.stringify(row[0]);
      this.selectedRow = [];
      this.disableSelectionButton = true;
      this.populateMSDataFromPopup();
    },

    validateViewVariables() {
      this.inital_filters = JSON.parse(JSON.stringify(this.advance_filters));
      if (this.master_data_fields_map.size == 0) {
        logInfo('No master data field map is empty');
      }

      if (isObjectEmtpy(this.formBuilderConfigModel)) {
        logInfo('view data model is empty');
      }
    },

    showAllColumns(display_all: boolean) {
      // show all columns
      if (this.tableRows.length == 0) {
        return;
      }
      if (!display_all) {
        // clean up existing columns
        this.tableColumns.splice(0, this.tableColumns.length);
        this.getColumnsfromFieldsMapping();
        return;
      }

      this.populateTableColumnsFromRow();
    },

    populateTableColumnsFromRow() {
      const first_row = this.tableRows[0];
      for (const [name, value] of Object.entries(first_row)) {
        if (this.column_ms_mapping.hasOwnProperty(name)) {
          continue;
        }

        let label = name;
        if (name == 'last_modified_on') {
          label = this.$t(name);
        } else {
          label = convertLabel(label);
        }

        this.tableColumns.push({
          name: name,
          label: label,
          field: name,
          align: 'left',
        });
      }
      this.applyColumnSort();
    },

    dblClickSelect(row: any) {
      this.selected_row = JSON.stringify(row);
      this.selectedRow = [];
      this.disableSelectionButton = true;
      this.populateMSDataFromPopup();
    },

    async getColumnSortPreference() {
      const saved_columns = JSON.parse(await this.getColumnPreference(this.master_lookup_type));
      if (saved_columns.length > 0) {
        this.columnListPreferenc = saved_columns;
      } else {
        await this.getDataTypeFields(this.master_lookup_type);
        this.columnListPreferenc = this.data[this.master_lookup_type].fields;
      }
    },

    applyColumnSort() {
      this.tableColumns = this.sortColumns(
        this.columnListPreferenc,
        this.tableColumns,
      );
    },

    async setDefaultSearchOperator() {
      const search_operator_pref_key = String(
        this.master_lookup_type + this.search_op_key_postfix,
      ).toUpperCase();
      this.search_operator = await this.getSetting(search_operator_pref_key);
      if (this.search_operator) {
        return;
      }
      this.search_operator = this.default_operator;
    },

    onTableFilterChange(payload: any) {
      const columnObj = this.tableColumns.find(
        (c: any) => c.name === payload.column,
      );
      if (!columnObj) return;

      if (payload.action === 'set') {
        // Check if there's already an advance_filter for this column
        const existingKey = this.findAdvanceFilterKey(payload.column);
        if (existingKey) {
          this.advance_filters[existingKey].search_text = String(payload.value);
          this.advance_filters[existingKey].operator = payload.operator;
        } else {
          const id = uid();
          this.advance_filters[id] = {
            field: columnObj,
            search_text: String(payload.value),
            validate: false,
            operator: payload.operator,
            validate_field_name: false,
          };
        }
        this.searchBySelectedColumns();
      } else if (payload.action === 'clear') {
        const existingKey = this.findAdvanceFilterKey(payload.column);
        if (existingKey) {
          delete this.advance_filters[existingKey];
          this.searchBySelectedColumns();
        }
      }
    },

    syncFiltersToTableHeader() {
      const columnFilter = (this.docBitsTableRef as any)?.columnFilter;
      if (!columnFilter) return;

      const advanceRows = Object.values(this.advance_filters as dynamicObj);
      for (const columnName of Object.keys(columnFilter.filterValues.value)) {
        const advance = advanceRows.find(
          (f: any) => f?.field?.name === columnName,
        );
        const value = advance?.search_text ? String(advance.search_text) : '';
        if (!value) {
          columnFilter.clearFilter(columnName);
        } else {
          columnFilter.setFilter(columnName, value, advance.operator);
        }
      }
    },

    findAdvanceFilterKey(columnName: string): string | null {
      for (const [key, filter] of Object.entries(this.advance_filters)) {
        if (filter.field && filter.field.name === columnName) {
          return key;
        }
      }
      return null;
    },

    async onSortChange(payload: { column: string; direction: 'asc' | 'desc' | null }) {
      // DocBitsTable emits col.name, but orderByMap and the API use col.field (lookup_field)
      const col = this.tableColumns.find((c: dynamicObj) => c.name === payload.column);
      const sortField = col ? col.field : payload.column;

      if (payload.direction === null) {
        this.orderByMap.delete(sortField);
      } else {
        this.orderByMap.clear();
        this.orderByMap.set(sortField, payload.direction);
      }
      this.saveOrderByColumns(this.master_lookup_type);
      await this.refetchWithCurrentParams();
    },

    async refetchWithCurrentParams() {
      try {
        this.loading = true;
        this.resetPagination();
        const data = this.last_search_params;
        if (Object.keys(data).length === 0) {
          return;
        }
        await this.fetchFromServer(data);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    makeOrderByForCall() {
      return makeOrderByJsonForApi(this.orderByMap);
    },

    populateMSDataFromPopup() {
      let config = this.master_data_fields_map.get(this.master_lookup_type);
      this.$emit(
        'populatePopupData',
        config,
        this.master_lookup_type,
        this.selected_row,
      );
    },
  },
  setup() {
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const {
      master_data_fields_map,
      selected_row,
      column_ms_mapping,
      advance_filters,
      master_lookup_type,
      last_search_params,
      search_operators,
      search_op_key_postfix,
      orderByMap,
      default_operator,
      inital_filters,
      isDraggle,
    } = storeToRefs(doc_ms_data_lookup_store);

    const { setColumnsByType, getColumnsByType, getOrderByColumns, saveOrderByColumns } =
      doc_ms_data_lookup_store;

    const master_data_lookup_store = useMasterDataLookupStore();
    const { data } = storeToRefs(master_data_lookup_store);
    const { sortColumns, getColumnPreference, getDataTypeFields } =
      master_data_lookup_store;

    const doc_store = useDocumentStore();
    const { getDocSubOrgId } = doc_store;
    const { amount_format_locale, doc_loaded, record } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { getSetting, updateSetting } = settings_store;

    const form_builder_store = useFormBuilderStore();
    const { formBuilderConfigModel } = storeToRefs(form_builder_store);

    return {
      data,
      record,
      isDraggle,
      doc_loaded,
      orderByMap,
      default_operator,
      amount_format_locale,
      search_op_key_postfix,
      advance_filters,
      column_ms_mapping,
      master_lookup_type,
      last_search_params,
      selected_row,
      master_data_fields_map,
      search_operators,
      docBitsTableRef: ref<any>(null),
      tableColumns: ref([] as dynamicObj[]),
      loading: ref(false),
      tableRows: ref([] as dynamicObj[]),
      selectedRow: ref([]),
      disableSelectionButton: ref(true),
      show_all_columns: ref(false),
      match_all_filters: ref(true),
      search_params: ref({} as dynamicObj),
      current_page: ref(1),
      total_pages: ref(0),
      offset: ref(0),
      page_size: ref(10),
      total_records: ref(0),
      search_operator: ref(''),
      inital_filters,

      formBuilderConfigModel,

      getSetting,
      sortColumns,
      updateSetting,
      getDocSubOrgId,
      getColumnsByType,
      setColumnsByType,
      getOrderByColumns,
      getDataTypeFields,
      getColumnPreference,
      saveOrderByColumns,
    };
  },
});
</script>

