/**
 * DU-223 — Which sub-group copies (`__1`, `__2`, …) a repeatable field group has.
 *
 * A repeatable group (e.g. a tax pair: net amount, tax amount, tax rate, tax
 * country, tax code) is stored as flat fields; each extra copy carries a
 * `__<n>` suffix on every field name (`net_amount__1`, `tax_amount__1`, …).
 *
 * The validation screen used to look only at the group's FIRST field
 * (`net_amount__<n>`) to decide which copies exist. A copy whose first field is
 * missing but whose other fields carry values (`tax_amount__1` = 533.29 with no
 * `net_amount__1`) was then never rendered — yet the export still reads it and
 * sends it on, so the user could neither see nor remove it.
 *
 * Rule:
 * - the first field marks a copy whenever it is present, valued or not
 *   (unchanged behaviour);
 * - another field marks a copy only when it is one of the amount fields the
 *   export builds tax lines from (net amount, tax amount, tax rate, gross
 *   amount — any tax group) AND carries a value. Placeholders written by
 *   document scripts (`tax_country__1`, `tax_code_without_country__1`) never
 *   add a group, valued or not, because the export ignores them.
 */

// Mirrors the fields doc2-api's get_tax_lines discovers sub-pairs from.
const TAX_LINE_AMOUNT_FIELD =
  /^(net_amount|tax_amount|tax_rate|gross_amount)(_\d+)?$/;

export interface SubGroupField {
  name: string;
  value?: unknown;
  formatted_value?: unknown;
  content?: unknown;
  [key: string]: unknown;
}

function isFilled(value: unknown): boolean {
  if (value === null || value === undefined) {
    return false;
  }
  // LOV selections arrive as [{ translated_value: 'ES' }] or a single such
  // object: filled only when something inside is filled, so an empty
  // selection ({ translated_value: '' }) does not count.
  if (Array.isArray(value)) {
    return value.some(isFilled);
  }
  if (typeof value === 'object') {
    return Object.values(value as object).some(isFilled);
  }
  return String(value).trim() !== '';
}

export function fieldCarriesValue(field: SubGroupField): boolean {
  return (
    isFilled(field.value) ||
    isFilled(field.formatted_value) ||
    isFilled(field.content)
  );
}

function subGroupIndexOf(fieldName: string, rowName: string): number | null {
  const prefix = rowName + '__';
  if (!fieldName.startsWith(prefix)) {
    return null;
  }
  const suffix = fieldName.slice(prefix.length);
  if (!/^\d+$/.test(suffix)) {
    return null;
  }
  const index = Number(suffix);
  return index > 0 ? index : null;
}

/**
 * Returns the sub-group indexes present for a group, ascending and unique.
 *
 * @param rowNames  field names of the parent group, first field first
 * @param fields    the document's fields
 */
export function findSubGroupIndexes(
  rowNames: string[],
  fields: SubGroupField[],
): number[] {
  const indexes = new Set<number>();
  const [firstRowName, ...otherRowNames] = rowNames.filter(Boolean);
  if (!firstRowName) {
    return [];
  }
  const amountRowNames = otherRowNames.filter((rowName) =>
    TAX_LINE_AMOUNT_FIELD.test(rowName),
  );

  for (const field of fields ?? []) {
    if (!field || typeof field.name !== 'string') {
      continue;
    }

    const firstIndex = subGroupIndexOf(field.name, firstRowName);
    if (firstIndex !== null) {
      indexes.add(firstIndex);
      continue;
    }

    if (!fieldCarriesValue(field)) {
      continue;
    }
    for (const rowName of amountRowNames) {
      const index = subGroupIndexOf(field.name, rowName);
      if (index !== null) {
        indexes.add(index);
        break;
      }
    }
  }

  return [...indexes].sort((a, b) => a - b);
}
