import { api } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';
import type { HeaderFieldReport } from 'src/types/headerFieldReport';

/**
 * Reads the Kopffeld-Check for one document — OBO-156.
 *
 * Read-only by contract: the endpoint opens documents that are mid-validation
 * and is reachable by people who may not change them, so there is deliberately
 * no write method on this service to add one to by accident.
 *
 * The 403 it can return is not a failure to retry. It carries a code —
 * `analytics_module_off` or `analytics_access_denied` — because the two send
 * the user to different settings pages, so the caller inspects the body rather
 * than showing one generic error.
 */
export default class HeaderFieldReportApiService extends AbstractApiService {
  public constructor({}) {
    super({});
  }

  public async getForDocument(docId: string): Promise<HeaderFieldReport> {
    const url = `${api.header_field_report}/${encodeURIComponent(docId)}/header-field-report`;
    return super.get(url, {});
  }
}
