<!--
  "Gehört zu Analytics" — OBO-156, mockup page 5.

  The small offer shown when the org has no active Analytics subscription.
  It does not sell anything itself: "Freischalten" emits `unlock` and the
  button opens the existing SubscriptionDialog, which owns plans and pricing.
  "Später" only closes.
-->
<template>
  <q-dialog :model-value="modelValue" @update:model-value="close">
    <q-card
      class="w-[360px] max-w-[90vw] rounded-lg border border-border bg-card text-card-foreground"
      data-test="header-field-check-upsell"
    >
      <div class="flex flex-col gap-3 p-5">
        <div class="flex items-center gap-3">
          <span
            class="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary"
          >
            <Icon icon="mdi:lock-outline" width="20" height="20" />
          </span>
          <h2 class="m-0 text-base font-semibold leading-snug text-foreground">
            {{ $t('header_field_check_upsell_title') }}
          </h2>
        </div>
        <p class="m-0 text-sm text-muted-foreground">
          {{ $t('header_field_check_upsell_text') }}
        </p>
        <div class="mt-2 flex justify-end gap-2">
          <f-btn
            appearance="cancel"
            size="sm"
            :label="$t('header_field_check_upsell_later')"
            data-test="header-field-check-upsell-later"
            @click="close(false)"
          />
          <f-btn
            appearance="primary"
            size="sm"
            :label="$t('header_field_check_upsell_unlock')"
            data-test="header-field-check-upsell-unlock"
            @click="unlock"
          />
        </div>
      </div>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';

export default defineComponent({
  name: 'HeaderFieldCheckUpsellDialog',
  components: { Icon },
  props: {
    modelValue: { type: Boolean, required: true },
  },
  emits: ['update:modelValue', 'unlock'],
  methods: {
    close(value: boolean) {
      this.$emit('update:modelValue', value);
    },
    unlock() {
      this.$emit('update:modelValue', false);
      this.$emit('unlock');
    },
  },
});
</script>
