<!--
  "Kopffeld-Check", next to Save on the validation screen — OBO-156,
  mockup pages 1 and 5.

  Every visual decision comes from `buttonPresentation(state)`; this file
  holds no copy of any of it:

  * needs_subscription -> no button at all. `lock` is the one state where
                          something is for sale, and we do not advertise it
                          here: the lock icon read as "broken" rather than
                          "buy me". The upsell is still reachable from a
                          field's source badge (`fields-view.vue`), which is
                          where someone is actually asking about the feature.
  * module_off         -> no button at all, for anyone
  * not_offered        -> no button at all: no subscription and not an org
                          admin, so nothing to buy or grant (CORE-6434)
  * no_access          -> greyed, no lock, hint on hover/focus: an admin
                          grants it under Settings › Roles
  * loading            -> greyed and silent
  * ready              -> opens the report

  The hint sits on a wrapper around the button, not inside it: QTooltip never
  opens on a disabled button, and a disabled button is not in the tab order.
  The wrapper is focusable while it carries a hint and opens it on focus.
-->
<template>
  <div v-if="presentation.render && !presentation.lock" class="col-auto">
    <span
      v-if="!hideTrigger"
      data-test="header-field-check-hint-wrapper"
      class="inline-flex rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
      :class="presentation.disabled ? 'cursor-not-allowed *:pointer-events-none' : ''"
      :tabindex="presentation.hintKey ? 0 : undefined"
      :aria-describedby="presentation.hintKey ? hintId : undefined"
      @focus="showHint"
      @blur="hideHint"
    >
      <q-btn
        id="header_field_check"
        data-test="header-field-check-btn"
        flat
        class="px-6"
        :disable="presentation.disabled"
        :aria-label="$t('header_field_check_button_label')"
        @click="onClick"
      >
        <Icon
          icon="mdi:magnify-scan"
          width="22"
          height="22"
          class="icon-grey"
        />
      </q-btn>
      <!-- Icon-only: the name is in aria-label and on hover. -->
      <q-tooltip v-if="!presentation.hintKey">
        {{ $t('header_field_check_button_label') }}
      </q-tooltip>
      <q-tooltip
        v-if="presentation.hintKey"
        :model-value="hintVisible"
        max-width="300px"
        @update:model-value="hintVisible = $event"
      >
        {{ $t(presentation.hintKey) }}
      </q-tooltip>
      <span v-if="presentation.hintKey" :id="hintId" class="sr-only">
        {{ $t(presentation.hintKey) }}
      </span>
    </span>

    <!-- Deliberately no `v-if` on docId: with one, a missing id silently
         un-renders the dialog and the button does nothing at all when
         clicked — indistinguishable from a broken build. The dialog handles
         an empty id itself and says so. -->
    <HeaderFieldCheckDialog v-model="reportOpen" :doc-id="docId" :date-fields="dateFields" />

    <HeaderFieldCheckUpsellDialog
      v-model="upsellOpen"
      @unlock="openSubscription"
    />

    <!-- Deliberately no `v-if`: the dialog fetches its plans in a watcher on
         the open flag, and that watcher is not immediate. Mounting it already
         open means the plan list is never fetched — the dialog then shows its
         fallback confirmation, and confirming subscribes the customer to a
         plan they were never shown. -->
    <subscriptionDialog
      v-model="subscriptionOpen"
      :settings="{}"
      :app-key="analyticsAppKey"
      setting-type="ANALYTICS_DASHBOARD"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';
import HeaderFieldCheckDialog from 'src/components/document/HeaderFieldCheckDialog.vue';
import HeaderFieldCheckUpsellDialog from 'src/components/document/HeaderFieldCheckUpsellDialog.vue';
import { useHeaderFieldCheck } from 'src/composables/useHeaderFieldCheck';
import {
  buttonPresentation,
  type HeaderFieldCheckButtonPresentation,
} from 'src/utils/header-field-check-access';
import { CONSTANTS } from 'src/constants';

export default defineComponent({
  name: 'HeaderFieldCheckButton',
  components: {
    Icon,
    subscriptionDialog,
    HeaderFieldCheckDialog,
    HeaderFieldCheckUpsellDialog,
  },
  props: {
    docId: { type: String as PropType<string>, default: '' },
    /** The fields configured as a date, passed on to the report. */
    dateFields: { type: Array as PropType<string[]>, default: () => [] },
    /** CORE-6161: the toolbar folded into "...", which calls onClick itself; the dialogs stay mounted. */
    hideTrigger: { type: Boolean, default: false },
  },
  setup() {
    const { state, ensureLoaded } = useHeaderFieldCheck();
    return { state, ensureLoaded };
  },
  data() {
    return {
      reportOpen: false,
      upsellOpen: false,
      subscriptionOpen: false,
      hintVisible: false,
      hintId: 'header-field-check-hint',
      analyticsAppKey: CONSTANTS.analytics_dashboard,
    };
  },
  computed: {
    presentation(): HeaderFieldCheckButtonPresentation {
      return buttonPresentation(this.state);
    },
  },
  watch: {
    // A hint left open from the previous state would describe a state the
    // button is no longer in.
    'presentation.hintKey'() {
      this.hintVisible = false;
    },
  },
  mounted() {
    void this.ensureLoaded();
  },
  methods: {
    onClick() {
      const { action } = this.presentation;
      if (action === 'report') this.reportOpen = true;
      else if (action === 'upsell') this.upsellOpen = true;
      // 'none': the click is dropped rather than queued. A report that opens
      // a second later, after the user has moved on, is worse than nothing.
    },
    openSubscription() {
      this.upsellOpen = false;
      this.subscriptionOpen = true;
    },
    showHint() {
      if (this.presentation.hintKey) this.hintVisible = true;
    },
    hideHint() {
      this.hintVisible = false;
    },
  },
});
</script>
