/**
 * Field Value Helper Utilities
 *
 * Issue #13605 Fix: Content Property Population
 *
 * The API returns field values in the 'content' property, but the frontend
 * expects them in 'formatted_value' and 'value'. These utilities ensure
 * field values are correctly populated by copying 'content' to these
 * properties when they are missing.
 */

/**
 * Field model interface representing a document field
 */
export interface FieldModel {
  name?: string;
  content?: unknown;
  formatted_value?: unknown;
  value?: unknown;
  [key: string]: unknown;
}

/**
 * Populates field values from the 'content' property when 'formatted_value'
 * and/or 'value' are missing.
 *
 * Issue #13605: API returns field values in 'content' property, but frontend
 * expects 'formatted_value' and 'value'. This function copies 'content' to
 * these properties when they are undefined or null.
 *
 * @param field_model - The field model to populate values for
 * @returns The modified field model with populated values, or the original
 *          value if field_model is null/undefined
 *
 * @example
 * // With content but missing formatted_value and value
 * const field = { name: 'invoice_number', content: '911890158' };
 * populateFieldValuesFromContent(field);
 * // Result: { name: 'invoice_number', content: '911890158', formatted_value: '911890158', value: '911890158' }
 *
 * @example
 * // With existing values - no overwrite
 * const field = { name: 'total', content: '654.00', formatted_value: '$654.00', value: 654 };
 * populateFieldValuesFromContent(field);
 * // Result: unchanged - existing values preserved
 */
export function populateFieldValuesFromContent<T extends FieldModel | null | undefined>(
  field_model: T
): T {
  if (field_model) {
    // If formatted_value is not set but content exists, use content as the display value
    if (
      (field_model.formatted_value === undefined ||
        field_model.formatted_value === null) &&
      field_model.content !== undefined &&
      field_model.content !== null
    ) {
      field_model.formatted_value = field_model.content;
    }
    // Also populate value from content if not set
    if (
      (field_model.value === undefined || field_model.value === null) &&
      field_model.content !== undefined &&
      field_model.content !== null
    ) {
      field_model.value = field_model.content;
    }
  }
  return field_model;
}

/**
 * Checks if a field needs value population from content
 *
 * @param field_model - The field model to check
 * @returns true if the field has content but missing formatted_value or value
 */
export function needsValuePopulation(field_model: FieldModel | null | undefined): boolean {
  if (!field_model) {
    return false;
  }

  const hasContent = field_model.content !== undefined && field_model.content !== null;
  const missingFormattedValue =
    field_model.formatted_value === undefined || field_model.formatted_value === null;
  const missingValue = field_model.value === undefined || field_model.value === null;

  return hasContent && (missingFormattedValue || missingValue);
}
