<!--
  The Kopffeld-Check report — OBO-156.

  One question, answered per field: where does this value come from? Left is
  what the page said, right is what the screen shows, between them whoever
  changed it. The layout is doing the explaining: a long row is a value that
  travelled far from the document, a short one never moved.

  Every label comes from the server as a translation KEY. The web app does not
  map `extraction_method` to a source itself — a second copy of that mapping
  is how the badge and the insights panel drifted apart, and it is why half
  the rule-extracted fields showed no origin at all.
-->
<template>
  <q-dialog :model-value="modelValue" @update:model-value="close" full-width>
    <q-card class="header-field-check bg-card text-foreground">
      <q-toolbar class="secondary-toolbar" data-test="header-field-check-actions">
        <q-toolbar-title class="text-white">{{ $t('header_field_check_report_title') }}</q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="close"
          class="text-white"
          :aria-label="$t('close')"
          data-test="header-field-check-close"
          @click="close(false)"
        />
      </q-toolbar>

      <q-card-section v-if="loading" class="flex flex-col items-center gap-2 py-10 text-muted-foreground">
        <q-spinner size="32px" />
        <span class="text-xs">{{ $t('loading') }}</span>
      </q-card-section>

      <q-card-section v-else-if="errorMessage">
        <div
          role="alert"
          class="rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-destructive"
        >
          {{ errorMessage }}
        </div>
      </q-card-section>

      <!-- Only the table body scrolls; title, filters and search stay put. -->
      <q-card-section v-else-if="report" class="header-field-check__body">
        <HeaderFieldReportView :report="report" :date-fields="dateFields" />
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref, watch, type PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { Icon } from '@iconify/vue';
import HeaderFieldReportApiService from 'src/services/document/HeaderFieldReportApiService';
import type { HeaderFieldReport } from 'src/types/headerFieldReport';
import HeaderFieldReportView from 'src/components/document/HeaderFieldReportView.vue';
import { logger } from 'src/utils/logger';

export default defineComponent({
  name: 'HeaderFieldCheckDialog',
  components: { HeaderFieldReportView, Icon },
  props: {
    modelValue: { type: Boolean, required: true },
    docId: { type: String as PropType<string>, required: true },
    /** The fields configured as a date, shown in the user's date format. */
    dateFields: { type: Array as PropType<string[]>, default: () => [] },
  },
  emits: ['update:modelValue'],
  setup(props, { emit }) {
    const { t } = useTranslate();
    const report = ref<HeaderFieldReport | null>(null);
    const loading = ref(false);
    const errorMessage = ref('');

    /**
     * Which request is allowed to write the result.
     *
     * Open, close while the request is still in flight, reopen: two requests
     * are now racing. Without this counter the older one wins if it lands
     * second — replacing the fresh report with a stale one, or clearing a
     * successful report with its own late failure — and either of them also
     * clears `loading` while the newer request is still running.
     */
    let requestGeneration = 0;


    async function load() {
      const generation = ++requestGeneration;
      loading.value = true;
      errorMessage.value = '';
      // No document, nothing to report on. Said out loud rather than
      // returning quietly: a silent no-op here is what made the button look
      // dead when it was handed the wrong id.
      if (!props.docId) {
        report.value = null;
        errorMessage.value = t.value('header_field_check_load_failed');
        loading.value = false;
        return;
      }
      try {
        const service = new HeaderFieldReportApiService({});
        const result = await service.getForDocument(props.docId);
        if (generation !== requestGeneration) return;
        report.value = result;
      } catch (error) {
        if (generation !== requestGeneration) return;
        logger.warn('[HEADER-FIELD-CHECK] report load failed', error);
        report.value = null;
        errorMessage.value = t.value('header_field_check_load_failed');
      } finally {
        if (generation === requestGeneration) loading.value = false;
      }
    }

    watch(
      () => props.modelValue,
      (open) => {
        // Reloaded on every open rather than cached: the user reaches this
        // from a screen where they have just been editing, and a cached
        // answer describing the document as it was before the last save is
        // worse than a second of spinner.
        if (open) void load();
      },
      { immediate: true },
    );

    function close(value: boolean) {
      emit('update:modelValue', value === true);
    }





    return {
      report,
      loading,
      errorMessage,
      close,
    };
  },
});
</script>

<style lang="scss" scoped>
/* Layout here, not as classes: Quasar's .flex adds flex-wrap: wrap and beats
   Tailwind's flex-nowrap, which pushed the body out of view. */
.header-field-check {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  max-width: 1200px;
  /* Quasar caps a dialog card at 80vh, but the cap alone does nothing: the
     content inside still overflows unless a child owns the scrolling. Stated
     explicitly here at the same number so the two cannot drift apart. */
  max-height: 80vh;
}

.header-field-check__body {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}
</style>
