<template>
<div class="sub-group-area rounded-lg border border-border overflow-hidden">
  <div class="flex items-center justify-between bg-muted px-3 py-2 text-sm font-medium text-foreground border-b border-border">
    <span># {{ currentField.subGroupCount }} {{ $t(currentField.translation_key) }} {{ currentField.indexByType }}</span>
    <Icon
      icon="mdi:plus-box-outline"
      class="size-4 cursor-pointer text-muted-foreground hover:text-foreground"
      v-if="currentField.isParent"
      @click="duplicateGroup(groupIndex, itemIndex)"
    />
    <Icon
      icon="mdi:minus"
      class="size-4 cursor-pointer text-muted-foreground hover:text-foreground"
      v-else
      @click="removeSubGroup(itemIndex)"
    />
  </div>
  <div class="w-full bg-card p-3">

    <template v-for="(element, elementIndex) in formLayout[groupIndex].rows[itemIndex].rows" :key="`div-${elementIndex}`">
      <div v-if="!element.is_hidden && !formBuilderConfigModel[element.name].is_hidden && (element.visibile == undefined || element.visibile)" class="display-block field-padding " :style="'width:' + element.elementWidth  + '%'">

        <component :is="element.fieldType" :currentField="element" :isReadOnly="isReadOnly" :fieldName="element.name" :groupIndex="groupIndex"
          @inputClicked="htmlElementClick" @inputValueChanges="onInputValueChanges" @applyFuzzySearch="masterDataSearchByField" @updateModel="updateModel"  >
        </component>
      </div>
    </template>
  </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { useFormBuilderStore } from 'src/store/main';
import { VueDraggableNext } from 'vue-draggable-next';
import Label from 'src/formBuilder/form_elements/FormElementLabel.vue';
import LineItemTable from 'src/pages/TableExtraction/LineItemTable.vue';
import CheckBox from 'src/formBuilder/form_elements/FormElementCheckBox.vue';
import ExportButton from 'src/formBuilder/form_elements/FormElementButton.vue';
import TextInput from 'src/formBuilder/form_elements/FormElementTextInput.vue';
import EnumInput from 'src/formBuilder/form_elements/FormElementEnumInput.vue';
import validationButtonPanelHelper from 'src/formBuilder/validationButtonPanelHelper';
import MultiCheckBox from 'src/formBuilder/form_elements/FormElementMultiCheckBox.vue';
import PoMatchButton from 'src/formBuilder/form_elements/ButtonFormElements/PoMatch.vue';
import InvoiceButtons from 'src/formBuilder/form_elements/FormElementInvoiceButtons.vue';
import AmountButtonsPanel from 'src/formBuilder/form_elements/FormElementAmountFields.vue';
import SaveRulesButton from 'src/formBuilder/form_elements/ButtonFormElements/SaveRules.vue';
import TableOfCheckboxes from 'src/formBuilder/form_elements/FormElemenTableOfCheckboxes.vue';
import RejectDocument from 'src/formBuilder/form_elements/ButtonFormElements/RejectDocument.vue';
import HorizontalSeparator from 'src/formBuilder/form_elements/FormElementHorizontalSeparator.vue';
import QRCodeExtractedFields from 'src/formBuilder/form_elements/FormElementQRCodeExtractedFields.vue';
import AutoAccountingButton from 'src/formBuilder/form_elements/ButtonFormElements/AutoAccounting.vue';
import AditionalAmountButtonsPanel from 'src/formBuilder/form_elements/FormElementAdditionalAmountFields.vue';
import ExportWithoutValidation from 'src/formBuilder/form_elements/ButtonFormElements/ExportWithoutValidation.vue';
export default defineComponent({
  el: 'fields_designer',
  mixins: [helperMixin, validationButtonPanelHelper],
  emits: [
    'inputClicked',
    'inputValueChanges',
    'updateModel',
    'applyFuzzySearch',
  ],
  props: {
    isPanelSection: {
      type: Boolean,
      default: false,
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
    currentField: {
      type: Object,
      default: new Object(),
    },
  },
  data() {
    return {};
  },
  components: {
    Label,
    CheckBox,
    TextInput,
    EnumInput,
    ExportButton,
    MultiCheckBox,
    LineItemTable,
    PoMatchButton,
    InvoiceButtons,
    RejectDocument,
    SaveRulesButton,
    TableOfCheckboxes,
    AmountButtonsPanel,
    HorizontalSeparator,
    AutoAccountingButton,
    QRCodeExtractedFields,
    ExportWithoutValidation,
    AditionalAmountButtonsPanel,
    draggable: VueDraggableNext,
  },

  methods: {
    htmlElementClick(fieldName: string) {
      this.$emit('inputClicked', fieldName);
    },
    onInputValueChanges(fieldName: string, fieldType: string) {
      this.$emit('inputValueChanges', fieldName, fieldType);
    },
    updateModel(newField: any, isChildElement = false) {
      this.$emit('updateModel', newField, isChildElement);
    },
    masterDataSearchByField(field: any) {
      this.$emit('applyFuzzySearch', field);
    },

    removeSubGroup(index: number) {
      const subGroup = this.formLayout[this.groupIndex].rows[index];
      const customEvent = new CustomEvent('remove_sub_group_items', {
        detail: { items: subGroup.rows },
      });

      document.dispatchEvent(customEvent);
      this.formLayout[this.groupIndex].rows.splice(index, 1);

      this.prepareIndexesForSubGroups(this.groupIndex);
    },
    duplicateGroup(groupIndex: number, itemIndex: number) {
      if (!this.duplicateSubGroup(groupIndex, itemIndex, '', true)) {
        notify.error(this.$t('previous_field_group_is_empty'));
        return;
      }

      this.prepareLayoutForTemplate();
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formLayout,
      activeFieldName,
      renderComponent,
      formBuilderConfigModel,
    } = storeToRefs(form_builder_store);

    const { getElementWidth, duplicateSubGroup, prepareIndexesForSubGroups } =
      form_builder_store;

    return {
      formLayout,
      activeFieldName,
      renderComponent,
      formBuilderConfigModel,

      getElementWidth,
      duplicateSubGroup,
      prepareIndexesForSubGroups,
    };
  },
});
</script>

<style lang="scss" scoped>
.sub-group-area {
  width: 100%;
}
</style>
