/** The icon and colours of one extraction method, if it has any. */
export function originSource(source: string | null | undefined): OriginSource | undefined {
  return ORIGIN_SOURCES.find((entry) => entry.source === source);
}

/** Every method the value passed through, the reading engine included. */
export function usedSources(entry: HeaderFieldEntry | null | undefined): Set<string> {
  const used = new Set<string>();
  if (entry?.source) used.add(entry.source);
  for (const step of entry?.chain ?? []) if (step?.source) used.add(step.source);
  return used;
}

const UNUSED_TILE_CLASSES = 'text-muted-foreground opacity-50';
const UNUSED_TILE_COLOR = 'var(--muted-foreground)';

/**
 * All sources as tiles: the one the current value comes from, the ones the
 * value passed through, and the rest greyed out — so a value the AI read and
 * master data then replaced shows both at a glance.
 */
export function sourceTiles(
  entry: HeaderFieldEntry | null | undefined,
): SourceTile[] {
  const used = new Set<string>();
  // entry.source is the engine that read the value; the last sourced step made what the field says now.
  let final = entry?.source ?? '';
  if (final) used.add(final);
  for (const step of entry?.chain ?? []) {
    if (!step?.source) continue;
    used.add(step.source);
    final = step.source;
  }
  return ORIGIN_SOURCES.map(({ source, icon, color, final: finalClasses }) => {
    const use: SourceUse =
      source === final ? 'final' : used.has(source) ? 'used' : 'unused';
    return {
      source,
      icon,
      use,
      labelKey: `extraction_source.${source.toLowerCase()}`,
      color: use === 'unused' ? UNUSED_TILE_COLOR : color,
      classes: use === 'final' ? finalClasses : use === 'unused' ? UNUSED_TILE_CLASSES : '',
    };
  });
}

/**
 * The rows the report shows, in the order the payload has them: the reader
 * compares them against the document in front of them. An empty field is a
 * count, not a row — except a required one, since something has to go there.
 */
export function rowFields(
  report: HeaderFieldReport | null | undefined,
): HeaderFieldEntry[] {
  return (report?.fields ?? []).filter(
    (entry) => !!entry && (entry.status !== 'empty' || entry.is_required === true),
  );
}

/**
 * The field the hero is about.
 *
 * `worst_field` names a field by `name`, and a name that is not in `fields`
 * is no field at all: the hero is dropped rather than built from a name with
 * no values behind it.
 */
export function heroField(
  report: HeaderFieldReport | null | undefined,
): HeaderFieldEntry | null {
  const name = report?.summary?.worst_field;
  if (!name) return null;
  const entry = (report?.fields ?? []).find((field) => field?.name === name) ?? null;
  // The card says "does not match the document". That is only true of a value
  // the document does not carry as shown — the red tone. A script rewrite or
  // an exact master-data replacement is "changed on the way": amber, a row
  // (OBO-156 part 7). So is an unchanged field that merely needs review
  // (found on dev: worst_field named such a field). A required field nothing
  // filled is red but has no value to compare, so it stays a row too.
  if (!entry || rowTone(entry) !== 'bad' || !entry.current_value) return null;
  return entry;
}

/** One piece of a displayed value: text, and whether the lookup hit it. */
export interface HighlightPart {
  text: string;
  hit: boolean;
}

/**
 * The displayed value, split at the span the lookup actually matched.
 *
 * The mark is the whole point of the hero: it shows where inside
 * "06O051001" the "1001" from the page is. A span that is missing, empty,
 * out of order or outside the value is refused — the value comes back
 * unmarked. A half-right highlight is worse than none, because it teaches the
 * reader to distrust the marks.
 */
export function highlightParts(
  value: string | null | undefined,
  span: [number, number] | null | undefined,
): HighlightPart[] {
  if (!value) return [];
  if (!Array.isArray(span)) return [{ text: value, hit: false }];

  const [start, end] = span;
  const valid =
    Number.isInteger(start) &&
    Number.isInteger(end) &&
    start >= 0 &&
    end > start &&
    end <= value.length;
  if (!valid) return [{ text: value, hit: false }];

  const parts: HighlightPart[] = [];
  if (start > 0) parts.push({ text: value.slice(0, start), hit: false });
  parts.push({ text: value.slice(start, end), hit: true });
  if (end < value.length) parts.push({ text: value.slice(end), hit: false });
  return parts;
}

/**
 * What the field is called.
 *
 * The label is what the user configured and what the mockup shows; the name
 * is the internal key. A payload from before the label was added falls back
 * to the name — showing the raw name is honest, showing nothing is not.
 */
export function entryLabel(entry: HeaderFieldEntry | null | undefined): string {
  if (!entry) return '';
  // Same rule as the validation screen (displayFieldLabel): a translation of
  // the field name wins, then the org's own field_label (the server's
  // `label`, when it is more than the name), then the name. Without this the
  // report printed "invoice_id" next to a screen that says "Invoice number".
  const orgLabel = entry.label && entry.label !== entry.name ? entry.label : '';
  const label = displayFieldLabel.methods.displayFieldLabel.call(
    displayFieldLabel.methods,
    { field_name: entry.name, field_label: orgLabel },
  );
  return label || entry.name;
}

/** The tone a station's number badge and box carry. */
export type StationTone = 'neutral' | 'warn' | 'bad' | 'ok' | 'result';

/**
 * One station of "Herkunft des Wertes" — mockup page 2.
 *
 * Only the fields of its own stage are filled. Every one of them is either
 * read from the payload or `null`: a station never states a number, a page or
 * a value the payload did not carry.
 */
/** What the saved rule matched on, and the rules it beat. */
export interface RuleDetail {
  weight: number | null;
  /** How closely the page matched the training, 0..100. */
  score: number | null;
  labelLeft: string | null;
  labelAbove: string | null;
  /** Whether the trained label words were found next to the value. */
  labelFound: boolean | null;
  positionKey: string | null;
  trainedBy: string | null;
  trainedOn: string | null;
  rivals: Array<{ value: string; weight: number; score: number }>;
}

export interface OriginStation {
  /** 1-based, counted over the stations that exist. */
  number: number;
  stage: HeaderFieldStage;
  tone: StationTone;
  /** Whether this station is one of those that changed the value. */
  changesValue: boolean;
  /** document: the page, when recorded. */
  page: number | string | null;
  /** document: how the page text was obtained, as a label key. */
  textSourceKey: string;
  /** document / result: the value at that point. */
  value: string;
  /** document: false when no earlier value was recorded at all. */
  valueKnown: boolean;
  /** extraction / transform / lookup: the station's title key. */
  titleKey: string;
  /** extraction: the server's source label key for the chip. */
  sourceKey: string;
  /** extraction: confidence in whole percent, when recorded. */
  confidence: number | null;
  /** extraction: the rule that produced the value, when recorded. */
  ruleId: string | null;
  /** extraction: a trained rule took the text over as it stood on the page. */
  ruleTookTextAsIs: boolean;
  /** extraction, trained rule: weight, match and competing rules. */
  rule: RuleDetail | null;
  /** extraction, e-invoice: the XML element and the format. */
  xml: { tag: string; format: string | null } | null;
  /** transform */
  directional: boolean;
  struck: string | null;
  next: string | null;
  values: string[];
  scriptLabel: string | null;
  /** lookup */
  fromValue: string | null;
  toParts: HighlightPart[];
  dataset: string | null;
  matchKindKey: string | null;
  /** lookup, substring: the text that was searched for inside the records. */
  needle: string | null;
  /** lookup: the configured lookup's name. */
  lookupName: string | null;
  /** lookup: what started it, as a label key. */
  triggerKey: string | null;
  /** lookup: the fields it searched with. */
  searchInputs: Array<{ name: string; label: string; value: string; learned: boolean }>;
  /** lookup: it ran after another lookup had filled one of its inputs. */
  afterOtherLookup: boolean;
  /** lookup: this field was filled from a record another field found. */
  filledAlong: boolean;
  /** lookup: the field whose value found the record, when it is another field. */
  triggeredBy: { label: string; value: string | null } | null;
  /** lookup: the record used, by its matched column and value or its id. */
  record: { column: string | null; value: string | null; id: string | null } | null;
  /** lookup: the record column this value was copied from. */
  lookupColumn: string | null;
  /** lookup: "1 of N" — only when the payload counted the candidates. */
  hits: { hits: number; total: number } | null;
  /** result: what the same record filled into other fields. */
  drives: Array<{ name: string; label: string; value: string }>;
}

/** The match kinds that have a `match_kind_<kind>` label. */
const KNOWN_MATCH_KINDS = ['exact', 'prefix', 'substring', 'alternate', 'unknown'];

/**
 * Confidence in whole percent.
 *
 * The engines disagree on the scale: some store 0..1, some 0..100. A value up
 * to 1 is read as a fraction. Anything that is not a finite number is no
 * confidence at all — the chip is dropped rather than showing "0 %".
 */
export function confidencePercent(value: number | null | undefined): number | null {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return Math.round(value <= 1 ? value * 100 : value);
}

function blankStation(stage: HeaderFieldStage): Omit<OriginStation, 'number'> {
  return {
    stage,
    tone: 'neutral',
    changesValue: false,
    page: null,
    textSourceKey: '',
    value: '',
    valueKnown: true,
    titleKey: '',
    sourceKey: '',
    confidence: null,
    ruleId: null,
    ruleTookTextAsIs: false,
    rule: null,
    xml: null,
    directional: false,
    struck: null,
    next: null,
    values: [],
    scriptLabel: null,
    fromValue: null,
    toParts: [],
    dataset: null,
    matchKindKey: null,
    needle: null,
    lookupName: null,
    triggerKey: null,
    searchInputs: [],
    afterOtherLookup: false,
    filledAlong: false,
    triggeredBy: null,
    record: null,
    lookupColumn: null,
    hits: null,
    drives: [],
  };
}

const TEXT_SOURCE_KEYS: Record<string, string> = {
  ocr: 'header_field_check_text_source_ocr',
  text_layer: 'header_field_check_text_source_text_layer',
  electronic_document: 'header_field_check_text_source_electronic',
};

const TRIGGER_KEYS: Record<string, string> = {
  auto_trigger: 'header_field_check_lookup_trigger_auto',
  search: 'header_field_check_lookup_trigger_search',
};

const POSITION_KEYS: Record<string, string> = {
  matched: 'header_field_check_rule_position_matched',
  different_position: 'header_field_check_rule_position_moved',
};

function finite(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function filled(value: string | null | undefined): string | null {
  const text = typeof value === 'string' ? value.trim() : '';
  return text || null;
}

/** The winning rule from the explanation; without one only the stored weight is known. */
export function ruleDetail(
  entry: HeaderFieldEntry,
  explanation: FieldExplanation | null | undefined,
): RuleDetail {
  const candidates = explanation?.candidates ?? [];
  const winner = candidates.find((candidate) => candidate?.is_winner) ?? null;
  const label = winner?.score_breakdown?.label;
  return {
    weight: finite(winner?.rule_weight) || finite(entry.rule_weight),
    score: winner ? finite(winner.score) : null,
    labelLeft: filled(winner?.word_left),
    labelAbove: filled(winner?.word_above),
    labelFound:
      winner && (filled(winner.word_left) || filled(winner.word_above))
        ? (finite(label) ?? 0) > 0
        : null,
    positionKey: (winner && POSITION_KEYS[winner.position_match]) || null,
    trainedBy: filled(winner?.trained_by_name) || filled(winner?.trained_by_email),
    trainedOn: filled(winner?.last_modified_on),
    rivals: candidates
      .filter((candidate) => candidate && !candidate.is_winner && filled(candidate.content))
      .slice(0, 3)
      .map((candidate) => ({
        value: String(candidate.content).trim(),
        weight: finite(candidate.rule_weight) ?? 0,
        score: finite(candidate.score) ?? 0,
      })),
  };
}

function extractionTitleKey(step: HeaderFieldStep): string {
  if (step.source === 'TRAINED_RULE') return 'header_field_check_station_rule';
  if (step.source === 'AI') return 'header_field_check_station_ai';
  if (step.source === 'ELECTRONIC_DOCUMENT') return 'header_field_check_station_electronic';
  return step.source_label_key ?? '';
}

function transformTitleKey(step: HeaderFieldStep): string {
  if (step.source !== 'SCRIPT') return 'header_field_check_station_transform';
  // "shortens" is a claim about the two values, so it is only made when the
  // new value really is a piece of the old one.
  if (
    step.directional &&
    typeof step.from === 'string' &&
    typeof step.to === 'string' &&
    step.to.length < step.from.length &&
    step.from.includes(step.to)
  ) {
    return 'header_field_check_station_script_shortens';
  }
  return 'header_field_check_station_script_changes';
}

function lookupTitleKey(step: HeaderFieldStep): string {
  if (step.match_quality === 'exact') return 'header_field_check_station_lookup_exact';
  return step.match_quality === 'partial'
    ? 'header_field_check_station_lookup_partial'
    : 'header_field_check_station_lookup_unverified';
}

/**
 * The value's journey as numbered stations.
 *
 * The document station is always there — it is built from the entry itself,
 * so a value nobody recorded reads as "not recorded" instead of vanishing.
 * Extraction, transform and lookup appear only when the chain carries them.
 * The closing "now in the field" station appears when something happened on
 * the way (or the page value is unknown, or the record filled other fields):
 * for a value that came through untouched it would only repeat station 1.
 *
 * `fields` is the report's field list, used to name the fields the record
 * also filled. Without it those fields are named by their key.
 */
export function originStations(
  entry: HeaderFieldEntry | null | undefined,
  fields: HeaderFieldEntry[] | null | undefined = [],
  explanation: FieldExplanation | null = null,
): OriginStation[] {
  if (!entry) return [];
  const chain = entry.chain ?? [];
  const stations: Array<Omit<OriginStation, 'number'>> = [];

  const documentStation = blankStation('document');
  documentStation.page = entry.page ?? null;
  const textSource = chain.find((step) => step?.stage === 'document')?.text_source;
  documentStation.textSourceKey = (textSource && TEXT_SOURCE_KEYS[textSource]) || '';
  documentStation.valueKnown = entry.document_value_known !== false;
  documentStation.value = documentStation.valueKnown ? (entry.document_value ?? '') : '';
  stations.push(documentStation);

  const byName = new Map<string, HeaderFieldEntry>(
    (fields ?? []).filter(Boolean).map((field): [string, HeaderFieldEntry] => [field.name, field]),
  );

  for (const step of chain) {
    if (!step) continue;
    // A value master data wrote outright was never read off the page; the lookup station says it.
    if (step.stage === 'extraction' && step.source === 'MASTER_DATA') continue;
    if (step.stage === 'extraction') {
      const station = blankStation('extraction');
      station.titleKey = extractionTitleKey(step);
      station.sourceKey = step.source_label_key ?? '';
      station.confidence = confidencePercent(entry.confidence);
      station.ruleId = entry.rule_id || null;
      station.ruleTookTextAsIs =
        step.source === 'TRAINED_RULE' &&
        entry.document_value_known !== false &&
        typeof step.value === 'string' &&
        step.value === entry.document_value;
      if (step.source === 'TRAINED_RULE') station.rule = ruleDetail(entry, explanation);
      const xml = explanation?.xml_sources?.[0];
      if (step.source === 'ELECTRONIC_DOCUMENT' && filled(xml?.short_tag)) {
        station.xml = { tag: String(xml?.short_tag), format: filled(xml?.document_format) };
      }
      stations.push(station);
    } else if (step.stage === 'transform') {
      const station = blankStation('transform');
      station.tone = 'warn';
      station.titleKey = transformTitleKey(step);
      station.scriptLabel = step.script?.label || null;
      station.directional = step.directional === true;
      if (station.directional) {
        station.struck = step.from ?? null;
        station.next = step.to ?? null;
        station.changesValue = step.from !== step.to;
      } else {
        station.values = (step.values ?? []).filter((v) => typeof v === 'string');
        station.changesValue = true;
      }
      stations.push(station);
    } else if (step.stage === 'lookup') {
      const station = blankStation('lookup');
      const quality = step.match_quality;
      station.tone = quality === 'exact' ? 'ok' : quality === 'partial' ? 'bad' : 'warn';
      station.titleKey = lookupTitleKey(step);
      station.fromValue = step.from_known === false ? null : (step.from ?? null);
      station.toParts = highlightParts(step.to, step.match_span);
      station.dataset = step.dataset || null;
      station.matchKindKey =
        step.match_kind && KNOWN_MATCH_KINDS.includes(step.match_kind)
          ? `match_kind_${step.match_kind}`
          : null;
      station.needle =
        quality === 'partial' && step.match_kind === 'substring' ? station.fromValue : null;
      station.hits =
        typeof step.candidate_count === 'number' && Number.isFinite(step.candidate_count)
          ? { hits: step.candidate_count > 0 ? 1 : 0, total: step.candidate_count }
          : null;
      station.changesValue = typeof step.to === 'string' && step.to !== step.from;
      station.lookupName = filled(step.lookup_name);
      station.triggerKey = step.trigger ? (TRIGGER_KEYS[step.trigger] ?? null) : null;
      station.searchInputs = (step.search_inputs ?? [])
        .filter((input) => input && filled(input.field))
        .map((input) => ({
          name: input.field,
          label: entryLabel(byName.get(input.field)) || input.field,
          value: input.value ?? '',
          learned: input.learned === true,
        }));
      station.afterOtherLookup = (finite(step.round) ?? 1) > 1;
      station.filledAlong = Boolean(step.source_field && step.source_field !== entry.name);
      if (station.filledAlong) {
        station.fromValue = null;
        station.needle = null;
        const driverName = String(step.source_field);
        const driver = byName.get(driverName);
        const driverStep = (driver?.chain ?? []).find((s) => s?.stage === 'lookup');
        const searched = station.searchInputs.find((input) => input.name === driverName);
        station.triggeredBy = {
          label: entryLabel(driver) || driverName,
          value:
            filled(searched?.value) ??
            (driverStep && driverStep.from_known !== false ? filled(driverStep.from) : null),
        };
      }
      const recordValue = filled(step.record_match_value);
      const recordId = filled(step.record_id);
      station.record =
        recordValue || recordId
          ? { column: filled(step.match_column), value: recordValue, id: recordId }
          : null;
      station.lookupColumn = filled(step.lookup_column);
      stations.push(station);
    }
  }

  const drives = (entry.drives ?? []).map((name) => ({
    name,
    label: entryLabel(byName.get(name)) || name,
    value: entry.drives_values?.[name] ?? '',
  }));

  const somethingHappened = stations.some((station) => station.changesValue);
  if (somethingHappened || !documentStation.valueKnown || entry.changed || drives.length) {
    const result = blankStation('result');
    result.tone = 'result';
    result.value = entry.current_value ?? '';
    result.drives = drives;
    stations.push(result);
  }

  return stations.map((station, index) => ({ ...station, number: index + 1 }));
}

/** The numbers of the stations that changed the value, for the intro. */
export function changedStationNumbers(stations: OriginStation[]): number[] {
  return stations.filter((station) => station.changesValue).map((s) => s.number);
}

/**
 * What the user can do about the value.
 *
 * Resetting needs a page value that is known and differs from the screen —
 * "reset to a value nobody recorded" would reset to a guess. Picking another
 * record only makes sense when a lookup picked this one.
 */
export function originActions(entry: HeaderFieldEntry | null | undefined): {
  restoreTo: string | null;
  searchMasterData: boolean;
} {
  if (!entry) return { restoreTo: null, searchMasterData: false };
  const known = entry.document_value_known !== false;
  const restoreTo =
    known && (entry.document_value ?? '') !== (entry.current_value ?? '')
      ? (entry.document_value ?? '')
      : null;
  const searchMasterData = (entry.chain ?? []).some((step) => step?.stage === 'lookup');
  return { restoreTo, searchMasterData };
}

/** A step a script took: a rewrite, or a value a script produced itself. */
function isScriptStep(step: HeaderFieldStep | null | undefined): boolean {
  return step?.stage === 'transform' || step?.source === 'SCRIPT';
}

/**
 * The wording of the reset button in "Herkunft des Wertes".
 *
 * The screen restores the snapshot it took before the master-data lookup, and
 * that snapshot is taken after the document scripts ran. When a script acted
 * before the lookup, the value put back is the script's, not the page's —
 * "reset to the document value" would be false, so the button says "before
 * the master-data lookup" instead.
 */
export function restoreLabelKey(entry: HeaderFieldEntry | null | undefined): string {
  const chain = entry?.chain ?? [];
  const lookupAt = chain.findIndex((step) => step?.stage === 'lookup');
  if (lookupAt > 0 && chain.slice(0, lookupAt).some(isScriptStep)) {
    return 'header_field_check_restore_before_lookup';
  }
  return 'header_field_check_origin_restore';
}

/** The explanation of the report, on the docs site. */
export const HEADER_FIELD_CHECK_DOCS_URL =
  'https://docs.docbits.com/end-user-and-partner-section/end-user-section/validation-screen/header-field-check';
