  methods: {
    /**
     * Check if user has view access to a field based on ACL permissions
     * Field is visible if permission >= READ_ONLY
     */
    hasFieldViewAccess(fieldId: string): boolean {
      return Acl.hasFieldPermission(this.record?.doc_type, fieldId, FieldPermission.READ_ONLY);
    },

    /**
     * Check if a field should be read-only based on ACL permissions
     * Field is read-only if permission is exactly READ_ONLY
     */
    isFieldReadOnly(fieldId: string): boolean {
      return Acl.isFieldPermission(this.record?.doc_type, fieldId, FieldPermission.READ_ONLY);
    },

    assignColorToFields() {
      let counter = 0;
      this.fieldColors.forEach((value, key) => {
        const colorIndex = counter % this.info_panel_chip_colors.length;
        this.fieldColors.set(key, this.info_panel_chip_colors[colorIndex]);
        counter++;
      });
    },
    downloadFile() {
      try {
        let path =
          DOC2API_URL +
          '/' +
          this.record['doc_path'] +
          '?' +
          this.tokenQueryParam;
        if (!path) {
          return;
        }

        // Assuming 'path' is the URL to the file
        fetch(path)
          .then((response) => response.blob())
          .then((blob) => {
            // Create a Blob URL
            const blobUrl = URL.createObjectURL(blob);
            // Create an anchor element
            const link = document.createElement('a');
            link.href = blobUrl;
            // Set the file name (you may need to extract this from the response headers)
            link.download = this.record['filename'];
            // Append the link to the document
            document.body.appendChild(link);
            // Trigger a click on the link to start the download
            link.click();
            // Remove the link from the document
            document.body.removeChild(link);
            // Revoke the Blob URL to free up resources
            URL.revokeObjectURL(blobUrl);
          })
          .catch((error: any) => {
            logError('Error downloading file:', error);
          });

        // var link = document.createElement('a');
        // // link.download = row['filename'];
        // link.setAttribute('download', row['filename']);
        // link.href = path;
        // document.body.appendChild(link);
        // link.click();
        // // Cleanup the DOM
        // document.body.removeChild(link);
      } catch (err) {
        logError(err);
      }
    },
    initDefaultValues() {
      this.isFormBuilderMode = false;
      this.formBuilderModel = {};
      this.formBuilderConfigModel = {};
      this.lookup_loading_fields = {} as dynamicObj;
      this.freeze_fields_change_event = false;
    },

    reloadTable() {
      this.renderKey++;
    },
    async init() {
      if (this.is_sep_view && this.get_cached_data_id === this.docId) {
        await this.setRecordFromCache();
      }

      // Wait for doc_type to be available before fetching layout template
      // This prevents fetching wrong template when doc_type is not yet loaded
      const maxWaitMs = 5000;
      const pollIntervalMs = 100;
      let waitedMs = 0;
      if (!this.record?.doc_type) {
        console.log('[init] Waiting for doc_type to be loaded...');
      }
      while (!this.record?.doc_type && waitedMs < maxWaitMs) {
        await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
        waitedMs += pollIntervalMs;
      }
      if (waitedMs > 0 && this.record?.doc_type) {
        console.log('[init] doc_type loaded after', waitedMs, 'ms:', this.record.doc_type);
      }

      if (!this.record?.doc_type) {
        console.error('[init] doc_type not available after waiting', maxWaitMs, 'ms');
        notify.error(
          'Document type could not be loaded. Please refresh the page. Document ID: ' +
            this.docId,
        );
        this.hideLoading();
        return;
      }

      await this.getFormBuilderLayout();
      await this.populateListsAndValues();
      if (!this.isModelReady()) {
        console.error('Document layout validation failed:', {
          docId: this.docId,
          layout_template_id: this.layout_template_id,
          formBuilderModel: this.formBuilderModel,
          formLayout: this.formLayout,
          formLayoutOrignal: this.formLayoutOrignal,
        });
        // Skip the duplicate generic toast if we already surfaced the
        // specific "layout is empty" message in getFormBuilderLayout().
        if (!this.layoutEmptyHandled) {
          notify.error(
            'Document does not have layout. Please configure it properly in the layout builder. Document ID: ' +
              this.docId,
          );
        }
        this.layoutEmptyHandled = false;
        this.hideLoading();
        return;
      }

      if (this.record?.doc_type == 'INVOICE') {
        this.setConversionFields();
        this.fieldCaluclations();
      }
      if (this.record) {
        this.record.apply_script_triggered_on_field = '';
      }

      this.renderComponent = true;
      // this.$emit('getImageDetails');

      // find first group to foucs on
      const groupIndex = this.findGroupToFocus(0);
      const field_name = this.getFirstFieldOfGroup(String(groupIndex));

      await this.setLineItemDetails();

      this.createScriptCalculateDebounceFunc();
      await this.$nextTick();
      this.$emit('setSplitterModel', this.isExtenedPanel);

      this.viewLoadCompleted();
      this.$emit('onFieldLoad', field_name, true);

      this.DOC_SCRIPT_MODULE = await this.getSetting(this.doc_script_module_setting);
      if (
        this.record?.classification?.method != 'model' &&
        this.record?.extraction_method == 'ELECTRONIC_DOCUMENT'
      ) {
        this.selectEDocIcon();
      }
    },

    createScriptCalculateDebounceFunc() {
      this.debounceScriptCalculateFunc = debounce(() => {
        logInfo('debounceScriptCalculateFunc called');
        this.applyScript();
      }, 3000);
    },

    updateScriptRequest() {
      if (
        !this.debounceScriptCalculateFunc ||
        typeof this.debounceScriptCalculateFunc.cancel != 'function'
      ) {
        return;
      }

      this.updateRequestId();
      this.debounceScriptCalculateFunc.cancel();
    },

    createNewScriptRequest() {
      this.updateScriptRequest();
      this.createScriptCalculateDebounceFunc();
      logInfo('debounceScriptCalculateFunc canceled and created new one');
      this.debounceScriptCalculateFunc();
    },
    viewLoadCompleted() {
      const stickyArea = $('.validation-sticky-area') as HTMLElement;
      const notStickyArea = $('.not-sticky-area') as HTMLElement;

      if (stickyArea && notStickyArea) {
        notStickyArea.style.paddingTop = stickyArea.clientHeight + 20 + 'px';
      }
      // this.focusFirstFieldOnGroup();

      const el_field_scrolle = $('#field_scrolle');
      if (el_field_scrolle) {
        el_field_scrolle.addEventListener('scroll', this.handleScroll);
      }
    },

    prepareMediTable(fieldDef: any) {
      this.formBuilderConfigModel[fieldDef.name] = Object.assign({}, fieldDef);

      if (!this.record.tables || !this.record.tables[0]) {
        this.record.tables = [];

        let tableData = {
          name: fieldDef.name,
          rows: [],
        };

        this.formBuilderModel[fieldDef.name] = Object.assign({}, tableData);
        return;
      }

      let tableObj = {};

      this.record.tables.forEach((table: any) => {
        if ((table.name = fieldDef.name)) {
          tableObj = Object.assign({}, table);
          return;
        }
      });

      this.formBuilderModel[fieldDef.name] = Object.assign({}, tableObj);
    },
    prepareMultiCheckBox(fieldDef: any, field_model: any, field_name: string) {
      this.formBuilderConfigModel[fieldDef.name] = Object.assign({}, fieldDef);
      if (!field_model) {
        this.formBuilderModel[field_name] = [];
        this.formBuilderModel[field_name].page = '';
        this.formBuilderModel[field_name].color = '';
        this.formBuilderModel[field_name].score = '';
        this.formBuilderModel[field_name].value = '';
        this.formBuilderModel[field_name].coords = [];
        this.formBuilderModel[field_name].groupList = [];
        this.formBuilderModel[field_name].confidence = '';
        this.formBuilderModel[field_name].formatted_value = '';
        return;
      }
      if (field_model.highlight_field) {
        field_model.highlight_field = false;
        this.addFieldToHighlight(field_name);
      }
      this.formBuilderModel[field_name] = Object.assign({}, field_model);
    },
    prepareCheckboxesTable(fieldDef: any, data: any, layoutSettings: any) {
      fieldDef.tableBodyRows.forEach(
        (tableBodyRow: any, bodyRowsIndex: any) => {
          tableBodyRow.forEach((tableBodyColumn: any, bodyColumnIndex: any) => {
            let field_name = tableBodyColumn.name;

            // replace setting with updated field settings
            if (layoutSettings.hasOwnProperty(field_name)) {
              Object.assign(
                tableBodyColumn,
                this.cleanLayoutSettings(layoutSettings[field_name]),
              );
            }

            this.prepareModel(tableBodyColumn, data[field_name], field_name);
          });
        },
      );
    },
    prepareSubGroup(fieldDef: any, data: any, layoutSettings: any) {
      if (fieldDef.rows.length == 0) {
        return;
      }

      const subGroups = fieldDef.rows;

      for (let subgroup of subGroups) {
        let field_name = subgroup.name ? subgroup.name : subgroup.field_name;

        // replace setting with updated field settings
        if (layoutSettings.hasOwnProperty(field_name)) {
          Object.assign(
            subgroup,
            this.cleanLayoutSettings(layoutSettings[field_name]),
          );
        }

        this.prepareModel(subgroup, data[field_name], field_name);
      }
    },
    makeModel() {
      let groupWithsubGroup: number | null = null;

      this.fieldListToHighlight = [];

      // Add defensive null check for formLayoutOrignal
      if (!this.formLayoutOrignal || !Array.isArray(this.formLayoutOrignal)) {
        console.error(
          'makeModel: formLayoutOrignal is not available or not an array',
        );
        return Promise.resolve();
      }

      this.formLayout = JSON.parse(JSON.stringify(this.formLayoutOrignal));

      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record !== undefined) {
          // Defensive null check for fields array - prevents silent crash if API response is malformed
          if (!this.record?.fields || !Array.isArray(this.record.fields)) {
            console.error('makeModel: record.fields is undefined or not an array', {
              docId: this.docId,
              recordKeys: this.record ? Object.keys(this.record) : 'undefined',
              hasData: this.record?.hasOwnProperty('data'),
            });
            resolve(null);
            return;
          }

          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
            this.fieldsNotDisplayed[value.name] = value;
          });

          // prepare the list with updated field settings
          let layoutSettings = this.getUpdatedFieldSettings();
          let groupKey = '';

          // Add defensive null check for formLayout
          if (!this.formLayout || !Array.isArray(this.formLayout)) {
            console.error(
              'makeModel: formLayout is not available or not an array',
            );
            resolve(null);
            return;
          }

          for (const [index, group] of this.formLayout.entries()) {
            if (group.short_cut_key_2) {
              groupKey = group.short_cut_key_1 + group.short_cut_key_2;
              this.groupShortCutMap.set(groupKey, index);
            }

            // Add defensive null check for group.rows
            if (!group.rows || !Array.isArray(group.rows)) {
              console.warn(
                `makeModel: group.rows is not available for group ${index}`,
              );
              continue;
            }

            // for(let fieldDef of group.rows) {
            for (let [itemIndex, fieldDef] of group.rows.entries()) {
              let field_name = fieldDef.name
                ? fieldDef.name
                : fieldDef.field_name;

              if (
                fieldDef.fieldType === formBuilderInputTypes.TABLE_OF_CHECKBOXES
              ) {
                this.prepareCheckboxesTable(fieldDef, data, layoutSettings);
                continue;
              }

              if (
                fieldDef.fieldType === formBuilderInputTypes.EXTRACTED_TABLE
              ) {
                this.prepareMediTable(fieldDef);
                continue;
              }

              if (
                fieldDef.fieldType === formBuilderInputTypes.MULTI_CHECK_BOX
              ) {
                this.prepareMultiCheckBox(
                  fieldDef,
                  data[field_name],
                  field_name,
                );
                continue;
              }

              if (fieldDef.fieldType === formBuilderInputTypes.SUB_GROUP) {
                groupWithsubGroup = index;
                this.prepareSubGroup(fieldDef, data, field_name);

                if (fieldDef.isParent) {
                  if (!fieldDef.rows || fieldDef.rows.length == 0) {
                    continue;
                  }

                  this.prepareChildSubGroups(index, itemIndex, fieldDef.rows);
                }
                continue;
              }

              // replace setting with updated field settings
              if (layoutSettings.hasOwnProperty(field_name)) {
                const globalSetting = layoutSettings[field_name];
                const prevHidden = fieldDef.is_hidden || globalSetting.is_hidden;
                const prevReadonly = fieldDef.is_readonly || globalSetting.is_readonly;
                fieldDef = Object.assign(fieldDef, this.cleanLayoutSettings(globalSetting));
                
                fieldDef.is_hidden = prevHidden;
                fieldDef.is_readonly = prevReadonly;
              }

              this.prepareModel(fieldDef, data[field_name], field_name);
            }

            if (group.name === GROUP_NAMES.charges) {
              this.handleChargesFieldsVisibility(group);
            }
          }

          if (Object.keys(this.fieldsNotDisplayed).length >= 0) {
            this.record.fields.forEach((field: any, index: any) => {
              if (this.fieldsNotDisplayed.hasOwnProperty(field.name)) {
                this.record.fields[index].is_valid = true;
                delete this.fieldsNotDisplayed[field.name];
              }

              if (!this.formBuilderConfigModel.hasOwnProperty(field.name)) {
                // Not on the layout template, so never rendered: a required
                // error can only be reported out of band (see setFieldErrors).
                this.prepareModel({ not_in_layout: true }, data[field.name], field.name);
              }
            });
          }
          // Do it at the end when page is completly ready
          this.prepareLayoutForTemplate();
          this.setCalculatorFieldsColor();
          this.handleConfidenceAlert();
          this.setupLookup();
          if (this.record.tables) {
            this.setupTableLookup(
              this.record?.tables[0]?.lookup_configurations,
            );
          }

          if (groupWithsubGroup) {
            this.prepareIndexesForSubGroups(groupWithsubGroup);
          }
          this.$forceUpdate();
        }

        this.prepareLayoutData();
        this.assignColorToFields();
        resolve('done');

        if (this.highlightFieldsMode) {
          setTimeout(() => {
            this.highlightFields();
          }, 500);
        }
      });
    },
    addColorsToMap(fieldDef: any) {
      if (fieldDef.calculation_formula || fieldDef.calculator_formula) {
        const formula: string = fieldDef.calculation_formula
          ? fieldDef.calculation_formula
          : fieldDef.calculator_formula;
        const tempArray = formula.split(' ');
        let tempStrContainer = '';
        for (let index = 0; index < tempArray.length; index = index + 1) {
          tempStrContainer = tempArray[index].trim();
          if (tempArray[index].startsWith('[')) {
            tempStrContainer = tempStrContainer.replace('[', '');
            tempStrContainer = tempStrContainer.replace(']', '');
            this.fieldColors.set(tempStrContainer, '');
          }
        }
      }
    },
    setCalculatorFieldsColor() {
      Object.keys(this.formBuilderModel).forEach((fieldName: any) => {
        this.addColorsToMap(this.formBuilderConfigModel[fieldName]);
      });
    },
    async prepareModel(fieldDef: any, field_model: any, field_name: string) {
      if (field_model) {
        this.setColor(field_model, fieldDef);
      } else {
        field_model = this.createEmptyField(field_name, fieldDef.input_type);
      }

      // Issue #13605: Populate field values from 'content' property
      // See src/utils/fieldValueHelper.ts for implementation details
      populateFieldValuesFromContent(field_model);

      if (this.record.doc_type == 'INVOICE') {
        this.countAmountFieldsConfidence(field_model);
      }

      let fieldType = fieldDef.input_type
        ? fieldDef.input_type
        : fieldDef.fieldType;
      if (fieldType) {
        this.cleanCheckboxValue(field_model, fieldType.toLowerCase());
      }

      if (
        !fieldDef.hasOwnProperty('tabIndex') ||
        isUndefinedOrNull(fieldDef.tabIndex)
      ) {
        fieldDef.tabIndex = 0;
      }

      if (field_model.highlight_field) {
        field_model.highlight_field = false;
        this.addFieldToHighlight(field_name);
      }

      this.formBuilderModel[field_name] = [];
      this.formBuilderConfigModel[field_name] = [];

      this.formBuilderModel[field_name] = Object.assign({}, field_model); //JSON.parse(JSON.stringify(field_model));
      this.formBuilderConfigModel[field_name] = Object.assign({}, fieldDef); //JSON.parse(JSON.stringify(fieldDef));

      this.addColorsToMap(fieldDef);

      if (field_model.hasOwnProperty('is_required')) {
        this.formBuilderConfigModel[field_name].is_required = field_model.is_required;
      }

      if (field_model.hasOwnProperty('is_hidden')) {
        this.formBuilderConfigModel[field_name].is_hidden = field_model.is_hidden;
      }

      if (field_model.hasOwnProperty('is_readonly')) {
        this.formBuilderConfigModel[field_name].is_readonly = field_model.is_readonly;
      }

      if (field_model.hasOwnProperty('force_validation')) {
        this.formBuilderConfigModel[field_name].force_validation = field_model.force_validation;
        if (field_model.force_validation == true) {
          this.formBuilderModel[field_name].validation_code = 'FORCED_VALIDATION';
          this.formBuilderModel[field_name].validation_message = 'Validation required';
        }
      }

      this.setTabIndexInList(fieldDef);
      this.handleListofValues(field_name);
      this.broadcastFieldChange(field_name);
      this.setFieldError(field_name);

      // delete all those fields which are not hidden
      if (fieldDef.is_hidden === false) {
        if (this.fieldsNotDisplayed.hasOwnProperty(field_name)) {
          delete this.fieldsNotDisplayed[field_name];
        }
      }

      //Trigger Validation to Show validation errors after Save
      const { is_valid, input_error } = await textValidator.init(
        this.formBuilderModel[field_name],
        this.formBuilderConfigModel[field_name],
      );
      if (is_valid) {
        return;
      }
      this.formBuilderModel[field_name].input_error = input_error;
    },
    prepareModelListner(e: any) {
      this.prepareModel(e.detail.fieldDef, null, e.detail.field_name);
    },
    removeSubGroupItems(e: any) {
      if (!e.detail.items) {
        return;
      }

      const items = e.detail.items;
      this.record.fields = this.record.fields.filter(
        (field: any) =>
          !items.some((item: any) => field.name === item.field_name),
      );
    },
    prepareChildSubGroups(
      groupIndex: number,
      itemIndex: number,
      parentRows: any[],
    ) {
      // DU-223: discover copies from every field of the group, not only the
      // first — a valued tax_amount__1 without net_amount__1 is still exported.
      const rowNames = parentRows
        .map((row: any) => (row.name ? row.name : row.field_name))
        .filter(Boolean);
      const firstChildName = rowNames[0];
      const subGroupIndexes = findSubGroupIndexes(
        rowNames,
        this.record.fields,
      );

      for (const subGroupIndex of subGroupIndexes) {
        this.duplicateSubGroup(
          groupIndex,
          itemIndex,
          firstChildName + '__' + subGroupIndex,
        );
      }
    },

    setupLookup() {
      try {
        this.lookup_configurations = new Map();
        if (
          !this.record.hasOwnProperty('layout') ||
          !this.record.layout.lookup_configurations ||
          !Array.isArray(this.record.layout.lookup_configurations)
        ) {
          return;
        }

        this.autoTriggerFields = {};

        for (const [
          index,
          item,
        ] of this.record.layout.lookup_configurations.entries()) {
          if (!item.hasOwnProperty('fields') || !Array.isArray(item.fields)) {
            continue;
          }

          const itemTempObj = JSON.parse(JSON.stringify(item));

          this.lookupDictionary[item.id] = itemTempObj;
          this.lookupDictionary[item.id]['fields_obj'] = {};
          this.lookupDictionary[item.id]['fields'] = [];

          for (const [index, field] of item.fields.entries()) {
            if (
              !this.lookupDictionary[item.id]['fields_obj'][
                field.field_name
              ]
            ) {
              this.lookupDictionary[item.id]['fields_obj'][
                field.field_name
              ] = {};
            }

            this.lookupDictionary[item.id]['fields_obj'][
              field.field_name
            ] = field;
            this.lookupDictionary[item.id]['fields'].push(
              field,
            );

            if (field.auto_trigger) {
              if (!this.autoTriggerFields[field.field_name]) {
                this.autoTriggerFields[field.field_name] = [];
              }
              this.autoTriggerFields[field.field_name].push(item);
            }

            if (!field.is_searchable) {
              continue;
            }

            this.lookup_configurations.set(
              field.field_name,
              Object.assign(JSON.parse(JSON.stringify(field)), {
                id: item.id,
                lookup_dataset_name: item.lookup_dataset_name,
                // SAL-35: restored after DMB-414. Without it the manual lookup
                // sends no document_fields_data and a dynamic REST lookup
                // never fetches the records it is missing.
                request_fields: item.request_fields,
                fields: JSON.parse(JSON.stringify(item.fields)),
              }),
            );
          }
        }

        // auto trigger will be direclty get from lookup_configurations as its key is field name
        // this.check_for_auto_trigger();
      } catch (e) {
        logError(e);
      }
    },

    handleListofValues(field_name: string) {
      if (
        !this.formBuilderConfigModel[field_name].hasOwnProperty(
          'list_of_values',
        )
      ) {
        return;
      }

      this.addNameToLovList(
        this.formBuilderConfigModel[field_name].list_of_values,
      );
    },

    addFieldToHighlight(fieldName: string) {
