    async handleCOA() {
      if (this.isReadOnly) {
        this.$router.push('/certificate-of-analysis/' + this.record.doc_id);
        return;
      }

      let valid_fields = true;
      this.record.fields.forEach((field: dynamicObj) => {
        if (field.name == 'supplier_id') {
          if (!field.content && !field.value) {
            valid_fields = false;
            return;
          }
        }
        if (field.name == 'supplier_name') {
          if (!field.content && !field.value) {
            valid_fields = false;
            return;
          }
        }
        if (field.name == 'customer_product_code') {
          if (!field.content && !field.value) {
            valid_fields = false;
            return;
          }
        }
      });

      if (!valid_fields) {
        notify.error(this.$t('please_check_some_values_are_missing'));
        return;
      }

      if (this.tb_version === null) {
        return;
      }

      if (!this.hasTable()) {
        notify.error(this.$t('table_not_found'));
        return;
      }

      try {
        this.showLoading();
        let saving_data_alert = notify.info(this.$t('saving_data'));
        const response: dynamicObj = await this.saveAndValidate();
        saving_data_alert();
        if (response.success === false) {
          const event = new CustomEvent('display_fields_errors', {});
          document.dispatchEvent(event);
          notifyValidationFailure(response.message, response);
          return;
        }

        this.$router.push('/certificate-of-analysis/' + this.record.doc_id);
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async navigateToPOMatch() {
      try {
        if (
          this.record.po_multi_matched &&
          this.record.po_multi_matched.length > 0 &&
          this.is_extracted_table_update
        ) {
          // Show popup
          this.showConfirmRemoveConnectionsDialog = true;
          this.resumeAfterConfirmDialog = this.navigateToPOMatch;
          return;
        }

        this.showLoading();
        const response: dynamicObj = await this.saveAndValidate();
        if (response.success === false) {
          const event = new CustomEvent('display_fields_errors', {});
          document.dispatchEvent(event);
          notifyValidationFailure(response.message, response);
          return;
        }

        const po_match_route = await this.getPOUrl(this.doctype);
        
        this.$router.push(po_match_route + this.record.doc_id);
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

