    handleButtons(connectionId: string) {
      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.reject
      ) {
        this.rejectDocument();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.save
      ) {
        this.saveData();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.po_match
      ) {
        this.handlePoMatch();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType == CONSTANTS.coa
      ) {
        this.handleCOA();
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.save_rules
      ) {
        logInfo('save rules');
        return;
      }

      if (
        this.formBuilderConfigModel[connectionId].exportType ==
        CONSTANTS.quotes_detail
      ) {
        this.handleQuotes();
        return;
      }

      // Export data
      this.record['export_parameters'] = {
        doc_export_status: this.formBuilderConfigModel[connectionId].exportType,
      };
      this.exportData();
    },

    poMatchButtonClicked() {
      if (this.tb_version === null) {
        return;
      }
    },

    updateFieldInFormBuilder(
      fieldElement: HTMLElement,
      getTextApiResponse: any,
    ) {
      let inputEl: HTMLInputElement | null = fieldElement.querySelector(
        '.' + this.connectionId + '_input',
      );
      if (!inputEl) {
        return;
      }

      const event = new CustomEvent('update_field_value', {
        detail: {
          input_class: this.connectionId + '_input',
          val: getTextApiResponse.formatted_value,
        },
      });
      inputEl.dispatchEvent(event);
    },

    updateFieldData(getTextApiResponse: any) {
      // Field that don't have a box, and you draw a box against them, you should set attribute of page number to that field
      let fieldElement: HTMLElement | null = $('#' + this.connectionId);
      fieldElement!.setAttribute('pageno', this.page.toString());

      if (this.record.doc_type == 'INVOICE') {
        if (
          getTextApiResponse.extracted_value &&
          Object.keys(getTextApiResponse.extracted_value).length !== 0
        ) {
          // this.hideLoading();
          this.openSelectionPopup(
            JSON.parse(JSON.stringify(getTextApiResponse)),
          );
          return;
        }
      }

      if (fieldElement) {
        this.updateFieldInFormBuilder(fieldElement, getTextApiResponse);
      }

      const componentType = this.getInputType(fieldElement as HTMLElement);

      // Handle formatted_value when it's an array of translation objects
      let formattedValue = getTextApiResponse.formatted_value;
      if (Array.isArray(formattedValue)) {
        const defaultEntry = formattedValue.find((item: any) => item.is_default);
        formattedValue = (defaultEntry || formattedValue[0])?.translated_value ?? '';
      }

      this.formBuilderModel[this.connectionId].value = getTextApiResponse.value;
      this.formBuilderModel[this.connectionId].formatted_value = formattedValue;
      this.formBuilderModel[this.connectionId].content =
        getTextApiResponse.text;
      this.formBuilderModel[this.connectionId].api_save = true;
      this.formBuilderModel[this.connectionId].score_description = '';
      this.formBuilderModel[this.connectionId].coords =
        getTextApiResponse.coords;

      if (getTextApiResponse && getTextApiResponse.multi_line === true) {
        this.formBuilderModel[this.connectionId].multi_line = true;
      } else {
        this.formBuilderModel[this.connectionId].multi_line = false;
      }

      if (componentType === 'checkbox') {
        this.formBuilderModel[this.connectionId].value = false;
        this.formBuilderModel[this.connectionId].formatted_value = false;
        this.formBuilderModel[this.connectionId].content = false;

        if (
          formattedValue &&
          String(formattedValue).toLowerCase() === 'x'
        ) {
          this.handleSingleSelection(this.connectionId);

          this.formBuilderModel[this.connectionId].value = true;
          this.formBuilderModel[this.connectionId].content = true;
          this.formBuilderModel[this.connectionId].formatted_value = true;
        }
      }

      // Field that don't have a box, and you draw a box against them, you should also set the value of this input in apiData
      // This would help us when we navigates between pages
      this.valueChangesOnRedraw(
        this.connectionId,
        getTextApiResponse.coords,
        this.page,
      );
      // this.handleLookupAutoTrigger(this.connectionId);
      this.$emit('enableOrDisableExportButton');

      this.$forceUpdate();
    },
    valueChangesOnRedraw(
      connectionId: string,
      coordinates?: any,
      page?: number,
    ) {
      let singleSelectionFields = [
        'stuck_checkbox',
        'paar_checkbox',
        'hose_checkbox',
      ];
      let fields_to_update: string[] = [];

      if (singleSelectionFields.includes(connectionId)) {
        fields_to_update = singleSelectionFields;
      } else {
        fields_to_update.push(connectionId);
      }

      if (coordinates && page) {
        this.prepareImportJson(fields_to_update, coordinates, page, 'AI');
        logInfo('valueChangesOnRedraw', fields_to_update);
      } else {
        this.prepareImportJson(fields_to_update);
      }

      this.$emit('removeOldMapiingsAndDrawNew', connectionId);

      this.$forceUpdate();
    },
    prepareImportJson(
      fields_to_update: string[],
      coordinates?: any,
      page?: number,
      extractionMethod?: string,
    ) {
      fields_to_update.forEach((connection_id: string) => {
        this.updateImportJson(
          connection_id,
          coordinates,
          page,
          extractionMethod,
        );
      });
    },

    updateImportJson(
      connectionId: string,
      coordinates?: any,
      page?: number,
      extractionMethod = '',
      restoringOriginal = false,
    ) {
      const restoreGeneration = this.restoreGenerations[connectionId] || 0;
      let found = false;
      const recordFields = Array.isArray(this.record?.fields)
        ? this.record.fields
        : [];
      recordFields.forEach(async (value: any) => {
        if (value.name === connectionId) {
          found = true;

          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign({}, value);
          }

          if (!value.hasOwnProperty('original_value')) {
            value['original_value'] = value.value;
          }

          if (coordinates || coordinates === null) {
            value.coords = coordinates;
          }

          if (page) {
            value.page = page;
          }
          if (extractionMethod) {
            value.extraction_method = extractionMethod;
          }

          value.is_valid = true;
          value.is_validated = true;

          let field = this.formBuilderModel[connectionId];
          if (!field) {
            return;
          }
          value.formatted_value = field.formatted_value;
          value.value = restoringOriginal ? field.value : (field.value ? field.value : field.formatted_value);
          value.content = field.content;

          if (field.input_error) {
            value.is_valid = false;
            value.is_validated = false;
          }

          if (this.formBuilderConfigModel[connectionId]?.parent_field_name) {
            value.parent_field_name =
              this.formBuilderConfigModel[connectionId].parent_field_name;
          }

          if (!restoringOriginal && !(field.hasOwnProperty('api_save') && field.api_save)) {
            value.value = field.formatted_value;
          }

          if (
            value.value != '' &&
            !restoringOriginal &&
            !(field.hasOwnProperty('api_save') && field.api_save) &&
            this.conversionFields.includes(field.name) &&
            this.amount_format_locale != 'en_US'
          ) {
            const convertedValue = await this.convertValueAccordingToLocale(
              value.value,
              this.amount_format_locale,
              'en_US',
            );
            if (restoreGeneration !== (this.restoreGenerations[connectionId] || 0)) return;
            value.value = convertedValue;
            value.float_value = +value.value;
          }

          value.color = CONSTANTS.success_border_left;
          if (value.extraction_method == 'MD') {
            value.color = 'extraction_method-border-left';
          } else if (value.extraction_method == 'CALCULATED') {
            value.color = 'extraction_method-calculated-border-left';
          }

          if (
            value.is_required &&
            (value.formatted_value == '' || value.formatted_value == null)
          ) {
            value.color = 'error-border-left';
          }

          if (
            !restoringOriginal && (isUndefinedOrNull(value.formatted_value) ||
            isEmptyString(value.formatted_value))
          ) {
            value.content = value.formatted_value;
            // DU-223: a cleared amount must not keep its old numeric value —
            // value, formatted_value and float_value stay one state.
            if (value.hasOwnProperty('float_value')) {
              value.float_value = null;
            }
          }

          if (this.isMultiLine()) {
            value.multi_line = true;
          } else {
            value.multi_line = false;
          }

          this.formBuilderModel[connectionId].is_valid = value.is_valid;
          this.formBuilderModel[connectionId].is_validated = value.is_validated;
          this.$emit('checkFieldInvalid', value);
          return;
        }
      });

      if (!found) {
        if (!Array.isArray(this.record.fields)) {
          this.record.fields = [];
        }
        if (!this.formBuilderModel[connectionId]) {
          return;
        }
        this.record.fields.push({});

        const field_index = this.record.fields.length - 1;
        this.record.fields[field_index].name = connectionId;
        this.record.fields[field_index].content =
          this.formBuilderModel[connectionId].content;
        // this.record.fields[this.record.fields.length - 1].confidence = 0.99;
        this.record.fields[field_index].formatted_value =
          this.formBuilderModel[connectionId].formatted_value;
        this.record.fields[field_index].value =
          this.formBuilderModel[connectionId].value;
        this.record.fields[field_index].original_value = '';
        this.record.fields[field_index].validation_code = '';
        this.record.fields[field_index].extraction_method = extractionMethod;
        this.record.fields[field_index].is_validated = true;
        this.record.fields[field_index].is_valid = true;
        this.record.fields[field_index].color = CONSTANTS.success_border_left;

        if (this.isMultiLine()) {
          this.record.fields[field_index].multi_line = true;
        } else {
          this.record.fields[field_index].multi_line = false;
        }

        if (this.formBuilderConfigModel[connectionId]?.parent_field_name) {
          this.record.fields[field_index].parent_field_name =
            this.formBuilderConfigModel[connectionId].parent_field_name;
        }

        if (coordinates) {
          this.record.fields[field_index].coords = coordinates;
        }

        if (page) {
          this.record.fields[field_index].page = page;
        }

        this.$emit('checkFieldInvalid', this.record.fields[field_index]);
      }
    },

    isMultiLine() {
      return Boolean(
        this.formBuilderModel &&
          this.formBuilderModel[this.connectionId] &&
          this.formBuilderModel[this.connectionId].hasOwnProperty(
            'multi_line',
          ) &&
          this.formBuilderModel[this.connectionId].multi_line === true,
      );
    },

    initTempFieldDelete() {
      if (!Array.isArray(this.record?.fields)) {
        return;
      }
      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === this.connectionId) {
          const update_attr = {
            color: null,
            coords: null,
            validation_code: null,
            value: '',
            formatted_value: '',
            content: '',
            page: null,
          };

          this.formBuilderModel[this.connectionId] = Object.assign(
            this.formBuilderModel[this.connectionId],
            update_attr,
          );
          delete this.formBuilderModel[this.connectionId].confidence;

          this.record.fields[index] = Object.assign(
            this.record.fields[index],
            update_attr,
          );
          delete this.record.fields[index].confidence;
        }
      });

      this.fieldCaluclations();
      this.saveOneFieldStateForAutotrigger(this.record, this.connectionId);
      // also remove page attribute from the field
      let fieldElement = $('#' + this.connectionId);
      if (fieldElement) {
        fieldElement.setAttribute('pageno', '');
      }
    },

    handleScroll() {
      this.$emit('handleScroll');
    },

    getInputType(fieldElement: HTMLElement) {
      return fieldElement.getAttribute('child_type') as string;
    },

    // =========================================================================================

    /**
     * OBO-156: what "reset" in the origin dialog would put back — the same
     * conditions FormElementTextInput uses for its undo icon, so the dialog
     * never offers a reset that onRestoreOriginal would silently skip.
     */
    originRestoreValue(): string | null {
      const name = this.originFieldName;
      const field: any = name ? this.formBuilderModel[name] : null;
      const original = field?.original;
      if (!original || !Object.prototype.hasOwnProperty.call(original, 'value')) {
        return null;
      }
      if (String(original.value) === String(field.value)) return null;
      if (this.formBuilderConfigModel[name]?.is_readonly) return null;
      return String(original.value ?? '');
    },

    /**
     * OBO-156 part 7: the badge goes through the same doors as the
     * Kopffeld-Check button — the origin dialog loads the same report.
     * `module_off` and `not_offered` never get here: the badge is plain
     * text then.
     */
    onOpenOrigin({ fieldName }: { fieldName: string }) {
      const action = originEntryAction(this.headerFieldCheckState);
      if (action === 'open') {
        this.originFieldName = fieldName;
        this.originDialogOpen = true;
      } else if (action === 'upsell') {
        this.originUpsellOpen = true;
      } else if (action === 'hint') {
        notify.info(this.$t('header_field_check_no_access_hint'));
      }
    },

    openOriginSubscription() {
      this.originUpsellOpen = false;
      this.originSubscriptionOpen = true;
    },

    onOriginSearchMasterData({ fieldName }: { fieldName: string }) {
      const fieldModel = this.formBuilderModel[fieldName];
      if (!fieldModel) return;
      this.masterDataSearchByField(fieldModel);
    },

    async onRestoreOriginal({ fieldName }: { fieldName: string }) {
      const field = this.formBuilderModel[fieldName];
      const config = this.formBuilderConfigModel[fieldName];
      if (!field || !config || this.isReadOnly || config.is_readonly ||
          this.isFieldReadOnly(config.id) ||
          this.lookup_loading_fields[fieldName]?.lookup_loading) return;

      const generation = (this.restoreGenerations[fieldName] || 0) + 1;
      this.restoreGenerations[fieldName] = generation;
      const restored = await restoreOriginalField({
        field, config,
        isCurrent: () => this.formBuilderModel[fieldName] === field &&
          this.restoreGenerations[fieldName] === generation,
        isAmount: this.conversionFields.includes(fieldName) || config.field_type?.toLowerCase() === 'amount',
        formatAmount: (value) => this.convertValueAccordingToLocale(value, 'en_US', this.amount_format_locale),
        formatDate: (value) => dateInput.format(value),
        recordFields: Array.isArray(this.record?.fields) ? this.record.fields : [],
        validate: (model, definition) => textValidator.init(model, definition),
        setColor: () => this.setColor(field, config),
        update: () => this.updateImportJson(fieldName, undefined, undefined, field.extraction_method, true),
      });
      if (restored) this.startTimer();
    },

    onInputValueChanges(fieldName: string, fieldType: string) {
      // if (this.freeze_fields_change_event) {
      //   return;
      // }
      let has_multiple_po_numbers = false;
      if (fieldType === 'delete_rule') {
        this.deleteRule(fieldName);
        return;
      } else if (fieldType === 'calculated') {
        this.updateImportJson(fieldName, null, this.page, 'calculated');
      } else if (fieldName == 'purchase_order') {
        this.record.is_purchase_order_changed = true;
        has_multiple_po_numbers =
          splitCommaSeparatedValues(
            this.formBuilderModel[fieldName]?.formatted_value,
          ).length > 1;
      }
      this.removeSelectedAreaOnImage(fieldName);

      if (this.isFieldScriptCalculated(fieldName)) {
        this.updateScriptRequest();
      } else {
        this.alreadyExecutedGroups = [];
        const needs_script_call = this.handleScriptForNonCalcField();
        // A multi-PO value is not a lookup key, so the auto trigger is skipped
        // and the PO tables are loaded instead.
        if (
          !needs_script_call &&
          this.autoTriggerFields[fieldName] &&
          !has_multiple_po_numbers
        ) {
          const currectDataSet = this.preapreAutoTriggerDataSet(fieldName);
          this.setAutoTriggerInitialFilters(fieldName);
          this.processAutoTriggerFields(currectDataSet);
        }
      }

      this.inputValueChanges(fieldName);
      if (has_multiple_po_numbers) {
        this.handlePoItems();
      }
      this.startTimer();
    },

    removeSelectedAreaOnImage(field_name: string) {
      if (this.isConfirmationBoxDisable) {
        const event = new CustomEvent('removeSelectedAreaOnImage', {});
        document.dispatchEvent(event);
        this.connectionId = field_name;
        this.removeConnectionFromModel(this.connectionId);
      }
    },

    removeConnectionFromModel(field_name: string) {
      this.record.fields.forEach((value: any, index: any) => {
        if (value.name === this.connectionId) {
          if (!value.hasOwnProperty('original')) {
            value['original'] = Object.assign(
              {},
              JSON.parse(JSON.stringify(value)),
            );
          }

          const update_attr = {
            color: null,
            coords: null,
            confidence: 0,
            validation_code: null,
          };

          this.formBuilderModel[this.connectionId] = Object.assign(
            this.formBuilderModel[this.connectionId],
            update_attr,
          );
          this.record.fields[index] = Object.assign(
            this.record.fields[index],
            update_attr,
          );
        }
      });
    },

    async getFormBuilderLayout() {
      try {
        await this.getLayoutTemplate({
          doc_id: this.record.doc_id || this.docId,
          layout_type: layout_types.field_validation,
          doc_type: this.record.doc_type,
          sub_doc_type: this.record.sub_doc_type,
          doc_origin: this.record.doc_origin,
          include_layout_json: true,
        });

        await this.applyLoadedLayout();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

    // Everything that has to happen once a layout is in the store, whether it
    // came from the initial load or from a post-save re-resolve.
    async applyLoadedLayout() {
      try {
        this.formLayoutOrignal = JSON.parse(JSON.stringify(this.formLayout));

        // Add validation for layout structure
        if (
          !this.formLayout ||
          !Array.isArray(this.formLayout) ||
          this.formLayout.length === 0
        ) {
          console.error('applyLoadedLayout: Invalid layout structure', {
            formLayout: this.formLayout,
            docId: this.docId,
          });
          // Backend now returns an empty layout instead of an error when
          // none is configured for the doc type — surface a clear,
          // actionable message instead of "layout not found".
          this.layoutEmptyHandled = true;
          notify.error(
            'Document layout is empty. Please configure it properly in the layout builder. Document ID: ' +
              this.docId,
          );
          return;
        }

        if (this.formLayout) {
          // Only call triggerlookupLovs if record.layout exists (Issue #13605)
          // Without this check, accessing undefined.lookup_lov_configurations crashes
          // and makeModel() never executes, resulting in 0 fields displayed
          if (this.record?.layout?.lookup_lov_configurations) {
            await this.triggerlookupLovs(
              this.record.layout.lookup_lov_configurations,
              '',
              true,
              '',
              false,
            );
          }
          await this.makeModel();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },
    updateModel(newField: any) {
      return;
    },

    isFieldScriptCalculated(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_script_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_script_on_change === true
      ) {
        return true;
      }

      return false;
    },

    isFieldhasWorkflowEnabled(field_name: string) {
      if (
        this.formBuilderConfigModel[field_name].hasOwnProperty(
          'run_workflow_on_change',
        ) &&
        this.formBuilderConfigModel[field_name].run_workflow_on_change === true
      ) {
        return true;
      }

      return false;
    },

    handleScriptCalculatedFields(field_name: string) {
      try {
        if (!this.isFieldScriptCalculated(field_name)) {
          return;
        }
        this.record.apply_script_triggered_on_field = field_name;

        this.updateScriptRequest();
        this.debounceScriptCalculateFunc();
      } catch (err) {
        logError(err);
      } finally {
      }
    },

    handleScriptForNonCalcField() {
      if (
        this.api_request_id !== '' &&
        this.record.hasOwnProperty('apply_script_triggered_on_field') &&
        this.record.apply_script_triggered_on_field
      ) {
        this.updateScriptRequest();
        this.debounceScriptCalculateFunc();
        return true;
      }
      return false;
    },

    scriptCalculateFuncWrapper(e: any) {
      let row_id = '';
      let column_name = '';
      if (e.detail.columnName) {
        column_name = e.detail.columnName;
      }
      if (e.detail.rowId) {
        row_id = e.detail.rowId;
      }
      this.record.apply_script_triggered_on_table_row = row_id;
      this.record.apply_script_triggered_on_table_field = column_name;
      this.debounceScriptCalculateFunc();
    },

    async applyScript() {
      try {
        this.auto_saved_done = false;
        this.auto_saving = true;
        this.script_api_timestamp = Date.now();
        const is_done = await this.applyScriptOnDocument();
        if (!is_done) {
          return;
        }

        let discard_response = false;

        for (const [field_name, fieldDef] of Object.entries(
          this.formBuilderModel,
        )) {
          let field_timestamp = 0;
          if (fieldDef.hasOwnProperty('update_timestamp')) {
            field_timestamp = fieldDef.update_timestamp;
          }
          if (field_timestamp > this.script_api_timestamp) {
            discard_response = true;
          }

          if (discard_response) {
            logInfo(
              'discard_response',
              field_name,
              fieldDef.formatted_value,
              field_timestamp,
              this.script_api_timestamp,
            );
          }
        }

        if (discard_response) {
          this.updateRequestId();
          this.createNewScriptRequest();
          return;
        }
        const script_changed_fields = this.getScriptChangedFields();
        await this.updateRecordAfterScript();

        this.$emit('setDocVersion');
        this.setDataToCache();
        this.saveFieldsStateForAutotrigger(this.record.fields);

        this.highlightFieldsMode = true;
        await this.makeModel();

        this.alreadyExecutedGroups = [];
        this.triggerlookupAfterScript(script_changed_fields);

        this.setFieldErrors(false);
        this.refreshCanvas();

        // if changed field is invoice_sub_type then remove accounting data
        if (
          script_changed_fields.some((item: any) =>
            item.name.startsWith(CONSTANTS.invoice_sub_type),
          )
        ) {
          this.removeAccountingData();
          this.saveData();
        }

        const event = new CustomEvent('prepare_rows', {});
        document.dispatchEvent(event);
      } catch (err) {
        logError(err);
      } finally {
        this.auto_saving = false;
        this.auto_saved_done = true;
        setTimeout(() => {
          this.auto_saved_done = false;
        }, 10000);
      }
    },
    triggerlookupAfterScript(script_changed_fields = [] as dynamicObj[]) {
      // this.handleLookupAutoTrigger(this.record.apply_script_triggered_on_field);

      let lookupDataSet = [] as any;

      if (this.autoTriggerFields[this.record.apply_script_triggered_on_field]) {
        lookupDataSet = this.preapreAutoTriggerDataSet(
          this.record.apply_script_triggered_on_field,
        );
        this.record.apply_script_triggered_on_field = '';
      }

      const lookUps = this.triggerScriptChangedFields(script_changed_fields);

      if (lookUps && lookUps.length > 0) {
        lookupDataSet.push(...lookUps);
      }

      this.processAutoTriggerFields(lookupDataSet);
    },

    async rejectDocument() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.showLoading();
        await this.saveData();
        const data = { request_type: 'reject' };
        const response = await documentDetailApiService.rejectDocument(
          data,
          this.docId,
        );
        if (response.success === false) {
          throw response.message;
        }

        notify.success(this.$t('MSG_SAVE'));
        if (response.success === true) {
          this.routeToDashboard();
        }
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    jumpToTable(event: any) {
      event.preventDefault();
      for (const [index, group] of this.formLayout.entries()) {
        if (!this.isGroupTable(index)) {
          continue;
        }
        this.focusOnTableGroup(index);
        break;
      }
    },

    triggerTableAddRow(event: any) {
      for (const [index, group] of this.formLayout.entries()) {
        if (!this.isGroupTable(index)) {
          continue;
        }

        const field = this.formLayout[index].rows[0];
        let fieldEl: HTMLElement | null =
          document!.querySelector('.' + field.name) ||
          document!.querySelector('#line_item_table');
        if (!fieldEl) {
          return;
        }
        if (fieldEl.id == 'line_item_table') {
          const tableEvent = new CustomEvent('trigger_add_row_extract_table', {
            detail: {},
          });
          fieldEl.dispatchEvent(tableEvent);
        } else {
          const tableEvent = new CustomEvent('trigger_add_row_ai_table', {
            detail: {},
          });
          fieldEl.dispatchEvent(tableEvent);
        }
        break;
      }
      event.preventDefault();
    },

    findGroupShortcutkey(event: any) {
      const key = event.key;
      const combKey_list = ['shift', 'alt'];

      const comb_key = combKey_list.find((comb_key: any) => {
        const mapIndex = comb_key + key;
        return this.groupShortCutMap.has(mapIndex);
      });
      return comb_key;
    },

    focusOnGroupFromMap(event: any) {
      if (this.groupShortCutMap.size === 0) {
        return;
      }

      const comb_key = this.findGroupShortcutkey(event);
      if (!comb_key) {
        return;
      }

      const mapIndex = comb_key + event.key;
      const groupIndex = this.groupShortCutMap.get(mapIndex);
      if (
        groupIndex === null ||
        groupIndex === undefined ||
        groupIndex === ''
      ) {
        return;
      }
      event.preventDefault();
      this.focusGroup(groupIndex, event);
    },

    isGroupTable(groupIndex: string) {
      if (!this.formLayout[groupIndex].rows[0]) {
        return false;
      }
      return (
        this.formLayout[groupIndex].rows[0].fieldType ===
        this.EXTRACTED_TABLE_TAB_PANELS
      );
    },

    focusGroup(groupIndex: string, event: any) {
      event.preventDefault();
      if (this.formLayout[groupIndex].rows.length === 0) {
        return;
      }

      if (this.isGroupTable(groupIndex)) {
        this.focusOnTableGroup(groupIndex);
        return;
      }

      const field_name = this.getFirstFieldOfGroup(groupIndex);
      if (!field_name) {
        return;
      }
      this.focusOnField(field_name);
    },

    getFirstFieldOfGroup(groupIndex: string) {
      let field_name = '';
      let exclude_field_types = ['CheckBox', 'TableOfCheckboxes'];
      exclude_field_types = exclude_field_types.concat(
        this.excluded_field_types,
      );

      const firstElement = this.formLayout[groupIndex].rows.find((row: any) => {
        return !exclude_field_types.includes(row.fieldType);
      });

      if (!firstElement) {
        return field_name;
      }

      field_name = firstElement.name;
      if (firstElement.hasOwnProperty('field_name')) {
        field_name = firstElement.field_name;
      }

      if (!field_name) {
        return '';
      }
      return field_name;
    },

    focusOnTableGroup(groupIndex: string) {
      const field = this.formLayout[groupIndex].rows[0];
      this.focusOnTable(field.name);
    },

    validateAllSectionFields(index: any) {
      if (this.isReadOnly) {
        return;
      }
      const section = this.formLayout[index];
      if (!section.hasOwnProperty('rows')) {
        logInfo('No rows found to validate in this section');
        return;
      }

      for (const fieldDef of section.rows) {
        this.validateField(fieldDef.field_name);
      }
    },

    selectFieldFromNextGroup(e: any) {
      let current_group_el = e.target.closest('[data-group-id]');

      // find first
      if (!current_group_el) {
        current_group_el = document.querySelector('[data-group-id]');
      }

      if (!current_group_el) {
        return;
      }

      const group_index = current_group_el.getAttribute('data-group-id');
      const next_group_index = Number(group_index) + 1;
      this.focusFirstFieldOnGroup(next_group_index);
    },

    validateAndSelectNextInvalidField(selectedwraperId: string) {
      let moveToNextFiled = false;
      let componentType = '';

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          if (subRow.fieldType == formBuilderInputTypes.SUB_GROUP) {
            for (const innerRow of subRow.rows) {
              let field_name = innerRow.field_name;
              let data_field = this.formBuilderModel[field_name];
              if (!data_field) {
                continue;
              }

              if (moveToNextFiled === true) {
                if (
                  innerRow.is_readonly == true ||
                  innerRow.is_hidden == true
                ) {
                  continue;
                }

                if (
                  data_field.is_valid == false ||
                  data_field.calculation_formula
                ) {
                  this.focusOnField(field_name);
                  moveToNextFiled = false;
                  return;
                }
              } else if (field_name === selectedwraperId) {
                moveToNextFiled = true;
                this.validateField(field_name);
                const parentDiv: HTMLElement | null = $('#' + field_name);
                componentType = this.getComponentType(field_name);
                if (componentType == '') {
                  parentDiv!.blur();
                } else {
                  const input: HTMLElement | null =
                    parentDiv!.querySelector(componentType);
                  input!.blur();
                }
              }
            }
            continue;
          }

          let field_name = subRow.field_name;
          let data_field = this.formBuilderModel[field_name];
          if (!data_field) {
            continue;
          }

          if (moveToNextFiled === true) {
            if (subRow.is_readonly == true || subRow.is_hidden == true) {
              continue;
            }

            if (
              data_field.is_valid == false ||
              data_field.calculation_formula
            ) {
              this.focusOnField(field_name);
              moveToNextFiled = false;
              return;
            }
          } else if (field_name === selectedwraperId) {
            moveToNextFiled = true;
            this.validateField(field_name);
            const parentDiv: HTMLElement | null = $('#' + field_name);
            componentType = this.getComponentType(field_name);

            if (componentType == '') {
              parentDiv!.blur();
            } else {
              const input: HTMLElement | null =
                parentDiv!.querySelector(componentType);
              input!.blur();
            }
          }
        }
      }
    },

    // CORE-6161: fold when the row overflows; unfold once the dropdowns as
    // they are now plus the buttons fit, measured fresh on every resize.
    updateToolbarCollapse() {
      const row = this.$refs.toolbarRow as HTMLElement | undefined;
      const classification = this.$refs.toolbarClassification as HTMLElement | undefined;
      if (!row || !classification) {
        return;
      }
      if (!this.toolbarCollapsed) {
        const contentWidth = this.toolbarContentWidth(row);
        if (contentWidth > row.clientWidth + 1) {
          this.toolbarButtonsWidth = contentWidth - classification.offsetWidth;
          this.toolbarCollapsed = true;
        }
        return;
      }
      if (row.clientWidth >= classification.scrollWidth + this.toolbarButtonsWidth) {
        this.toolbarCollapsed = false;
        this.$nextTick(() => this.updateToolbarCollapse());
      }
    },
    // Width the toolbar row's own items need, measured from their boxes rather
    // than row.scrollWidth. scrollWidth also counts decorations that hang off a
    // button (e.g. the validation assistant's count badge), which would fold the
    // toolbar although every button fits.
    toolbarContentWidth(row: HTMLElement): number {
      const left = row.getBoundingClientRect().left;
      let right = left;
      for (const child of Array.from(row.children)) {
        // q-resize-observer spans the row itself and carries no content.
        if (child.classList.contains('q-resize-observer')) {
          continue;
        }
        const rect = child.getBoundingClientRect();
        if (rect.width > 0 && rect.right > right) {
          right = rect.right;
        }
      }
      return right - left;
    },
    scriptMenuAvailable() {
      const script = this.$refs.scriptBtn as any;
      return (
        this.is_admin === true &&
        !this.isReadOnly &&
        this.DOC_SCRIPT_MODULE &&
        !!script &&
        (script.is_script_editor_available || script.selected_doc_type != '')
      );
    },
    toggleValidationAssistant() {
      document.dispatchEvent(new CustomEvent(TOGGLE_VALIDATION_ASSISTANT_EVENT));
    },

    // CORE-6161: "Zum Feld" from the validation assistant. A field folded
    // away behind "show more" is unfolded first, or there is nothing to focus.
    async focusBlockedField(event: Event) {
      const field_name = (event as CustomEvent).detail?.field_name;
      if (!field_name) {
        return;
      }
      this.unfoldField(field_name);
      await this.$nextTick();
      this.focusOnField(field_name, false);
      this.highlightField(field_name);
    },

    unfoldField(field_name: string) {
      for (const group of this.formLayout || []) {
        for (const row of group?.rows || []) {
          if (row?.name === field_name && row.visibile === false) {
            row.visibile = true;
          }
        }
      }
    },

    highlightField(field_name: string) {
      const target: HTMLElement | null = $('#' + field_name);
      if (target) {
        highlightElement(target);
      }
    },

    // CORE-6161: the validation assistant may only touch a field the user could edit by hand.
    assistantFieldGuard(field_name: string, requireTextInput: boolean): GuardResult {
      const config = this.formBuilderConfigModel?.[field_name];
      const element = findLayoutElement(this.formLayout, field_name);
      return checkFieldActionGuard({
        model: this.formBuilderModel?.[field_name],
        config,
        element,
        documentReadOnly: !!this.isReadOnly,
        formBuilderMode: !!this.isFormBuilderMode,
        aclReadOnly: config ? this.isFieldReadOnly(config.id) : false,
        canView: element ? this.hasFieldViewAccess(element.id) : false,
        lookupLoading: !!this.lookup_loading_fields?.[field_name]?.lookup_loading,
        requireTextInput,
      });
    },

    async revealAssistantField(field_name: string) {
      this.unfoldField(field_name);
      await this.$nextTick();
      this.highlightField(field_name);
    },

    // Sets the value like typing it would, then runs the normal change chain.
    async onAssistantSetFieldValue(event: Event) {
      const { field, value, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      let guard = this.assistantFieldGuard(field, true);
      if (!guard.ok) return replyFieldAction(requestId, guard);

      const config = this.formBuilderConfigModel[field];
      const prepared = await prepareFieldValue({
        value,
        isAmount:
          this.conversionFields.includes(field) ||
          config.field_type?.toLowerCase() === 'amount',
        isDate: config.field_type?.toLowerCase() === 'date',
        datePattern: useFormBuilderStore().getDocDateFormat(),
        formatAmount: (plain) =>
          this.convertValueAccordingToLocale(plain, 'en_US', this.amount_format_locale),
        formatDate: (date) => dateInput.format(date),
      });
      if (!prepared.ok) return replyFieldAction(requestId, prepared);

      // The formatters are async: the field may have changed or locked meanwhile.
      guard = this.assistantFieldGuard(field, true);
      if (!guard.ok) return replyFieldAction(requestId, guard);
      const model = this.formBuilderModel[field];
      if (prepared.formatted === model.formatted_value) {
        return replyFieldAction(requestId, { ok: false, reason: 'unchanged' });
      }
      // Changing it would wipe the accounting; that needs the user's own confirmation in the field.
      if (this.shouldConfirmAccountingReset(field)) {
        return replyFieldAction(requestId, { ok: false, reason: 'accounting_reset' });
      }

      const previous = snapshotField(model);
      await this.writeAssistantValue(field, prepared.formatted);
      await this.revealAssistantField(field);
      replyFieldAction(requestId, {
        ok: true,
        previous,
        applied: model.formatted_value,
        changes: [this.assistantChange(field, previous.formatted_value, 'set_value')],
      });
    },

    assistantFieldLabel(field: string): string {
      const config = this.formBuilderConfigModel?.[field];
      return (config && this.getFieldLabel(config, '')) || field;
    },

    assistantChange(field: string, from: unknown, kind: string) {
      return {
        field,
        label: this.assistantFieldLabel(field),
        from,
        to: this.formBuilderModel?.[field]?.formatted_value,
        kind,
        field_type: this.formBuilderConfigModel?.[field]?.field_type,
      };
    },

    async writeAssistantValue(field: string, formatted: string) {
      const model = this.formBuilderModel[field];
      const config = this.formBuilderConfigModel[field];
      model.formatted_value = formatted;
      model.update_timestamp = Date.now();
      model.input_error = '';
      if (formatted) {
        const { is_valid, input_error } = await textValidator.init(model, config);
        if (!is_valid) model.input_error = input_error;
      }
      this.onInputValueChanges(field, 'input');
    },

    async onAssistantConfirmField(event: Event) {
      const { field, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      const guard = this.assistantFieldGuard(field, false);
      if (!guard.ok) return replyFieldAction(requestId, guard);
      const previous = snapshotField(this.formBuilderModel[field]);
      this.validateField(field);
      await this.revealAssistantField(field);
      replyFieldAction(requestId, {
        ok: true,
        previous,
        changes: [{ field, label: this.assistantFieldLabel(field), kind: 'confirm_field' }],
      });
    },

    // Undo: the snapshot goes back through the same change path.
    async onAssistantRestoreField(event: Event) {
      const { field, previous, expected, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      const guard = this.assistantFieldGuard(field, false);
      if (!guard.ok) return replyFieldAction(requestId, guard);
      const model = this.formBuilderModel[field];
      const restorable = canRestoreSnapshot(model, previous, expected);
      if (!restorable.ok) return replyFieldAction(requestId, restorable);

      const valueChanged = model.formatted_value !== previous.formatted_value;
      if (valueChanged && this.shouldConfirmAccountingReset(field)) {
        return replyFieldAction(requestId, { ok: false, reason: 'accounting_reset' });
      }
      applySnapshot(model, previous);
      model.update_timestamp = Date.now();
      this.setColor(model, this.formBuilderConfigModel[field]);
      if (valueChanged) {
        this.onInputValueChanges(field, 'input');
      } else {
        this.updateImportJson(field);
      }
      await this.revealAssistantField(field);
      replyFieldAction(requestId, { ok: true });
    },

    // CORE-6161: the lookup a field belongs to — its search config, else its auto-trigger config.
    assistantLookupConfig(field: string) {
      const config = this.lookup_configurations?.get?.(field) || this.autoTriggerFields?.[field]?.[0];
      if (!config) return null;
      const dict = this.lookupDictionary?.[config.id];
      return dict ? { id: config.id, dict } : null;
    },

    assistantLookupChanges(before: dynamicObj, changed: string[]) {
      return changed.map((name) => this.assistantChange(name, before[name]?.formatted_value, 'set_value'));
    },

    // Applies the candidate the way a pick in the master-data dialog does (populatePopupData).
    async onAssistantApplyLookupCandidate(event: Event) {
      const { field, candidate_index, fills, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      let guard = this.assistantFieldGuard(field, false);
      if (!guard.ok) return replyFieldAction(requestId, guard);
      const lookup = this.assistantLookupConfig(field);
      if (!lookup) return replyFieldAction(requestId, { ok: false, reason: 'no_lookup' });
      const { id, dict } = lookup;

      this.alreadyExecutedGroups = [];
      const response = await this.loadAutoTriggerData({
        id,
        fieldName: field,
        lookup_dataset_name: dict.lookup_dataset_name,
      });
      const rows = Array.isArray(response?.data) ? response.data : [];
      if (!rows.length) return replyFieldAction(requestId, { ok: false, reason: 'no_candidates' });
      const row = rows[candidate_index];
      if (!candidateMatchesFills(row, dict.fields, fills, this.attributeKey)) {
        return replyFieldAction(requestId, { ok: false, reason: 'candidate_changed' });
      }
      guard = this.assistantFieldGuard(field, false);
      if (!guard.ok) return replyFieldAction(requestId, guard);

      const before = snapshotModels(this.formBuilderModel);
      this.lookupRestoreGenerations = { ...this.restoreGenerations };
      await this.populateMasterDataFields(dict, '', JSON.stringify(row), this.lookupRestoreGenerations);
      const dataset = [
        { lookup_dataset_name: dict.lookup_dataset_name, fieldName: field, triggerDataSet: false },
      ];
      const dependent = this.preapreAutoTriggerDataSet(field, dict.lookup_dataset_name);
      if (Array.isArray(dependent)) dataset.push(...dependent);
      await this.processAutoTriggerFields(dataset);
      this.startTimer();

      const changed = changedFields(before, this.formBuilderModel);
      await this.revealAssistantField(field);
      replyFieldAction(requestId, {
        ok: true,
        previous: pick(before, changed),
        applied: appliedValues(this.formBuilderModel, changed),
        undoable: changed.length > 0,
        changes: this.assistantLookupChanges(before, changed),
      });
    },

    // Runs the field's auto-trigger lookup like an edit does; a search-only lookup opens its dialog.
    async onAssistantRerunLookup(event: Event) {
      const { field, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      const guard = this.assistantFieldGuard(field, false);
      if (!guard.ok) return replyFieldAction(requestId, guard);

      if (this.autoTriggerFields?.[field]) {
        const before = snapshotModels(this.formBuilderModel);
        this.alreadyExecutedGroups = [];
        const dataset = this.preapreAutoTriggerDataSet(field);
        this.setAutoTriggerInitialFilters(field);
        await this.processAutoTriggerFields(dataset);
        const changed = changedFields(before, this.formBuilderModel);
        await this.revealAssistantField(field);
        return replyFieldAction(requestId, {
          ok: true,
          previous: pick(before, changed),
          applied: appliedValues(this.formBuilderModel, changed),
          undoable: changed.length > 0,
          changes: this.assistantLookupChanges(before, changed),
          notice: changed.length ? undefined : 'validation_assistant_action_lookup_unchanged',
        });
      }
      if (this.lookup_configurations?.get?.(field)) {
        this.masterDataSearchByField(this.formBuilderModel[field]);
        return replyFieldAction(requestId, {
          ok: true,
          undoable: false,
          notice: 'validation_assistant_action_lookup_dialog',
        });
      }
      replyFieldAction(requestId, { ok: false, reason: 'no_lookup' });
    },

    // Undo for lookups: every field it filled goes back, unless the user edited it since.
    async onAssistantRestoreFields(event: Event) {
      const { previous, expected, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      if (this.isReadOnly) return replyFieldAction(requestId, { ok: false, reason: 'document_read_only' });
      if (this.isFormBuilderMode) return replyFieldAction(requestId, { ok: false, reason: 'form_builder' });
      const plan = restorePlan(this.formBuilderModel, previous, expected);
      if (!plan.restore.length) return replyFieldAction(requestId, { ok: false, reason: 'changed_since' });
      if (plan.restore.some((name) => this.shouldConfirmAccountingReset(name))) {
        return replyFieldAction(requestId, { ok: false, reason: 'accounting_reset' });
      }
      for (const name of plan.restore) {
        const model = this.formBuilderModel[name];
        applyFieldSnapshot(model, previous[name]);
        model.update_timestamp = Date.now();
        this.setColor(model, this.formBuilderConfigModel[name]);
        this.updateImportJson(name, model.coords, this.page, model.extraction_method);
      }
      this.startTimer();
      replyFieldAction(requestId, { ok: true, applied: plan });
    },

    // Opens the classification confirmation preselected, like picking the type in the dropdown.
    onAssistantReclassify(event: Event) {
      const { doc_type, requestId } = (event as CustomEvent).detail || {};
      if (!requestId) return;
      if (this.isReadOnly) return replyFieldAction(requestId, { ok: false, reason: 'document_read_only' });
      if (this.isFormBuilderMode) return replyFieldAction(requestId, { ok: false, reason: 'form_builder' });
      const dropdown = useDropdownStore();
      const classification = useDocClassificationStore();
      const documentStore = useDocumentStore();
      const known = filterApiDocTypes(dropdown.active_doc_types_sub_types_list).some(
        (option: dynamicObj) => option.value === doc_type && !option.hasDocTypes,
      );
      if (!known) return replyFieldAction(requestId, { ok: false, reason: 'unknown_doc_type' });
      if (documentStore.selected_doc_type === doc_type) {
        return replyFieldAction(requestId, { ok: false, reason: 'same_doc_type' });
      }
      documentStore.selected_doc_type = doc_type;
      const subType = (dropdown.sub_types_list || []).find((v: dynamicObj) => v.value == doc_type);
      if (subType?.model_label_id) {
        classification.selected_custom_model_label = subType.model_label_id;
        classification.label_classification_popup = true;
      } else {
        classification.restart_classification_popup = true;
      }
      replyFieldAction(requestId, { ok: true, notice: 'validation_assistant_action_reclassify_open' });
    },

    focusOnField(field_name: string, start_timer = true, select_value = false) {
      const parentDiv: HTMLElement | null = $('#' + field_name);
      if (!parentDiv) {
        logError('cannot find field', field_name);
        return;
      }
      // For checkbox or non-input fields
      const componentType = this.getComponentType(field_name);
      if (componentType == '') {
        parentDiv.focus();
        if (start_timer) {
          this.startTimer();
        }
        return;
      }

      // For input fields
      const input: HTMLInputElement | null =
        parentDiv.querySelector(componentType);
      if (!input) {
        logError('cannot find field', componentType);
        return;
      }

      input.click();
      input.focus();
      this.scrollInToViewCenter(input);

      if (select_value) {
        input.select();
      }

      if (start_timer) {
        this.startTimer();
      }
    },

    selectNextField(selectedwraperId: string) {
      let moveToNextFiled = false;
      let componentType = '';
      const typesToExclude = ref([
        formBuilderInputTypes.LOV_INPUT,
        formBuilderInputTypes.ENUM_INPUT,
        formBuilderInputTypes.USER,
        formBuilderInputTypes.GROUP,
        formBuilderInputTypes.GROUP_DROPDOWN,
      ]);

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          if (subRow.fieldType == formBuilderInputTypes.SUB_GROUP) {
            for (const innerRow of subRow.rows) {
              let field_name =
                innerRow.fieldType == this.TEXT_INPUT
                  ? innerRow.field_name == undefined
                    ? innerRow.name
                    : innerRow.field_name
                  : innerRow.field_name;
              let data_field = this.formBuilderModel[field_name];
              if (!data_field) {
                continue;
              }

              if (moveToNextFiled === true) {
                if (
                  innerRow.is_readonly == true ||
                  innerRow.is_hidden == true ||
                  typesToExclude.value.includes(innerRow.fieldType)
                ) {
                  continue;
                }

                this.focusOnField(field_name);
                moveToNextFiled = false;
                return;
              } else if (field_name === selectedwraperId) {
                const parentDiv: HTMLElement | null = $('#' + field_name);
                componentType = this.getComponentType(field_name);
                // Getting input value
                const input: HTMLElement | null =
                  parentDiv!.querySelector(componentType);
                input!.blur();
                this.validateField(field_name);
                moveToNextFiled = true;
              }
            }

            continue;
          }
          let field_name =
            subRow.fieldType == this.TEXT_INPUT
              ? subRow.field_name == undefined
                ? subRow.name
                : subRow.field_name
              : subRow.field_name;
          let data_field = this.formBuilderModel[field_name];
          if (!data_field) {
            continue;
          }

          if (moveToNextFiled === true) {
            if (
              subRow.is_readonly == true ||
              subRow.is_hidden == true ||
              typesToExclude.value.includes(subRow.fieldType)
            ) {
              continue;
            }

            this.focusOnField(field_name);
            moveToNextFiled = false;
            return;
          } else if (field_name === selectedwraperId) {
            const parentDiv: HTMLElement | null = $('#' + field_name);
            componentType = this.getComponentType(field_name);
            // Getting input value
            const input: HTMLElement | null =
              parentDiv!.querySelector(componentType);
            input!.blur();
            this.validateField(field_name);
            moveToNextFiled = true;
          }
        }
      }
    },

    getNextTabIndex(tab_Index: number): number {
      let found_index = false;
      let next_index = 0;
      for (const [key, value] of Object.entries(this.fields_tabindex_mapping)) {
        const current_index = Number(key);

        if (found_index === true) {
          next_index = current_index;
          break;
        }

        if (tab_Index === current_index) {
          found_index = true;
        }
      }

      const fields = this.fields_tabindex_mapping[next_index];
      if (!fields || !Array.isArray(fields)) {
        return this.getNextTabIndex(next_index);
      }

      return next_index;
    },

    isFieldAvailableToFocus(field_name: string) {
      const field_el: HTMLElement | null = $('#' + field_name);
      if (!field_el) {
        return false;
      }
      return true;
    },

    // same index, field is not valid then move to next field
    getNextTabIndexField(tabIndex: number, field_name: string): string {
      try {
        const fields = this.fields_tabindex_mapping[tabIndex];
        const field_index = fields.indexOf(field_name);

        if (field_index === fields.length - 1) {
          const next_tab_Index = this.getNextTabIndex(tabIndex);
          const first_field = String(
            this.fields_tabindex_mapping[next_tab_Index][0],
          );

          const is_available = this.isFieldAvailableToFocus(first_field);

          if (!is_available) {
            return this.getNextTabIndexField(next_tab_Index, first_field);
          } else {
            return first_field;
          }
        }

        const next_field_index = field_index + 1;
        const next_field_name = String(fields[next_field_index]);
        const is_available = this.isFieldAvailableToFocus(next_field_name);
        if (!is_available) {
          return this.getNextTabIndexField(tabIndex, next_field_name);
        }
        return next_field_name;
      } catch (err) {
        return '';
      }
    },

