    handleChargesFieldsVisibility(group: any) {
      this.showAllChargesFields = false;

      for (let index = 0; index < group.rows.length; index = index + 2) {
        try {
          const currentFielName = group.rows[index].field_name;
          if (index + 1 >= group.rows.length) {
            break;
          }
          const nextFielName = group.rows[index + 1].field_name;
          // If both fields in the row do not has data then hide it
          if (
            !this.formBuilderModel[currentFielName].value &&
            !this.formBuilderModel[nextFielName].value
          ) {
            group.rows[index].visibile = false;
            group.rows[index + 1].visibile = false;
          }
        } catch (err) {
          logError(
            err,
            index,
            group.rows[index],
            group.rows[index + 1],
            group.rows.length,
          );
        }
      }
    },
