    handleTabGroupLabels(group: any, group_name: string) {
      let fullIsVisible = false;
      let altLabels: { [k: string]: any } = {};

      if (
        (Object.keys(group).length === 0 &&
          Object.getPrototypeOf(group) === Object.prototype) ||
        group_name !== GROUP_NAMES.tax_details
      ) {
        return altLabels;
      }

      for (let button of group.buttons) {
        if (button.name == 'full' && button.selected === true) {
          fullIsVisible = true;
          break;
        }
      }

      if (fullIsVisible) {
        return altLabels;
      }

      for (let button of group.buttons) {
        if (button.name !== 'full' && button.selected === true) {
          altLabels = button.alt_translation_keys;
          break;
        }
      }
      return altLabels;
    },

