    selectionPopupSelected(e: any) {
      if (
        !e.detail ||
        !e.detail.data ||
        !e.detail.data.data ||
        !e.detail.selected
      ) {
        return;
      }
      this.showSelectionPopupDialog = false;
      let field_data = e.detail.data.data;
      let coords = field_data.coords;

      if (e.detail.selected == 'extracted') {
        field_data = field_data.extracted_value;
      }

      this.formBuilderModel[this.connectionId].value = field_data.value;
      this.formBuilderModel[this.connectionId].formatted_value =
        field_data.formatted_value;
      this.formBuilderModel[this.connectionId].content = field_data.text;
      this.formBuilderModel[this.connectionId].api_save = true;

      this.updateCoordinates(coords);
      this.inputValueChanges(this.connectionId);

      this.$forceUpdate();
      this.hideLoading();
    },

