            'This field will stay empty for this layout from now on.',
          ),
        );
      } else if (outcome === 'forbidden') {
        notify.warning(
          this.$t(
            'field_cleared_forbidden',
            'Only administrators may store this permanently — the field is cleared on this document only.',
          ),
        );
      } else if (outcome === 'no_extraction_key') {
        notify.warning(
          this.$t(
            'field_cleared_no_key',
            'Nothing can be stored for this document — the field is cleared here only.',
          ),
        );
      } else {
        notify.error(
          this.$t(
            'field_cleared_failed',
            'Could not be saved — the field is cleared on this document only.',
          ),
        );
      }
    },

