    populatePopupData(
      config: dynamicObj,
      master_lookup_type: string,
      master_data_row: string,
    ) {
      this.populateMasterDataFields(config, '', master_data_row, this.lookupRestoreGenerations);

      const currectDataSet = [
        {
          lookup_dataset_name: master_lookup_type,
          fieldName: this.connectionId,
          triggerDataSet: false,
        },
      ];

      const duplicateDataSet = this.preapreAutoTriggerDataSet(
        this.connectionId,
        master_lookup_type,
      );
      if (Array.isArray(duplicateDataSet)) {
        currectDataSet.push(...duplicateDataSet);
      }

      this.processAutoTriggerFields(currectDataSet);
      this.connectionId = '';
    },
    async populateMasterDataFields(
      config: dynamicObj,
      autoTriggedField: string,
      master_data_row: string,
      restoreGenerations = { ...this.restoreGenerations },
    ) {
      this.lookup_loading_fields = {};
      try {
        this.closeMsDialog();

        // const autoTriggerList = [];
        const conversionFields = this.getConversionFields();
        // General Response-Data for all the respective Fields
        let jsonResponse = JSON.parse(master_data_row);
        const values = [];
        const lookup_fields = config.fields;
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field[this.attributeKey];
          const lookup_field = field.lookup_field.toLowerCase();
          if (
            jsonResponse.hasOwnProperty(lookup_field) &&
            conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            values.push({
              key: jsonResponse[lookup_field],
              value: jsonResponse[lookup_field],
            });
          }
        }
        let formatted_values = [] as dynamicObj[];
        if (values.length > 0) {
          formatted_values = await this.formatMultiValues(
            values,
            'en_US',
            this.amount_format_locale,
          );
        }

        const extraction_method = 'MD';
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field[this.attributeKey];
          const lookup_field = field.lookup_field.toLowerCase();
          if (!this.formBuilderModel.hasOwnProperty(field_name)) {
            continue;
          }

          if (jsonResponse.hasOwnProperty(lookup_field) == false) {
            continue;
          }

          let formatted_value = jsonResponse[lookup_field];
          if (
            conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            formatted_value = this.searchValueByKey(
              formatted_value,
              formatted_values,
            );
          }

          // if lookup_field has name with name_formatted_value then it will be used as formatted value
          if (jsonResponse.hasOwnProperty(lookup_field + '_formatted_value')) {
            formatted_value = jsonResponse[lookup_field + '_formatted_value'];
          }

          // Check if this is the auto-triggered field and if the value from Master Data is different
          if (autoTriggedField == field_name) {
            const currentValue = this.formBuilderModel[field_name].formatted_value || this.formBuilderModel[field_name].value;
            const newValue = formatted_value || jsonResponse[lookup_field];

            if (currentValue == newValue) {
              continue;
            }
          }

          if ((restoreGenerations[field_name] || 0) !== (this.restoreGenerations[field_name] || 0)) continue;
          this.formBuilderModel[field_name].formatted_value = formatted_value;
          this.formBuilderModel[field_name].value = jsonResponse[lookup_field];
          this.formBuilderModel[field_name].color =
            'extraction_method-border-left';
          this.formBuilderModel[field_name].extraction_method =
            extraction_method;

          if (formatted_value) {
            this.formBuilderModel[field_name].input_error = '';
          }

          if (
            !this.isCurrentFieldPrimary(field_name) &&
            this.isContentChanged(
              this.formBuilderModel[field_name].content,
              jsonResponse[lookup_field],
            )
          ) {
            this.formBuilderModel[field_name].content =
              jsonResponse[lookup_field];
            this.formBuilderModel[field_name].confidence = 0;
            this.formBuilderModel[field_name].validation_code = null;
            this.formBuilderModel[field_name].coords = null;
          }

          this.setColor(
            this.formBuilderModel[field_name],
            this.formBuilderConfigModel[field_name],
          );
          this.updateImportJson(
            field_name,
            this.formBuilderModel[field_name].coords,
            this.page,
            extraction_method,
          );
        }
        this.resetMasterDataStore();
      } catch (err) {
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

