    async processAutoTriggerFields(currectDataSet: any) {
      if (!currectDataSet || currectDataSet.length == 0) {
        return;
      }

      currectDataSet = this.removeDuplicateGroups(currectDataSet);

      let lookupsList = [];

      for (let item of currectDataSet) {
        if (item.triggerDataSet) {
          lookupsList.push(item);
        }

        const lookups = this.findDependentLookups(
          this.record.layout.lookup_configurations,
          item.lookup_dataset_name,
          item.fieldName,
        );

        if (lookups && lookups.length > 0) {
          lookupsList.push(...lookups);
        }
      }

      lookupsList = this.removeDuplicateGroups(lookupsList);

      for (let item of lookupsList) {
        const configFields =
          this.lookupDictionary[item.id]['fields'];

        this.setLookupFieldStatus(
          configFields,
          true,
          configFields.lookup_dataset_name,
          null,
        );

        const restoreGenerations = { ...this.restoreGenerations };
        const response = await this.loadAutoTriggerData(item);

        if (response && response.message == CONSTANTS.not_executed) {
          this.setLookupFieldStatus(
            configFields,
            false,
            item.lookup_dataset_name,
            false,
          );
          continue;
        }

        if (!response || !response.data || response.data.length == 0) {
          this.resetChildFields(
            this.lookupDictionary[item.id],
            item.fieldName,
            restoreGenerations,
          );
          this.setLookupFieldStatus(
            configFields,
            false,
            configFields.lookup_dataset_name,
            false,
          );
          continue;
        }

        this.populateMasterDataFields(
          this.lookupDictionary[item.id],
          item.fieldName,
          JSON.stringify(response.data[0]),
          restoreGenerations,
        );
        this.setLookupFieldStatus(
          configFields,
          false,
          configFields.lookup_dataset_name,
          true,
        );
      }

      this.updateScriptRequest();
      // this.record.apply_script_triggered_on_field = '';
      this.debounceScriptCalculateFunc();

      // this.alreadyExecutedGroups = [];
      this.saveFieldsStateForAutotrigger(this.record.fields);
    },
    resetChildFields(config: dynamicObj, triggerByField: string, restoreGenerations = { ...this.restoreGenerations }) {
      const lookup_fields = config.fields;
      for (let [index, field] of lookup_fields.entries()) {
        const field_name = field[this.attributeKey];
        if ((restoreGenerations[field_name] || 0) !== (this.restoreGenerations[field_name] || 0)) continue;

        if (
          triggerByField == field_name ||
          !this.formBuilderModel[field_name]
        ) {
          continue;
        }
        this.formBuilderModel[field_name].value = null;
        this.formBuilderModel[field_name].color = null;
        this.formBuilderModel[field_name].coords = null;
        this.formBuilderModel[field_name].content = null;
        this.formBuilderModel[field_name].confidence = null;
        this.formBuilderModel[field_name].formatted_value = null;
        this.formBuilderModel[field_name].validation_code = null;
        this.formBuilderModel[field_name].extraction_method = null;
        this.updateImportJson(
          field_name,
          this.formBuilderModel[field_name].coords,
          this.page,
          '',
        );
      }
    },
    setLookupFieldStatus(
      fields: any,
      enable: boolean,
      lookup_dataset_name: string,
      lookup_status: boolean | null,
    ) {
      for (let field of fields) {
        if (!this.formBuilderModel.hasOwnProperty(field.field_name)) {
          continue;
        }

        if (!this.lookup_loading_fields.hasOwnProperty(field.field_name)) {
          this.lookup_loading_fields[field.field_name] = {} as dynamicObj;
        }
        this.lookup_loading_fields[field.field_name].lookup_loading = enable;

        this.lookup_loading_fields[field.field_name].lookup_found =
          lookup_status;
        this.lookup_loading_fields[field.field_name].lookup_found_name =
          lookup_dataset_name;
      }
    },
    triggerScriptChangedFields(updated_fields = [] as dynamicObj[]) {
      if (updated_fields.length == 0) {
        return;
      }

      const autoTriggerFiled = [] as any;

      updated_fields.forEach((field: any) => {
        const field_name = field.name ? field.name : field.field_name;

        if (this.autoTriggerFields[field_name]) {
          const currectDataSet = this.preapreAutoTriggerDataSet(field_name);

          if (Array.isArray(currectDataSet)) {
            autoTriggerFiled.push(...currectDataSet);
          }
        }
      });

      return autoTriggerFiled;
    },
    triggerOnSave() {
      this.alreadyExecutedGroups = [];

      const autoTriggerFiled = [] as any;

      for (const [field_name, groups] of Object.entries(
        this.autoTriggerFields,
      )) {
        if (this.checkifFieldChangedForTrigger(field_name)) {
          const currectDataSet = this.preapreAutoTriggerDataSet(field_name);
          if (Array.isArray(currectDataSet)) {
            autoTriggerFiled.push(...currectDataSet);
          }
        }
      }

      if (autoTriggerFiled.length == 0) {
        return;
      }

      this.processAutoTriggerFields(autoTriggerFiled);
    },
    preapreAutoTriggerDataSet(
      fieldName: string,
      dataSetToSkip = '',
      triggerDataSet = true,
    ): any {
      // A multi-PO header value is not a lookup key, on save or from the script
      // response either, so it never builds a trigger set.
      if (
        fieldName === 'purchase_order' &&
        splitCommaSeparatedValues(
          this.formBuilderModel[fieldName]?.formatted_value,
        ).length > 1
      ) {
        return [];
      }

      const autoTriggerObject = this.autoTriggerFields[fieldName];
      return this.preapreAutoTriggerList(
        autoTriggerObject,
        fieldName,
        dataSetToSkip,
        triggerDataSet,
      );
    },
  },
  setup() {
    let dataObj: any = [];
    let groupShortCutMap = new Map();

    // OBO-156: the Kopffeld-Check gate, for the fields' source badges. The
    // form elements read `headerFieldOriginInteractive` to render the badge
    // as plain text when there is no door at all (module off, undecided).
    const { state: headerFieldCheckState } = useHeaderFieldCheck();
    const { blockers: validationBlockers } = useValidationBlockers();
    provide(
      'headerFieldOriginInteractive',
      computed(() => originEntryAction(headerFieldCheckState.value) !== 'none'),
    );

    const settings_store = useSettingStore();
    const { getSetting } = settings_store;

    const doc_attribute_store = useDocAttributesStore();
    const { model: docTypeAttributesModel } = storeToRefs(doc_attribute_store);

    const form_builder_store = useFormBuilderStore();

    const {
      freeze_fields_change_event,
      formBuilderModel,
      formLayout,
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      renderComponent,
      docType,
      fieldColors,
      layout_template_id,
      isFieldUnderEditing,
      fieldListToHighlight,
    } = storeToRefs(form_builder_store);
    const {
      getElementWidth,
      prepareLayoutData,
      performCalulations,
      isFieldHidden,
      duplicateSubGroup,
      prepareIndexesForSubGroups,
      getLayoutTemplate,
      refreshResolvedLayout,
    } = form_builder_store;

    const doc_store = useDocumentStore();
    const {
      record,
      po_items,
      doc_loaded,
      auto_saving,
      connectionId,
      auto_saved_done,
      fieldsNotDisplayed,
      get_cached_data_id,
      script_api_timestamp,
      amount_format_locale,
      lookup_configurations,
      is_extracted_table_update,
      ignore_doc_type_specific_validation,
    } = storeToRefs(doc_store);
    const {
      saveFieldsStateForAutotrigger,
      getScriptChangedFields,
      hasTable,
      saveOneFieldStateForAutotrigger,
      checkifFieldChangedForTrigger,
      saveDocument,
      applyScriptOnDocument,
      updateRecordAfterScript,
      handlePoItems,
      setDataToCache,
      setRecordFromCache,
      saveAndValidate,
      validateFields,
      cleanupDataforApi,
      setDocDataVariables,
      updateRequestId,
      findSubGroupChildFields,
      prepareFormula,
      removeAccountingData,
      shouldConfirmAccountingReset,
      setExtractionTableDataFromCache,
    } = doc_store;

    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const {
      // model: ms_view_model,
      advance_filters: ms_advance_filters,
      master_lookup_type,
      changed_fields,
      groups_to_update,
      populate_row_to_view,
      isDraggle,
      fuzzyDialog,
      lookupDictionary,
      autoTriggerFields,
      alreadyExecutedGroups,
      inital_filters,
    } = storeToRefs(doc_ms_data_lookup_store);
    const {
      resetMasterDataStore,
      isContentChanged,
      isCurrentFieldPrimary,
      prepareMSFilter,
      loadAutoTriggerData,
      findDependentLookups,
      triggerlookupLovs,
      setupTableLookup,
      preapreAutoTriggerList,
      removeDuplicateGroups,
    } = doc_ms_data_lookup_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    field_values_setting_store.$reset();
    const { populateListsAndValues, addNameToLovList } =
      field_values_setting_store;

    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { isConfirmationBoxDisable } = storeToRefs(
      form_builder_settings_store,
    );

    const dashboard_store = useDashboardStore();
    const { dashboardFiltersAfterExport } = dashboard_store;

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, searchValueByKey } = amount_format_store;

    const { tokenQueryParam } = useImageAuth();
    const lookup_function_store = useLookupFunctionStore();
    const { lookup_loading_fields } = storeToRefs(lookup_function_store);

    // OBO-156: the fields configured as a date — the Kopffeld-Check shows
    // their values in the user's date format, not as the stored ISO string.
    const headerDateFields = computed(() =>
      Object.keys(formBuilderConfigModel.value ?? {}).filter(
        (name) =>
          String(formBuilderConfigModel.value?.[name]?.field_type ?? '').toLowerCase() === 'date',
      ),
    );

    return {
      docTypeAttributesModel,
      headerFieldCheckState,
      validationBlockers,
      headerDateFields,
      po_items,
      connectionId,
      saveOneFieldStateForAutotrigger,
      lookup_loading_fields,
      fieldColors,
      isFieldUnderEditing,
      info_panel_chip_colors,
      saveFieldsStateForAutotrigger,
      checkifFieldChangedForTrigger,
      freeze_fields_change_event,
      lookup_configurations,
      is_extracted_table_update,
      script_api_timestamp,
      autoTriggerFields,
      lookupDictionary,
      tokenQueryParam,
      getScriptChangedFields,
      updateRecordAfterScript,
      handlePoItems,
      isCurrentFieldPrimary,
      inital_filters,
      formatMultiValues,
      searchValueByKey,
      loadAutoTriggerData,
      findDependentLookups,
      removeDuplicateGroups,
      preapreAutoTriggerList,
      triggerlookupLovs,
      setupTableLookup,
      prepareMSFilter,
      hasTable,
      getSetting,
      isFieldHidden,
      addNameToLovList,
      duplicateSubGroup,
      prepareIndexesForSubGroups,
      doc_loaded,
      setDocDataVariables,
      saveAndValidate,
      validateFields,
      cleanupDataforApi,
      performCalulations,
      amount_format_locale,
      dashboardFiltersAfterExport,
      setRecordFromCache,
      updateRequestId,
      setDataToCache,
      saveDocument,
      prepareFormula,
      getLayoutTemplate,
      refreshResolvedLayout,
      resetMasterDataStore,
      removeAccountingData,
      shouldConfirmAccountingReset,
      setExtractionTableDataFromCache,
      applyScriptOnDocument,
      populateListsAndValues,
      findSubGroupChildFields,
      ignore_doc_type_specific_validation,

      master_lookup_type,
      changed_fields,
      groups_to_update,
      isDraggle,

      ms_advance_filters,
      isConfirmationBoxDisable,
      populate_row_to_view,
      isContentChanged,
      // ms_view_model,
      record,
      apiData: ref(dataObj),
      tableAreasStr: ref(''),
      is_sep_view: ref(false),
      // fuzzyDialog: ref(false),
      fuzzyDialog,
      selectedRow: ref([]),
      renderKey: 0,
      formBuilderModel,
      formLayout,
      formLayoutOrignal: ref([] as any),
      isExtenedPanel,
      isFormBuilderMode,
      formBuilderConfigModel,
      layout_template_id,
      get_cached_data_id,
      renderComponent,
      docType,
      groupShortCutMap: groupShortCutMap,
      fieldListToHighlight,
      fieldsNotDisplayed,
      tb_version: 'default',

      // funcations
      getElementWidth,
      prepareLayoutData,
      is_admin: ref(false),
      master_data_popup_width: ref('700'),
      fields_tabindex_mapping: ref({} as dynamicObj),
      // subGroupsDeatils: ref({} as dynamicObj),
      script_loading: ref(false),
      auto_saving,
      auto_saved_done,

      DOC_SCRIPT_MODULE: ref(false),
      trigger_fields: ref([] as any),

      alreadyExecutedGroups,
      eDocIcon: ref(''),
    };
  },
});
</script>

<style lang="scss">
// Fix panel-right layout: dropdowns + icons on one row (match dev)
// Root cause: Quasar grid classes (.col-9, .col-6, .col-auto) are not
// bundled in local webpack build, so we must replicate the flex layout.
.image_control_panel {
  padding: 0 !important;
  margin-bottom: 4px !important;

  // The .row already has display:flex from Quasar base, but we need nowrap
  > .panel-right {
    flex-wrap: nowrap !important;
    align-items: center !important;
    padding: 0 !important;
    gap: 4px !important;
  }

  // A `col-auto` whose component renders nothing (autoTesting, when auto
  // testing is off) is still a flex item and still costs a gap. Collapse it,
  // or the toolbar carries dead space nobody can see the source of.
  > .panel-right > .col-auto:empty {
    display: none !important;
  }

  // Dropdowns container: content width, never squeezed under the buttons
  // (CORE-6161 folds the buttons into "..." instead).
  > .panel-right > .medi-classification {
    flex: 0 0 auto !important;
    min-width: 0 !important;
    max-width: none !important;
    width: auto !important;

    // Inner .row from classification/main.vue has class="full-width"
    // which forces width:100%. Override it to shrink-to-fit.
    > .row {
      width: auto !important;
      flex-wrap: nowrap !important;
      padding: 0 !important;
      gap: 4px !important;
      align-items: center;
    }

    // .col-6 divs wrapping each dropdown
    > .row > div {
      flex: 0 0 auto !important;
      width: auto !important;
      min-width: 0 !important;
      max-width: 200px !important;
      padding: 0 !important;
    }

    // Compact the q-select fields
    .q-field.q-select {
      padding: 0 !important;
    }
    .q-field__control {
      height: 32px;
      min-height: 32px !important;
    }
    .q-field--outlined .q-field__control {
      padding: 0 8px !important;
    }
    .q-field__control-container {
      padding: 0 !important;
    }
    .q-field__native {
      min-height: 32px !important;
      padding: 0 !important;
    }
    .q-field__marginal {
      height: 32px;
      padding: 0 4px !important;
    }
    .q-field__native span {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
  }

  // Folded and still too narrow: clip the dropdowns rather than overlap.
  > .panel-right--collapsed > .medi-classification {
    flex-shrink: 1 !important;
    overflow: hidden;
  }

  // Icon buttons: no grow, auto width
  > .panel-right > .col-auto,
  > .panel-right > .q-btn {
    flex: 0 0 auto !important;
  }

  // Fix: .image_control_panel .row matches .q-btn__content (Quasar uses .row internally)
  // which adds 16px 20px padding to button contents. Reset it.
  // Also resets the 40px min-width/height app.scss puts on every button in
  // this panel ("touch-friendly" — but these are a 22px icon each, so it was
  // padding the glyph by 9px a side on top of its own padding and the row
  // gap). The Tailwind `px-6` on the buttons themselves never applied: this
  // rule outranks it.
  > .panel-right .q-btn {
    padding: 4px 6px !important;
    min-height: unset !important;
    min-width: unset !important;
  }
  > .panel-right .q-btn__content {
    padding: 0 !important;
  }
}
