import type { dynamicObj } from 'src/pages/assets';

// CORE-6161: pure parts of the validation assistant's master-data lookup actions.

export const LOOKUP_SNAPSHOT_KEYS = [
  'formatted_value',
  'value',
  'content',
  'confidence',
  'coords',
  'extraction_method',
  'color',
  'input_error',
  'is_valid',
  'is_validated',
  'validation_code',
  'validation_message',
] as const;

export type FieldSnapshots = Record<string, dynamicObj>;

export function snapshotModels(
  formBuilderModel: dynamicObj | null | undefined,
  names?: string[],
): FieldSnapshots {
  const out: FieldSnapshots = {};
  const model = formBuilderModel || {};
  for (const name of names ?? Object.keys(model)) {
    const field = model[name];
    if (!field || typeof field !== 'object') continue;
    const snapshot: dynamicObj = {};
    for (const key of LOOKUP_SNAPSHOT_KEYS) snapshot[key] = field[key];
    out[name] = snapshot;
  }
  return out;
}

const same = (a: unknown, b: unknown) => (a ?? '') === (b ?? '');

// The fields whose value a lookup changed, in model order.
export function changedFields(before: FieldSnapshots, formBuilderModel: dynamicObj): string[] {
  return Object.keys(before).filter((name) => {
    const field = formBuilderModel?.[name];
    if (!field) return false;
    return !same(field.formatted_value, before[name].formatted_value) || !same(field.value, before[name].value);
  });
}

export function pick(snapshots: FieldSnapshots, names: string[]): FieldSnapshots {
  const out: FieldSnapshots = {};
  for (const name of names) if (snapshots[name]) out[name] = snapshots[name];
  return out;
}

export function appliedValues(formBuilderModel: dynamicObj, names: string[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const name of names) out[name] = formBuilderModel?.[name]?.formatted_value ?? null;
  return out;
}

// Undo skips a field the user edited after the assistant's change.
export function restorePlan(
  formBuilderModel: dynamicObj,
  previous: unknown,
  applied: unknown,
): { restore: string[]; skipped: string[] } {
  const restore: string[] = [];
  const skipped: string[] = [];
  if (!previous || typeof previous !== 'object') return { restore, skipped };
  const expected = applied && typeof applied === 'object' ? (applied as Record<string, unknown>) : {};
  for (const name of Object.keys(previous as dynamicObj)) {
    const field = formBuilderModel?.[name];
    if (!field) {
      skipped.push(name);
      continue;
    }
    if (name in expected && !same(field.formatted_value, expected[name])) {
      skipped.push(name);
      continue;
    }
    restore.push(name);
  }
  return { restore, skipped };
}

const comparable = (value: unknown) =>
  value === null || value === undefined ? '' : String(value).toLowerCase().replace(/[^\p{L}\p{N}]/gu, '');

const isMasked = (display: string) => display.includes('•') || /<[A-Z]+>/.test(display);

export interface LookupFill {
  field: string;
  label?: string;
  display?: string;
}

// The candidate row at candidate_index must still be the one the server described.
export function candidateMatchesFills(
  row: dynamicObj | null | undefined,
  configFields: dynamicObj[] | null | undefined,
  fills: LookupFill[] | null | undefined,
  attributeKey = 'field_name',
): boolean {
  if (!row || typeof row !== 'object') return false;
  let compared = 0;
  for (const fill of fills || []) {
    const display = typeof fill?.display === 'string' ? fill.display : '';
    if (!display || isMasked(display)) continue;
    const config = (configFields || []).find((f) => f?.[attributeKey] === fill.field);
    if (!config?.lookup_field) continue;
    const key = String(config.lookup_field).toLowerCase();
    const raw = row[`${key}_formatted_value`] ?? row[key];
    compared += 1;
    if (comparable(raw) !== comparable(display)) return false;
  }
  return compared > 0;
}

export function applyFieldSnapshot(field: dynamicObj, snapshot: dynamicObj) {
  for (const key of LOOKUP_SNAPSHOT_KEYS) {
    if (Object.prototype.hasOwnProperty.call(snapshot, key)) field[key] = snapshot[key];
  }
}
