<!-- CORE-6161: lamp next to Save; the red number is how many fields block validation. -->
<template>
  <div class="col-auto">
    <q-btn
      flat
      class="px-6"
      id="validation_assistant_toggle"
      data-test="validation-assistant-toggle"
      :aria-label="ariaLabel"
      :aria-pressed="active ? 'true' : 'false'"
      @click="toggle"
    >
      <Icon
        icon="docbits:genie-lamp"
        width="22"
        height="22"
        :class="active ? 'text-primary' : 'icon-grey'"
      />
      <q-badge
        v-if="blockers.total > 0"
        color="negative"
        floating
        rounded
        data-test="validation-assistant-count"
      >
        {{ blockers.total }}
      </q-badge>
      <q-tooltip>{{ $t('validation_assistant_title') }}</q-tooltip>
    </q-btn>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useValidationBlockers } from 'src/composables/useValidationBlockers';
import {
  TOGGLE_VALIDATION_ASSISTANT_EVENT,
  validationAssistantHost,
} from 'src/utils/validationBlockers';

export default defineComponent({
  name: 'ValidationAssistantButton',
  setup() {
    const { blockers } = useValidationBlockers();
    return { blockers };
  },
  computed: {
    active(): boolean {
      return validationAssistantHost.open;
    },
    ariaLabel(): string {
      const title = this.$t('validation_assistant_title');
      if (!this.blockers.total) {
        return title;
      }
      return `${title}: ${this.$t('validation_assistant_count_label', {
        count: this.blockers.total,
      })}`;
    },
  },
  methods: {
    toggle() {
      document.dispatchEvent(new CustomEvent(TOGGLE_VALIDATION_ASSISTANT_EVENT));
    },
  },
});
</script>
