<!--
  "Herkunft des Wertes" — the origin of ONE header field (OBO-156, mockup
  page 2).

  Opened from the field's source badge. The value's journey is told as
  numbered stations — the page, the engine that read it, the script that
  rewrote it, the master-data lookup that replaced it, what the field says
  now — and only the stations the payload actually carries are shown. Then
  the two ways out the user has: put the page value back, or pick another
  record.

  Every fact comes from the report payload. A missing number, page or value
  is left out or says "not recorded" — it is never filled in.
-->
<template>
  <q-dialog :model-value="modelValue" @update:model-value="close">
    <q-card
      class="flex max-h-[80vh] w-full max-w-[820px]! flex-col overflow-hidden bg-card text-sm text-foreground"
      data-test="hfo-dialog"
    >
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>{{ $t('header_field_check_origin_eyebrow') }}</q-toolbar-title>
        <q-btn
          flat
          round
          icon="close"
          class="text-white"
          :aria-label="$t('close')"
          data-test="hfo-close"
          @click="close(false)"
        />
      </q-toolbar>

      <q-card-section v-if="entry" class="border-b border-border">
        <div class="flex min-w-0 items-center gap-2">
          <h2 class="truncate text-lg font-semibold" data-test="hfo-title">
            {{ title }}
          </h2>
          <Icon
            v-if="finalTile"
            data-test="hfo-title-source"
            :icon="finalTile.icon"
            :color="finalTile.color"
            :aria-label="$t(finalTile.labelKey)"
            class="size-5 shrink-0"
          />
          <span
            role="img"
            data-test="hfo-intro"
            :aria-label="introText"
            class="inline-flex shrink-0 cursor-help text-muted-foreground"
            ><Icon icon="mdi:information-outline" class="size-4" /><q-tooltip
              max-width="320px"
              >{{ introText }}</q-tooltip
            ></span
          >
        </div>
        <ul
          data-test="hfo-sources"
          :aria-label="$t('header_field_check_sources_label')"
          class="mt-2 flex flex-wrap gap-1"
        >
          <li
            v-for="tile in sourceTiles"
            :key="tile.source"
            data-test="hfo-source-tile"
            :data-source="tile.source"
            :data-use="tile.use"
            :aria-label="sourceTileText(tile)"
            class="relative flex size-8 items-center justify-center rounded-md border border-transparent"
            :class="tile.classes"
          >
            <Icon :icon="tile.icon" :color="tile.color" class="size-[18px]" />
            <span
              v-if="tile.use === 'unused'"
              aria-hidden="true"
              class="absolute left-1 right-1 top-1/2 h-px -rotate-45 bg-current"
            />
            <q-tooltip>{{ sourceTileText(tile) }}</q-tooltip>
          </li>
        </ul>
      </q-card-section>

      <q-card-section class="min-h-0 flex-1 overflow-y-auto">
        <div v-if="loading" class="flex flex-col items-center gap-2 py-10 text-muted-foreground">
          <q-spinner size="32px" />
          <span class="text-xs">{{ $t('loading') }}</span>
        </div>

        <div
          v-else-if="errorMessage"
          role="alert"
          class="rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-destructive"
        >
          {{ errorMessage }}
        </div>

        <div
          v-else-if="report && !entry"
          role="alert"
          class="rounded-md border border-border bg-muted px-3 py-2 text-muted-foreground"
        >
          {{ $t('header_field_check_origin_missing') }}
        </div>

        <template v-else-if="entry">
          <ol class="flex flex-col">
            <li
              v-for="(station, index) in stations"
              :key="station.number"
              data-test="hfo-station"
              :data-stage="station.stage"
              class="flex gap-3"
            >
              <div class="flex flex-col items-center">
                <span
                  data-test="hfo-number"
                  class="flex size-7 shrink-0 items-center justify-center rounded-full border text-xs font-semibold"
                  :class="numberClass(station)"
                  >{{ station.number }}</span
                >
                <span
                  v-if="index < stations.length - 1"
                  class="my-1 w-px flex-1 bg-border"
                  aria-hidden="true"
                />
              </div>

              <div class="min-w-0 flex-1 pb-5">
                <!-- 1. The page -->
                <template v-if="station.stage === 'document'">
                  <div class="font-semibold">{{ documentTitle(station) }}</div>
                  <div
                    v-if="station.textSourceKey"
                    data-test="hfo-text-source"
                    class="mt-0.5 text-xs text-muted-foreground"
                  >
                    {{ $t(station.textSourceKey) }}
                  </div>
                  <div
                    class="max-w-full break-words mt-2 inline-block rounded-md border border-border bg-muted px-3 py-2"
                  >
                    <template v-if="!station.valueKnown">
                      <span class="italic text-muted-foreground">
                        {{ $t('header_field_check_origin_unrecorded') }}
                      </span>
                    </template>
                    <template v-else-if="station.value">{{ display(station.value) }}</template>
                    <span v-else class="text-muted-foreground">
                      {{ $t('header_field_check_value_empty') }}
                    </span>
                  </div>
                </template>

                <!-- 2. The engine that read it -->
                <template v-else-if="station.stage === 'extraction'">
                  <div class="flex items-center gap-1.5 font-semibold">
                    {{ keyText(station.titleKey) }}
                    <span
                      v-if="station.ruleTookTextAsIs"
                      role="img"
                      data-test="hfo-rule-explain"
                      :aria-label="
                        $t('header_field_check_station_rule_explain')
                      "
                      class="inline-flex shrink-0 cursor-help text-muted-foreground"
                      ><Icon
                        icon="mdi:information-outline"
                        class="size-4"
                      /><q-tooltip max-width="320px">{{
                        $t('header_field_check_station_rule_explain')
                      }}</q-tooltip></span
                    >
                  </div>
                  <div class="mt-2 flex flex-wrap gap-1.5">
                    <q-badge
                      v-if="station.sourceKey"
                      data-test="hfo-source"
                      color="grey"
                      >{{ $t(station.sourceKey) }}</q-badge
                    >
                    <q-badge
                      v-if="station.confidence !== null"
                      data-test="hfo-confidence"
                      color="grey"
                      >{{
                        $t('header_field_check_station_confidence', {
                          percent: station.confidence,
                        })
                      }}</q-badge
                    >
                    <q-badge
                      v-if="station.rule && station.rule.weight !== null"
                      data-test="hfo-rule-weight"
                      color="grey"
                      >{{
                        $t('header_field_check_rule_weight', {
                          weight: station.rule.weight,
                        })
                      }}<q-tooltip max-width="320px">{{
                        $t('header_field_check_rule_weight_explain')
                      }}</q-tooltip></q-badge
                    >
                    <q-badge
                      v-if="station.rule && station.rule.score !== null"
                      data-test="hfo-rule-score"
                      color="grey"
                      >{{
                        $t('header_field_check_rule_score', {
                          percent: station.rule.score,
                        })
                      }}<q-tooltip max-width="320px">{{
                        $t('header_field_check_rule_score_explain')
                      }}</q-tooltip></q-badge
                    >
                    <q-badge
                      v-if="station.xml"
                      data-test="hfo-xml-tag"
                      color="grey"
                      >{{
                        $t('header_field_check_xml_tag', { tag: station.xml.tag })
                      }}</q-badge
                    >
                    <q-badge
                      v-if="station.xml && station.xml.format"
                      data-test="hfo-xml-format"
                      color="grey"
                      >{{ station.xml.format }}</q-badge
                    >
                  </div>
                  <ul
                    v-if="extractionLines(station).length"
                    data-test="hfo-extraction-details"
                    class="mt-2 flex list-disc flex-col gap-0.5 pl-5 text-muted-foreground"
                  >
                    <li v-for="(line, lineIndex) in extractionLines(station)" :key="lineIndex">
                      {{ line }}
                    </li>
                  </ul>
                  <div
                    v-if="station.rule && station.rule.rivals.length"
                    data-test="hfo-rule-rivals"
                    class="mt-2"
                  >
                    <div class="text-xs font-semibold">
                      {{ $t('header_field_check_rule_rivals') }}
                    </div>
                    <ul class="mt-1 flex flex-col gap-1">
                      <li
                        v-for="(rival, rivalIndex) in station.rule.rivals"
                        :key="rivalIndex"
                        data-test="hfo-rule-rival"
                        class="flex flex-wrap items-center gap-1.5"
                      >
                        <span class="break-words rounded-md border border-border bg-muted px-2 py-0.5">{{
                          display(rival.value)
                        }}</span>
                        <span class="text-xs text-muted-foreground">{{
                          $t('header_field_check_rule_rival_meta', {
                            weight: rival.weight,
                            percent: rival.score,
                          })
                        }}</span>
                      </li>
                    </ul>
                  </div>
                </template>

                <!-- 3. A script rewrote it -->
                <template v-else-if="station.stage === 'transform'">
                  <div
                    class="flex flex-wrap items-center gap-1.5 font-semibold"
                  >
                    {{ keyText(station.titleKey) }}
                    <q-badge
                      v-if="station.scriptLabel"
                      color="grey"
                      data-test="hfo-script"
                      >{{
                        $t('header_field_check_station_script_named', {
                          name: station.scriptLabel,
                        })
                      }}</q-badge
                    >
                    <span
                      v-if="!station.directional"
                      role="img"
                      data-test="hfo-script-undirected"
                      :aria-label="
                        $t('header_field_check_station_script_undirected')
                      "
                      class="inline-flex shrink-0 cursor-help text-muted-foreground"
                      ><Icon
                        icon="mdi:information-outline"
                        class="size-4"
                      /><q-tooltip max-width="320px">{{
                        $t('header_field_check_station_script_undirected')
                      }}</q-tooltip></span
                    >
                  </div>
                  <div
                    v-if="station.directional"
                    class="mt-2 flex flex-wrap items-center gap-2 rounded-md border border-warning/40 bg-warning/5 px-3 py-2"
                  >
                    <s class="text-muted-foreground">{{ display(station.struck) }}</s>
                    <Icon icon="mdi:arrow-right" class="size-4 text-muted-foreground" />
                    <span v-if="station.next" class="font-semibold">{{ display(station.next) }}</span>
                    <span v-else class="text-muted-foreground">
                      {{ $t('header_field_check_value_empty') }}
                    </span>
                  </div>
                  <template v-else>
                    <div
                      class="mt-2 flex flex-wrap items-center gap-2 rounded-md border border-warning/40 bg-warning/5 px-3 py-2"
                    >
                      <template v-for="(value, valueIndex) in station.values" :key="valueIndex">
                        <Icon
                          v-if="valueIndex > 0"
                          icon="mdi:swap-horizontal"
                          class="size-4 text-muted-foreground"
                        />
                        <span>{{ display(value) }}</span>
                      </template>
                    </div>
                  </template>
                </template>

                <!-- 4. Master data replaced it -->
                <template v-else-if="station.stage === 'lookup'">
                  <div class="flex items-center gap-1.5 font-semibold">
                    {{ keyText(station.titleKey) }}
                    <span
                      v-if="station.needle"
                      role="img"
                      data-test="hfo-needle"
                      :aria-label="
                        $t(
                          'header_field_check_station_lookup_substring_explain',
                          { needle: station.needle },
                        )
                      "
                      class="inline-flex shrink-0 cursor-help"
                      :class="
                        station.tone === 'bad'
                          ? 'text-destructive'
                          : 'text-muted-foreground'
                      "
                      ><Icon
                        icon="mdi:information-outline"
                        :color="station.tone === 'bad' ? 'var(--destructive)' : undefined"
                        class="size-4"
                      /><q-tooltip max-width="320px">{{
                        $t(
                          'header_field_check_station_lookup_substring_explain',
                          { needle: station.needle },
                        )
                      }}</q-tooltip></span
                    >
                  </div>
                  <ul
                    v-if="lookupLines(station).length"
                    data-test="hfo-lookup-trigger"
                    class="mt-2 flex list-disc flex-col gap-0.5 pl-5 text-muted-foreground"
                  >
                    <li v-for="(line, lineIndex) in lookupLines(station)" :key="lineIndex">
                      {{ line }}
                    </li>
                  </ul>
                  <div class="mt-2 flex flex-wrap items-center gap-2">
                    <span
                      v-if="!station.filledAlong"
                      class="max-w-full break-words rounded-md border border-border bg-muted px-3 py-2"
                    >
                      <template v-if="station.fromValue !== null">{{
                        display(station.fromValue)
                      }}</template>
                      <span
                        v-else
                        class="italic text-muted-foreground"
                      >
                        {{ $t('header_field_check_origin_unrecorded') }}
                      </span>
                    </span>
                    <Icon
                      v-if="!station.filledAlong"
                      icon="mdi:arrow-right"
                      class="size-4 text-muted-foreground"
                    />
                    <span
                      class="max-w-full break-words rounded-md border border-border bg-card px-3 py-2 font-semibold"
                    >
                      <template
                        v-for="(part, partIndex) in displayParts(
                          station.toParts,
                        )"
                        :key="partIndex"
                      >
                        <mark
                          v-if="part.hit"
                          class="rounded-sm bg-destructive/25 px-px text-inherit"
                          >{{ part.text }}</mark
                        >
                        <span v-else>{{ part.text }}</span>
                      </template>
                      <span v-if="!station.toParts.length" class="font-normal text-muted-foreground">
                        {{ $t('header_field_check_value_empty') }}
                      </span>
                    </span>
                  </div>
                  <div
                    v-if="hasLookupInfo(station)"
                    data-test="hfo-lookup-info"
                    class="mt-2 flex flex-wrap gap-1.5"
                  >
                    <q-badge v-if="station.dataset" color="grey">{{
                      $t('header_field_check_station_dataset', {
                        dataset: datasetText(station.dataset),
                      })
                    }}</q-badge>
                    <q-badge
                      v-if="station.matchKindKey"
                      :color="station.tone === 'bad' ? 'negative' : 'grey'"
                      >{{
                        $t('header_field_check_station_match_kind', {
                          kind: $t(station.matchKindKey),
                        })
                      }}</q-badge
                    >
                    <q-badge
                      v-if="station.hits"
                      color="grey"
                      data-test="hfo-hits"
                      >{{
                        $t('header_field_check_station_hits', station.hits)
                      }}</q-badge
                    >
                  </div>
                </template>

                <!-- 5. What the field says now -->
                <template v-else-if="station.stage === 'result'">
                  <div class="flex items-center gap-1.5 font-semibold">
                    {{ $t('header_field_check_station_result') }}
                    <span
                      v-if="station.drives.length"
                      role="img"
                      data-test="hfo-drives"
                      :aria-label="
                        $t('header_field_check_station_result_drives', {
                          fields: drivesText(station),
                        })
                      "
                      class="inline-flex shrink-0 cursor-help text-muted-foreground"
                      ><Icon
                        icon="mdi:information-outline"
                        class="size-4"
                      /><q-tooltip max-width="320px">{{
                        $t('header_field_check_station_result_drives', {
                          fields: drivesText(station),
                        })
                      }}</q-tooltip></span
                    >
                  </div>
                  <div
                    class="max-w-full break-words mt-2 inline-block rounded-md border-2 border-primary/60 bg-primary/5 px-3 py-2 font-semibold"
                  >
                    <template v-if="station.value">{{
                      display(station.value)
                    }}</template>
                    <span
                      v-else
                      class="font-normal text-muted-foreground"
                    >
                      {{ $t('header_field_check_value_empty') }}
                    </span>
                  </div>
                </template>
              </div>
            </li>
          </ol>
        </template>
      </q-card-section>

      <q-card-actions
        v-if="entry && hasActions"
        align="right"
        data-test="hfo-footer"
        class="flex-wrap gap-2 border-t border-border"
      >
        <span class="mr-auto font-semibold">{{ footerLead }}</span>
        <q-btn
          v-if="restoreValue !== null"
          outline
          no-caps
          data-test="hfo-restore"
          @click="restoreOriginal"
          >{{ $t(restoreKey, { value: display(restoreValue) }) }}</q-btn
        >
        <q-btn
          v-if="actions.searchMasterData"
          unelevated
          no-caps
          color="primary"
          data-test="hfo-search"
          @click="searchMasterData"
          >{{ $t(isPurchaseOrder ? 'header_field_check_origin_other_po' : 'header_field_check_origin_other_record') }}</q-btn
        >
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import HeaderFieldReportApiService from 'src/services/document/HeaderFieldReportApiService';
import ExtractionExplanationApiService from 'src/services/document/ExtractionExplanationApiService';
import type { HeaderFieldEntry, HeaderFieldReport } from 'src/types/headerFieldReport';
import type { FieldExplanation } from 'src/types/extractionExplanation';
import {
  changedStationNumbers,
  datasetLabel,
  entryLabel,
  formatHeaderValue,
  originActions,
  originStations,
  restoreLabelKey,
  sourceTiles,
  type HighlightPart,
  type OriginStation,
  type SourceTile,
} from 'src/utils/header-field-check-view';
import { logger } from 'src/utils/logger';
import dateUtils from 'src/utils/date';

/** The app's own date display: the user's "Date Pattern" preference. */
function formatUserDate(iso: string): string {
  return dateUtils.methods.formatDateAccordingToPreference(iso, true, iso);
}

export default defineComponent({
  name: 'HeaderFieldOriginDialog',
  components: { Icon },
  props: {
    modelValue: { type: Boolean, required: true },
    docId: { type: String as PropType<string>, required: true },
    fieldName: { type: String as PropType<string>, required: true },
    /**
     * The value "reset" would actually put back, or null when a reset is not
     * possible (no snapshot, read-only field, lookup still loading). Only the
     * validation screen knows this — restoreOriginalField restores the
     * snapshot's `value`, which after a script is not the page text — so the
     * button shows and names exactly what the click does, never a dead button.
     */
    restoreValue: { type: String as PropType<string | null>, default: null },
    /**
     * The fields configured as a date (the payload carries no field type).
     * Their values are shown in the user's date format: "read from the
     * document" next to an ISO string the page never contained is false.
     */
    dateFields: { type: Array as PropType<string[]>, default: () => [] },
  },
  emits: ['update:modelValue', 'restore-original', 'search-master-data'],
  data() {
    return {
      report: null as HeaderFieldReport | null,
      explanations: [] as FieldExplanation[],
      loading: false,
      errorMessage: '',
      /**
       * Which request may write the result. Open, close, reopen: two
       * requests race, and without this the older one can land second and
       * replace the fresh report — same guard as HeaderFieldCheckDialog.
       */
      requestGeneration: 0,
    };
  },
  computed: {
    entry(): HeaderFieldEntry | null {
      return (this.report?.fields ?? []).find((field) => field?.name === this.fieldName) ?? null;
    },
    title(): string {
      return entryLabel(this.entry) || this.fieldName;
    },
    explanation(): FieldExplanation | null {
      return this.explanations.find((field) => field?.field_name === this.fieldName) ?? null;
    },
    stations(): OriginStation[] {
      return originStations(this.entry, this.report?.fields, this.explanation);
    },
    introText(): string {
      const numbers = changedStationNumbers(this.stations);
      if (!numbers.length) return this.$t('header_field_check_origin_intro_unchanged');
      if (numbers.length === 1) {
        return this.$t('header_field_check_origin_intro_changed_one', {
          stations: String(numbers[0]),
        });
      }
      const head = numbers.slice(0, -1).join(', ');
      const last = numbers[numbers.length - 1];
      return this.$t('header_field_check_origin_intro_changed', {
        stations: `${head} ${this.$t('header_field_check_origin_and')} ${last}`,
      });
    },
    actions(): { restoreTo: string | null; searchMasterData: boolean } {
      return originActions(this.entry);
    },
    hasActions(): boolean {
      return this.restoreValue !== null || this.actions.searchMasterData;
    },
    /** "Reset to …", or "… (before the master-data lookup)" after a script. */
    restoreKey(): string {
      return restoreLabelKey(this.entry);
    },
    isDate(): boolean {
      return this.dateFields.includes(this.fieldName);
    },
    sourceTiles(): SourceTile[] {
      return sourceTiles(this.entry);
    },
    finalTile(): SourceTile | null {
      return this.sourceTiles.find((tile) => tile.use === 'final') ?? null;
    },
    isPurchaseOrder(): boolean {
      return this.fieldName === 'purchase_order';
    },
    footerLead(): string {
      if (this.isPurchaseOrder) return this.$t('header_field_check_origin_footer_lead_po');
      return this.$t('header_field_check_origin_footer_lead', { label: this.title });
    },
  },
  watch: {
    modelValue: {
      handler(open: boolean) {
        // Reloaded on every open: the user comes here from a screen where
        // they have just been editing, and a cached answer about the
        // document before the last save is worse than a short spinner.
        if (open) void this.load();
      },
      immediate: true,
    },
  },
  methods: {
    async load() {
      const generation = ++this.requestGeneration;
      this.loading = true;
      this.errorMessage = '';
      if (!this.docId) {
        this.report = null;
        this.errorMessage = this.$t('header_field_check_load_failed');
        this.loading = false;
        return;
      }
      try {
        const service = new HeaderFieldReportApiService({});
        const [result, explanations] = await Promise.all([
          service.getForDocument(this.docId),
          this.loadExplanations(),
        ]);
        if (generation !== this.requestGeneration) return;
        this.report = result;
        this.explanations = explanations;
      } catch (error) {
        if (generation !== this.requestGeneration) return;
        logger.warn('[HEADER-FIELD-ORIGIN] report load failed', error);
        this.report = null;
        this.errorMessage = this.$t('header_field_check_load_failed');
      } finally {
        if (generation === this.requestGeneration) this.loading = false;
      }
    },
    /** Rule details only decorate the stations; without them the dialog still answers. */
    async loadExplanations(): Promise<FieldExplanation[]> {
      try {
        const result = await new ExtractionExplanationApiService({}).getForDocument(this.docId);
        return Array.isArray(result?.fields) ? result.fields : [];
      } catch (error) {
        logger.warn('[HEADER-FIELD-ORIGIN] explanation load failed', error);
        return [];
      }
    },
    /** The sentences under the extraction station: what read the value, and how. */
    extractionLines(station: OriginStation): string[] {
      const lines: string[] = [];
      const rule = station.rule;
      if (rule) {
        if (rule.labelLeft) {
          lines.push(this.$t('header_field_check_rule_label_left', { label: rule.labelLeft }));
        }
        if (rule.labelAbove) {
          lines.push(this.$t('header_field_check_rule_label_above', { label: rule.labelAbove }));
        }
        if (rule.labelFound === false) lines.push(this.$t('header_field_check_rule_label_missing'));
        if (rule.positionKey) lines.push(this.$t(rule.positionKey));
        if (rule.trainedBy && rule.trainedOn) {
          lines.push(
            this.$t('header_field_check_rule_trained_by_on', {
              name: rule.trainedBy,
              date: formatUserDate(rule.trainedOn),
            }),
          );
        } else if (rule.trainedBy) {
          lines.push(this.$t('header_field_check_rule_trained_by', { name: rule.trainedBy }));
        } else if (rule.trainedOn) {
          lines.push(
            this.$t('header_field_check_rule_trained_on', { date: formatUserDate(rule.trainedOn) }),
          );
        }
      }
      if (station.xml) lines.push(this.$t('header_field_check_station_electronic_explain'));
      return lines;
    },
    /** What started the lookup and what it searched with. */
    lookupLines(station: OriginStation): string[] {
      const lines: string[] = [];
      if (station.lookupName) {
        lines.push(this.$t('header_field_check_lookup_name', { name: station.lookupName }));
      }
      if (station.triggerKey) lines.push(this.$t(station.triggerKey));
      if (station.searchInputs.length) {
        const inputs = station.searchInputs
          .map((input) => `${input.label} “${this.display(input.value)}”`)
          .join(', ');
        lines.push(this.$t('header_field_check_lookup_inputs', { fields: inputs }));
      }
      for (const input of station.searchInputs.filter((item) => item.learned)) {
        lines.push(this.$t('header_field_check_lookup_learned', { label: input.label }));
      }
      if (station.afterOtherLookup) lines.push(this.$t('header_field_check_lookup_after_other'));
      if (station.triggeredBy) {
        lines.push(
          station.triggeredBy.value
            ? this.$t('header_field_check_lookup_triggered_by_value', {
                label: station.triggeredBy.label,
                value: this.display(station.triggeredBy.value),
              })
            : this.$t('header_field_check_lookup_triggered_by', { label: station.triggeredBy.label }),
        );
      }
      if (station.record) {
        const dataset = this.datasetText(station.dataset);
        if (station.record.value && station.record.column) {
          lines.push(
            this.$t('header_field_check_lookup_record', {
              dataset,
              column: station.record.column,
              value: station.record.value,
            }),
          );
        } else if (station.record.id) {
          lines.push(this.$t('header_field_check_lookup_record_id', { dataset, id: station.record.id }));
        }
      }
      if (station.lookupColumn) {
        lines.push(this.$t('header_field_check_lookup_column', { column: station.lookupColumn }));
      }
      if (station.filledAlong) lines.push(this.$t('header_field_check_lookup_group'));
      return lines;
    },
    close(value: boolean) {
      this.$emit('update:modelValue', value === true);
    },
    restoreOriginal() {
      this.$emit('restore-original', { fieldName: this.fieldName });
      this.close(false);
    },
    searchMasterData() {
      this.$emit('search-master-data', { fieldName: this.fieldName });
      this.close(false);
    },
    /** A value as the user sees it: a date field in the user's date format. */
    display(value: string | null | undefined): string {
      return formatHeaderValue(value, this.isDate, formatUserDate);
    },
    /** The lookup's value; a reformatted date is shown unmarked. */
    displayParts(parts: HighlightPart[]): HighlightPart[] {
      if (!this.isDate) return parts;
      const text = this.display(parts.map((part) => part.text).join(''));
      return text ? [{ text, hit: false }] : [];
    },
    datasetText(dataset: string | null): string {
      return datasetLabel(dataset, (key) => this.$t(key));
    },
    keyText(key: string): string {
      return key ? this.$t(key) : '';
    },
    documentTitle(station: OriginStation): string {
      if (station.page === null || station.page === '') {
        return this.$t('header_field_check_station_document_nopage');
      }
      return this.$t('header_field_check_station_document', { page: station.page });
    },
    hasLookupInfo(station: OriginStation): boolean {
      return Boolean(station.dataset || station.matchKindKey || station.hits);
    },
    sourceTileText(tile: SourceTile): string {
      return this.$t(`header_field_check_source_${tile.use}`, {
        source: this.$t(tile.labelKey),
      });
    },
    drivesText(station: OriginStation): string {
      return station.drives
        .map((dependant) => {
          const value = formatHeaderValue(
            dependant.value,
            this.dateFields.includes(dependant.name),
            formatUserDate,
          );
          return value ? `${dependant.label} ${value}` : dependant.label;
        })
        .join(', ');
    },
    numberClass(station: OriginStation): string {
      if (station.tone === 'result')
        return 'border-primary bg-primary text-primary-foreground';
      if (station.tone === 'bad')
        return 'border-destructive bg-destructive text-destructive-foreground';
      if (station.tone === 'warn')
        return 'border-warning/60 bg-warning/20 text-foreground';
      if (station.tone === 'ok')
        return 'border-success/60 bg-success/20 text-foreground';
      return 'border-border bg-muted text-foreground';
    },
  },
});
</script>
