<!--
  "Woher kommt jeder Wert?" — the Kopffeld-Check report body (OBO-156).

  One fixed-layout row per field: what the page said, what changed it, what
  the screen shows, and why. Long values are cut with … and shown in full on
  hover; the worst field is marked red, with the matched substring marked.

  Every fact comes from the payload. A key the server did not send renders as
  its fallback (the field's name, the old counters, no date) — never as an
  invented value.
-->
<template>
  <div class="hfc-report gap-4 text-sm text-foreground">
    <header class="flex flex-col gap-1">
      <div class="flex min-w-0 items-center gap-2">
        <span v-if="metaLine" data-test="hfc-meta" class="truncate font-semibold">{{ metaLine }}</span>
        <span
          role="img"
          data-test="hfc-intro"
          :aria-label="$t('header_field_check_report_subtitle')"
          class="inline-flex shrink-0 cursor-help text-muted-foreground"
          ><Icon icon="mdi:information-outline" class="size-4" /><q-tooltip max-width="320px">{{
            $t('header_field_check_report_subtitle')
          }}</q-tooltip></span
        >
        <a
          data-test="hfc-help-link"
          :href="docsUrl"
          target="_blank"
          rel="noopener noreferrer"
          :aria-label="$t('header_field_check_help_link')"
          class="inline-flex shrink-0 text-muted-foreground hover:text-primary"
        >
          <Icon icon="mdi:help-circle-outline" class="size-4" />
          <q-tooltip>{{ $t('header_field_check_help_link') }}</q-tooltip>
        </a>
      </div>
    </header>

    <ul class="flex flex-wrap gap-2">
      <li v-for="tile in tiles" :key="tile.tone">
        <q-btn
          flat
          dense
          no-caps
          data-test="hfc-tile"
          :data-tone="tile.tone"
          :aria-pressed="toneFilter === tile.tone ? 'true' : 'false'"
          :disable="!tile.count"
          class="rounded-full border px-3 text-xs"
          :class="toneFilter === tile.tone ? activeFilterClass : 'border-border'"
          @click="toggleTone(tile.tone)"
        >
          <span class="flex items-center gap-1.5">
            <span class="size-2 rounded-full" :class="tile.dot" aria-hidden="true" />
            <span class="tabular-nums">{{ tile.count }}</span>
            <span>{{ $t(tile.key) }}</span>
            <Icon v-if="toneFilter === tile.tone" icon="mdi:close" class="size-3.5" aria-hidden="true" />
          </span>
        </q-btn>
      </li>
    </ul>

    <ul
      data-test="hfc-sources"
      :aria-label="$t('header_field_check_sources_label')"
      class="flex flex-wrap gap-1"
    >
      <li v-for="tile in reportSources" :key="tile.source">
        <q-btn
          flat
          dense
          no-caps
          data-test="hfc-source-filter"
          :data-source="tile.source"
          :aria-pressed="sourceFilter === tile.source ? 'true' : 'false'"
          :aria-label="$t(tile.labelKey)"
          :disable="!tile.count"
          class="relative h-8 rounded-md border px-2"
          :class="sourceFilter === tile.source ? activeFilterClass : 'border-transparent'"
          @click="toggleSource(tile.source)"
        >
          <span class="flex items-center gap-1">
            <Icon :icon="tile.icon" :color="tile.count ? tile.color : 'var(--muted-foreground)'" class="size-[18px]" />
            <span v-if="tile.count" class="text-xs tabular-nums">{{ tile.count }}</span>
            <Icon v-if="sourceFilter === tile.source" icon="mdi:close" class="size-3.5" aria-hidden="true" />
          </span>
          <q-tooltip>{{ $t(tile.labelKey) }}</q-tooltip>
        </q-btn>
      </li>
    </ul>

    <q-input
      v-model="search"
      dense
      outlined
      clearable
      data-test="hfc-search"
      class="w-full max-w-xs"
      :placeholder="$t('search')"
      :aria-label="$t('search')"
    >
      <template #prepend><Icon icon="mdi:magnify" class="size-4" /></template>
    </q-input>

    <div class="hfc-table rounded-md border border-border">
      <table class="w-full min-w-[880px] table-fixed border-collapse">
        <colgroup>
          <col class="w-[16%]" />
          <col class="w-[18%]" />
          <col class="w-[18%]" />
          <col class="w-6" />
          <col class="w-[18%]" />
          <col />
        </colgroup>
        <thead class="sticky top-0 z-[1] bg-muted text-left text-xs text-muted-foreground">
          <tr>
            <template v-for="column in columns" :key="column.key">
              <th v-if="column.key === 'arrow'" aria-hidden="true" />
              <th
                v-else
                class="px-3 py-2 font-semibold"
                :aria-sort="sortKey === column.key ? (sortDesc ? 'descending' : 'ascending') : 'none'"
              >
                <button
                  type="button"
                  data-test="hfc-sort"
                  :data-column="column.key"
                  class="inline-flex max-w-full items-center gap-1 hover:text-foreground"
                  @click="toggleSort(column.key)"
                >
                  <span class="truncate">{{ $t(column.labelKey) }}</span>
                  <Icon
                    :icon="sortKey !== column.key ? 'mdi:unfold-more-horizontal' : sortDesc ? 'mdi:arrow-down' : 'mdi:arrow-up'"
                    class="size-3.5 shrink-0"
                  />
                </button>
              </th>
            </template>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="entry in sortedRows"
            :key="entry.name"
            data-test="hfc-row"
            :data-hero="entry.name === heroName ? 'true' : undefined"
            class="border-t border-border"
            :class="rowClass(entry)"
          >
            <td class="px-3 py-1.5">
              <div class="flex min-w-0 items-center gap-2">
                <span class="size-2 shrink-0 rounded-full" :class="dotClass(entry)" aria-hidden="true" />
                <span class="truncate font-semibold">{{ entryLabel(entry) }}</span>
                <q-tooltip>{{ entryLabel(entry) }}</q-tooltip>
              </div>
            </td>

            <td class="px-3 py-1.5" data-test="hfc-document-value">
              <div class="truncate tabular-nums">
                <template v-if="entry.document_value">{{ displayValue(entry, entry.document_value) }}</template>
                <!-- A required field nothing filled: the status already says
                     "Required field"; "not on the document" would be a claim. -->
                <span v-else-if="isRequiredEmpty(entry)" class="text-muted-foreground">—</span>
                <span v-else-if="entry.document_value_known" class="text-muted-foreground">
                  {{ $t('header_field_check_not_on_document') }}
                </span>
                <span v-else class="text-muted-foreground">—</span>
              </div>
              <q-tooltip v-if="entry.document_value">{{ displayValue(entry, entry.document_value) }}</q-tooltip>
            </td>

            <td class="px-3 py-1.5" data-test="hfc-action">
              <div class="flex min-w-0 flex-nowrap gap-1 overflow-hidden">
                <span
                  v-for="(chip, index) in rowChips(entry)"
                  :key="index"
                  data-test="hfc-chip"
                  :data-final="chip.final ? 'true' : undefined"
                  class="inline-flex min-w-0 shrink items-center gap-1 rounded border px-1.5 py-0.5 text-xs"
                  :class="chip.cls"
                >
                  <Icon v-if="chip.icon" :icon="chip.icon" :color="chip.color" class="size-3.5 shrink-0" />
                  <span class="truncate first-letter:uppercase">{{ chip.text }}</span>
                  <Icon v-if="chip.mark" icon="mdi:check" class="size-3.5 shrink-0" aria-hidden="true" />
                </span>
              </div>
              <!-- Every step with what it did; the one the value comes from is marked. -->
              <q-tooltip
                v-if="actionLines(entry).length"
                max-width="420px"
                anchor="bottom left"
                self="top left"
                :offset="[0, 4]"
              >
                <ol data-test="hfc-action-steps" class="flex flex-col gap-1.5">
                  <li
                    v-for="(line, index) in actionLines(entry)"
                    :key="index"
                    :data-final="line.final ? 'true' : undefined"
                    class="grid grid-cols-[1rem_minmax(0,1fr)] items-start gap-x-2"
                  >
                    <Icon v-if="line.icon" :icon="line.icon" class="mt-0.5 size-4" />
                    <span v-else aria-hidden="true" />
                    <span class="min-w-0">
                      <span class="first-letter:uppercase">{{ line.title }}</span>
                      <span v-if="line.detail" class="break-all">: {{ line.detail }}</span>
                      <span v-if="line.note" class="block opacity-80">{{ line.note }}</span>
                      <span v-if="line.final" class="block font-semibold">✓ {{ $t('header_field_check_source_final_here') }}</span>
                    </span>
                  </li>
                </ol>
              </q-tooltip>
            </td>

            <td class="text-muted-foreground" aria-hidden="true">
              <Icon icon="mdi:arrow-right" class="size-4" />
            </td>

            <td class="px-3 py-1.5" data-test="hfc-current-value">
              <div class="truncate tabular-nums">
                <template v-if="entry.current_value">
                  <template v-for="(part, index) in valueParts(entry)" :key="index">
                    <mark v-if="part.hit" class="hfc-hl">{{ part.text }}</mark>
                    <template v-else>{{ part.text }}</template>
                  </template>
                </template>
                <span v-else class="text-muted-foreground">
                  {{ $t('header_field_check_value_empty') }}
                </span>
              </div>
              <q-tooltip v-if="entry.current_value">{{ displayValue(entry, entry.current_value) }}</q-tooltip>
            </td>

            <td class="px-3 py-1.5" data-test="hfc-reason">
              <div class="flex min-w-0 items-center gap-2">
                <span
                  data-test="hfc-status"
                  class="shrink-0 rounded border px-1.5 py-0.5 text-xs first-letter:uppercase"
                  :class="statusChipClass(entry)"
                  >{{ $t(statusChipKey(entry, report.fields)) }}</span
                >
                <span
                  v-if="reasonText(entry)"
                  role="img"
                  data-test="hfc-reason-info"
                  :aria-label="reasonText(entry)"
                  class="inline-flex shrink-0 cursor-help text-muted-foreground"
                  ><Icon icon="mdi:information-outline" class="size-4" /><q-tooltip max-width="360px">{{
                    reasonText(entry)
                  }}</q-tooltip></span
                >
              </div>
            </td>
          </tr>
          <tr v-if="!sortedRows.length">
            <td colspan="6" class="px-3 py-6 text-center text-muted-foreground">
              {{ $t('no_results_found') }}
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <p v-if="emptyOptional" class="text-xs text-muted-foreground">
      {{ $t('header_field_check_empty_fields', { count: emptyOptional }) }}
    </p>

  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { Icon } from '@iconify/vue';
import type {
  HeaderFieldEntry,
  HeaderFieldReport,
  HeaderFieldStep,
} from 'src/types/headerFieldReport';
import {
  changingSteps,
  datasetLabel,
  docTypeLabel,
  entryLabel,
  formatHeaderValue,
  heroField,
  highlightParts,
  HEADER_FIELD_CHECK_DOCS_URL,
  originSource,
  usedSources,
  ORIGIN_SOURCES,
  type OriginSource,
  rowFields,
  rowTone,
  sourceTone,
  statusChipKey,
  stepKind,
  stepLabelKey,
  SOURCE_TONE_CLASSES,
  type HighlightPart,
  type RowTone,
} from 'src/utils/header-field-check-view';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import dateUtils from 'src/utils/date';
import docTypeLable from 'src/utils/docTypeLable';

type SortKey = 'field' | 'document' | 'action' | 'current' | 'reason';

/** The app's own date display: the user's "Date Pattern" preference. */
function formatUserDate(iso: string): string {
  return dateUtils.methods.formatDateAccordingToPreference(iso, true, iso);
}

export default defineComponent({
  name: 'HeaderFieldReportView',
  components: { Icon },
  props: {
    report: { type: Object as PropType<HeaderFieldReport>, required: true },
    /**
     * The fields configured as a date. The payload does not carry a field
     * type; the validation screen knows it and passes it down. Their values
     * are shown in the user's date format instead of the stored ISO string.
     */
    dateFields: { type: Array as PropType<string[]>, default: () => [] },
  },
  setup() {
    // The organisation's document types, as the validation screen's type
    // dropdown lists them — the label the reader knows the document by.
    const { doc_types_sub_types_list: docTypes } = storeToRefs(useDropdownStore());
    return { docTypes };
  },
  data() {
    return {
      sourceFilter: '' as string,
      toneFilter: '' as RowTone | '',
      search: '' as string | null,
      sortKey: '' as SortKey | '',
      sortDesc: false,
    };
  },
  computed: {
    docsUrl(): string {
      return HEADER_FIELD_CHECK_DOCS_URL;
    },
    metaLine(): string {
      const doc = this.report.document ?? ({} as HeaderFieldReport['document']);
      const type = docTypeLabel(doc.doc_type, this.docTypes, (value) =>
        docTypeLable.methods.displayDocType(value),
      );
      return [doc.filename, type, formatHeaderValue(doc.date, true, formatUserDate)]
        .filter((part): part is string => typeof part === 'string' && part !== '')
        .join(' · ');
    },
    /** Counted from the rows, so a chip's number is what its filter shows. */
    tiles(): Array<{ key: string; tone: RowTone; count: number; dot: string }> {
      const count = (tone: RowTone) => this.rows.filter((entry) => rowTone(entry) === tone).length;
      return [
        {
          key: 'header_field_check_tile_unchanged',
          tone: 'ok',
          count: count('ok'),
          dot: 'bg-success',
        },
        {
          key: 'header_field_check_tile_changed',
          tone: 'changed',
          count: count('changed'),
          dot: 'bg-warning',
        },
        {
          key: 'header_field_check_tile_not_on_document',
          tone: 'bad',
          count: count('bad'),
          dot: 'bg-destructive',
        },
      ];
    },
    activeFilterClass(): string {
      return 'border-primary bg-primary/10! text-primary ring-1 ring-primary';
    },
    heroName(): string | undefined {
      return heroField(this.report)?.name;
    },
    rows(): HeaderFieldEntry[] {
      return rowFields(this.report);
    },
    /** Every extraction method, with how many rows passed through it. */
    reportSources(): Array<OriginSource & { labelKey: string; count: number }> {
      const used = this.rows.map((entry) => usedSources(entry));
      return ORIGIN_SOURCES.map((origin) => ({
        ...origin,
        labelKey: `extraction_source.${origin.source.toLowerCase()}`,
        count: used.filter((sources) => sources.has(origin.source)).length,
      }));
    },
    visibleRows(): HeaderFieldEntry[] {
      return this.rows.filter(
        (entry) =>
          (!this.sourceFilter || usedSources(entry).has(this.sourceFilter)) &&
          (!this.toneFilter || rowTone(entry) === this.toneFilter),
      );
    },
    columns(): Array<{ key: SortKey | 'arrow'; labelKey: string }> {
      return [
        { key: 'field', labelKey: 'field' },
        { key: 'document', labelKey: 'header_field_check_hero_on_document' },
        { key: 'action', labelKey: 'action' },
        { key: 'arrow', labelKey: '' },
        { key: 'current', labelKey: 'header_field_check_hero_shown' },
        { key: 'reason', labelKey: 'reason' },
      ];
    },
    /** Filtered by the search over every text a row shows, then sorted. */
    sortedRows(): HeaderFieldEntry[] {
      const needle = (this.search ?? '').trim().toLowerCase();
      const rows = needle
        ? this.visibleRows.filter((entry) =>
            (['field', 'document', 'action', 'current', 'reason'] as SortKey[]).some((key) =>
              this.cellText(entry, key).toLowerCase().includes(needle),
            ),
          )
        : this.visibleRows;
      const key = this.sortKey;
      if (!key) return rows;
      const direction = this.sortDesc ? -1 : 1;
      return [...rows].sort((a, b) => {
        const left = this.cellText(a, key);
        const right = this.cellText(b, key);
        // Empty cells stay at the bottom in both directions.
        if (!left || !right) return left ? -1 : right ? 1 : 0;
        return direction * left.localeCompare(right, undefined, { numeric: true, sensitivity: 'base' });
      });
    },
    /** Empty fields nobody has to fill: a count, not rows. */
    emptyOptional(): number {
      return (this.report.fields ?? []).filter(
        (entry) => entry?.status === 'empty' && entry.is_required !== true,
      ).length;
    },
  },
  methods: {
    entryLabel,
    statusChipKey,
    isDateField(entry: HeaderFieldEntry | null | undefined): boolean {
      return !!entry && this.dateFields.includes(entry.name);
    },
    /** A value as the user sees it: a date field in the user's date format. */
    displayValue(entry: HeaderFieldEntry | null | undefined, value: string | null | undefined): string {
      return formatHeaderValue(value, this.isDateField(entry), formatUserDate);
    },
    isRequiredEmpty(entry: HeaderFieldEntry): boolean {
      return !entry.current_value && entry.is_required === true;
    },
    stepText(step: HeaderFieldStep): string {
      const key = stepLabelKey(step);
      return key ? this.$t(key) : '';
    },
    transformChipText(step: HeaderFieldStep): string {
      if (step.script?.label) {
        return this.$t('header_field_check_step_script_named', { name: step.script.label });
      }
      return this.stepText(step);
    },
    /**
     * The chips of a lookup: which record it read ("Bestellungen: 06O051001")
     * and, for anything short of an exact hit, how well it matched — the
     * record must not swallow the one fact that matters.
     */
    lookupChipTexts(step: HeaderFieldStep): string[] {
      const quality = this.stepText(step);
      if (!step.dataset) return quality ? [quality] : [];
      const dataset = datasetLabel(step.dataset, (key) => this.$t(key));
      const record = step.to
        ? this.$t('header_field_check_step_lookup_record', { dataset, value: step.to })
        : this.$t('header_field_check_step_lookup_from', { dataset });
      return step.match_quality === 'exact' || !quality ? [record] : [record, quality];
    },
    toggleSort(key: SortKey) {
      if (this.sortKey !== key) {
        this.sortKey = key;
        this.sortDesc = false;
      } else if (!this.sortDesc) {
        this.sortDesc = true;
      } else {
        this.sortKey = '';
      }
    },
    cellText(entry: HeaderFieldEntry, key: SortKey): string {
      if (key === 'field') return entryLabel(entry);
      if (key === 'document') return this.displayValue(entry, entry.document_value);
      if (key === 'current') return this.displayValue(entry, entry.current_value);
      if (key === 'action') return this.rowChips(entry).map((chip) => chip.text).join(' ');
      return `${this.$t(statusChipKey(entry, this.report.fields))} ${this.reasonText(entry)}`.trim();
    },
    toggleTone(tone: RowTone) {
      this.toneFilter = this.toneFilter === tone ? '' : tone;
    },
    toggleSource(source: string) {
      this.sourceFilter = this.sourceFilter === source ? '' : source;
    },
    /** The step the shown value comes from: the last one with a known engine. */
    finalStep(entry: HeaderFieldEntry): HeaderFieldStep | null {
      const steps = changingSteps(entry).filter(
        (step) => !!step.source && step.source !== 'UNKNOWN',
      );
      return steps[steps.length - 1] ?? null;
    },
    rowChips(
      entry: HeaderFieldEntry,
    ): Array<{
      text: string;
      cls: string;
      icon?: string;
      color?: string;
      final: boolean;
      mark: boolean;
    }> {
      const winner = this.finalStep(entry);
      const steps = changingSteps(entry);
      return steps.flatMap((step) => {
        const cls = this.chipClass(step);
        const origin = originSource(step.source);
        const texts =
          step.stage === 'lookup'
            ? this.lookupChipTexts(step)
            : [step.stage === 'transform' ? this.transformChipText(step) : this.stepText(step)];
        return texts
          .filter((text) => !!text)
          .map((text, index) => ({
            text,
            // A lookup's record chip keeps the method colour; only its quality chip warns.
            cls: this.isRecordChip(step, index) ? this.methodClass(step) : cls,
            final: step === winner,
            // Only worth a mark when there is more than one step to choose from.
            mark: steps.length > 1 && step === winner && index === 0,
            ...(index === 0 && origin ? { icon: origin.icon, color: origin.color } : {}),
          }));
      });
    },
    /** One line per step for the hover: what it did, from what to what. */
    actionLines(entry: HeaderFieldEntry): Array<{
      icon?: string;
      title: string;
      detail: string;
      note: string;
      final: boolean;
    }> {
      const winner = this.finalStep(entry);
      const quote = (value: string | null | undefined) =>
        `“${this.displayValue(entry, value ?? '')}”`;
      return changingSteps(entry).map((step) => {
        let title = this.stepText(step);
        let detail = '';
        let note = '';
        if (step.stage === 'transform') {
          title = this.transformChipText(step);
          if (step.directional && step.from != null && step.to != null) {
            detail = `${quote(step.from)} → ${quote(step.to)}`;
          } else if (step.values?.length) {
            detail = step.values.map(quote).join(' / ');
            note = this.$t('header_field_check_station_script_undirected');
          }
        } else if (step.stage === 'lookup') {
          title = this.lookupChipTexts(step).join(' · ') || title;
          if (step.to) detail = step.from ? `${quote(step.from)} → ${quote(step.to)}` : quote(step.to);
        } else if (step.value) {
          detail = quote(step.value);
        }
        return {
          icon: originSource(step.source)?.icon,
          title,
          detail,
          note,
          final: step === winner,
        };
      }).filter((line) => line.title || line.detail);
    },
    /** A lookup's first chip names the record, unless no dataset was recorded. */
    isRecordChip(step: HeaderFieldStep, index: number): boolean {
      return step.stage === 'lookup' && index === 0 && !!step.dataset;
    },
    methodClass(step: HeaderFieldStep): string {
      return originSource(step.source)?.final ?? SOURCE_TONE_CLASSES[sourceTone(step.source)];
    },
    chipClass(step: HeaderFieldStep): string {
      const kind = stepKind(step);
      if (kind === 'bad') return 'border-destructive/40 bg-destructive/10';
      if (kind === 'warn') return 'border-warning/40 bg-warning/10';
      return this.methodClass(step);
    },
    lookupStep(entry: HeaderFieldEntry): HeaderFieldStep | null {
      return entry.chain?.find((step) => step.stage === 'lookup') ?? null;
    },
    /** The shown value, with the part the lookup matched marked. */
    valueParts(entry: HeaderFieldEntry): HighlightPart[] {
      // The span points into the stored string, so a reformatted date stays unmarked.
      if (this.isDateField(entry)) {
        const text = this.displayValue(entry, entry.current_value);
        return text ? [{ text, hit: false }] : [];
      }
      return highlightParts(entry.current_value, this.lookupStep(entry)?.match_span);
    },
    /** Why the value is what it is, behind the (i) in the reason column. */
    reasonText(entry: HeaderFieldEntry): string {
      const parts: string[] = [];
      const lookup = this.lookupStep(entry);
      if (lookup?.match_quality === 'partial' && lookup.from && entry.current_value) {
        parts.push(
          this.$t('header_field_check_hero_partial_explain', {
            needle: lookup.from,
            value: entry.current_value,
          }),
        );
        if (lookup.candidate_count === 1) parts.push(this.$t('header_field_check_hero_single_hit'));
      }
      const byName = (name: string) =>
        (this.report.fields ?? []).find((field) => field?.name === name);
      if (entry.driven_by) {
        parts.push(
          this.$t('header_field_check_driven_by', {
            field: entryLabel(byName(entry.driven_by)) || entry.driven_by,
          }),
        );
      }
      if (entry.drives?.length) {
        const fields = entry.drives
          .map((name) => {
            const label = entryLabel(byName(name)) || name;
            const value = this.displayValue(byName(name), entry.drives_values?.[name] ?? '');
            return value ? `${label}: ${value}` : label;
          })
          .join(', ');
        parts.push(this.$t('header_field_check_drives', { fields }));
      }
      return parts.join(' ');
    },
    dotClass(entry: HeaderFieldEntry): string {
      const tone = rowTone(entry);
      if (tone === 'bad') return 'bg-destructive';
      if (tone === 'changed') return 'bg-warning';
      return 'bg-success';
    },
    rowClass(entry: HeaderFieldEntry): string {
      const tone = rowTone(entry);
      if (tone === 'bad') return 'bg-destructive/5';
      if (tone === 'changed') return 'bg-warning/5';
      return '';
    },
    statusChipClass(entry: HeaderFieldEntry): string {
      const tone = rowTone(entry);
      if (tone === 'bad') return 'border-destructive/40 bg-destructive/10 text-(--destructive-badge-text)';
      if (tone === 'changed') return 'border-warning/40 bg-warning/10 text-(--warning-badge-text)';
      return 'border-success/40 bg-success/10 text-(--success-badge-text)';
    },
  },
});
</script>

