/**
 * Who may press "Kopffeld-Check", and what happens when they may not — OBO-156.
 *
 * Three doors, and the whole point is that they are different doors. Showing
 * one generic "no access" for all three is what makes a support call: the
 * customer who has not bought the module, the admin who has switched it off
 * and the clerk whose role was never granted it each need a different next
 * step, and only one of them is a sales conversation.
 *
 * ## The order, and why
 *
 * 1. Not decidable yet → `loading`. Preferences and subscriptions arrive after
 *    mount. Deciding early gives the two classic failures: an upsell dialog
 *    flashed at a paying customer, or a button enabled before anyone knows the
 *    org has the module.
 * 2. Module off → `module_off`. Checked BEFORE the subscription (CORE-6434):
 *    an org that switched Analytics off has said it does not want it, and an
 *    upsell on every info icon is exactly what it was trying to turn off.
 * 3. No active subscription → `needs_subscription` for an org admin, the only
 *    person who can buy it; `not_offered` for everyone else (CORE-6434). A
 *    clerk shown a price list cannot act on it — the purchase 403s.
 * 4. Role not granted → `no_access`. An admin grants it under Settings → Roles.
 * 5. Otherwise → `ready`.
 *
 * ## This is not the security boundary
 *
 * `routers/header_field_report.py` decides again on every request, through the
 * same `require_analytics_access` gate the analytics API uses. What happens
 * here is that we do not offer a button whose report the person cannot load.
 * Keep the two in step anyway: an enabled button that 403s is indistinguishable
 * from an outage to the person pressing it.
 *
 * ## Why it rides the Analytics permission
 *
 * The Kopffeld-Check does not get a feature key of its own. "No grants
 * configured means admins only" is deliberate in that mechanism, so a new key
 * would ship denied in every tenant and have to be granted a second time even
 * where Analytics is already handed to a role.
 */

export type HeaderFieldCheckState =
  | 'loading'
  | 'needs_subscription'
  | 'not_offered'
  | 'module_off'
  | 'no_access'
  | 'ready';

export interface HeaderFieldCheckAccessInput {
  /** Preferences have arrived (see `analyticsAccessSettingsReady`). */
  settingsReady: boolean;
  /** The feature-subscription list has been fetched at least once. */
  subscriptionsReady: boolean;
  /** An active plan covering the analytics feature exists. */
  hasSubscription: boolean;
  /** The org's `ANALYTICS_DASHBOARD` module toggle, already coerced. */
  moduleEnabled: boolean;
  /**
   * The shared Analytics gate's verdict — admin, or a granted role.
   *
   * Taken as an input rather than recomputed here. `useAnalyticsAccess` owns
   * the grant list and invalidates it when an admin saves the roles page or
   * the acting identity changes; a second evaluation against a locally held
   * copy of the role ids keeps a button alive for someone whose access was
   * just revoked, and loses a race where a grant list that resolved before an
   * invalidation is installed after it.
   */
  analyticsGranted: boolean;
  /**
   * Is the acting user an organisation admin? Decides who sees the upsell —
   * only someone who can actually buy the plan.
   */
  isAdmin: boolean;
}

export function resolveHeaderFieldCheckState(
  input: HeaderFieldCheckAccessInput | null | undefined,
): HeaderFieldCheckState {
  // A missing input is a caller bug, not a grant. `loading` rather than a
  // denial: the button stays quiet instead of accusing anyone of anything.
  if (!input) return 'loading';

  if (!input.settingsReady || !input.subscriptionsReady) return 'loading';
  if (!input.moduleEnabled) return 'module_off';
  if (!input.hasSubscription) {
    return input.isAdmin ? 'needs_subscription' : 'not_offered';
  }

  return input.analyticsGranted ? 'ready' : 'no_access';
}

/**
 * What a click on the button should do.
 *
 * Here rather than in the component so the decision can be tested: `q-*` are
 * custom elements in this project and stubs never apply, so a component test
 * asserts on an empty render and passes for the wrong reason. Testing
 * `isReportReachable` alone did not cover this — the component had its own
 * copy of the condition, and every case still passed with that copy deleted.
 */
export function nextActionFor(
  state: HeaderFieldCheckState,
): 'report' | 'subscription' | 'none' {
  if (state === 'ready') return 'report';
  if (state === 'needs_subscription') return 'subscription';
  // loading, module_off, not_offered, no_access: the click is dropped rather than queued.
  // A report that opens a second later, after the user has moved on, is
  // worse than no dialog at all.
  return 'none';
}

/**
 * What a click on a field's source badge does — OBO-156 part 7.
 *
 * The badge opens "Herkunft des Wertes", which loads the same report as the
 * button, so it goes through the same three doors:
 *
 * * `ready` → `open`: the origin dialog.
 * * `needs_subscription` → `upsell`: the upsell dialog, as the button does.
 * * `no_access` → `hint`: the "your administrator grants it" notice.
 * * `module_off`, `not_offered` and `loading` → `none`: the badge is not
 *   clickable at all — the org switched the module off, the user cannot buy
 *   it (CORE-6434), or nothing is decided yet.
 */
export function originEntryAction(
  state: HeaderFieldCheckState,
): 'open' | 'upsell' | 'hint' | 'none' {
  if (state === 'ready') return 'open';
  if (state === 'needs_subscription') return 'upsell';
  if (state === 'no_access') return 'hint';
  return 'none';
}

/** Is the button pressable, or does it open a door instead? */
export function isReportReachable(state: HeaderFieldCheckState): boolean {
  return state === 'ready';
}

/** Everything the button needs to know about itself in one state. */
export interface HeaderFieldCheckButtonPresentation {
  /** `false` → the button is not in the DOM at all. */
  render: boolean;
  /** Greyed and not pressable. */
  disabled: boolean;
  /** Lock icon instead of the check icon — only where something is for sale. */
  lock: boolean;
  /** Translation key of the hover/focus hint, or `null` for none. */
  hintKey: string | null;
  /** What a click does. */
  action: 'report' | 'upsell' | 'none';
}

const HIDDEN: HeaderFieldCheckButtonPresentation = {
  render: false,
  disabled: false,
  lock: false,
  hintKey: null,
  action: 'none',
};

/**
 * How the button looks and what it does, per state — OBO-156 mockup pages 1/5.
 *
 * The component reads every visual decision from here and holds no copy of
 * its own; a copy in the template is how "lock on every non-ready state"
 * shipped the first time.
 *
 * * `needs_subscription` — pressable, lock, opens the upsell. Org admins
 *   only: an admin cannot grant what the org has not bought.
 * * `module_off` — not rendered, for anyone. The org switched the module off;
 *   a button that cannot work there is noise.
 * * `not_offered` — not rendered. Nothing this user can buy or be granted.
 * * `no_access` — greyed, no lock (nothing to buy), with a hint telling the
 *   user their administrator grants it under Settings › Roles.
 * * `loading` — greyed and silent: no lock, no hint, nothing decided yet.
 * * `ready` — active, opens the report.
 */
export function buttonPresentation(
  state: HeaderFieldCheckState,
): HeaderFieldCheckButtonPresentation {
  switch (state) {
    case 'needs_subscription':
      return { render: true, disabled: false, lock: true, hintKey: null, action: 'upsell' };
    case 'module_off':
    case 'not_offered':
      return { ...HIDDEN };
    case 'no_access':
      return {
        render: true,
        disabled: true,
        lock: false,
        hintKey: 'header_field_check_no_access_hint',
        action: 'none',
      };
    case 'ready':
      return { render: true, disabled: false, lock: false, hintKey: null, action: 'report' };
    case 'loading':
    default:
      return { render: true, disabled: true, lock: false, hintKey: null, action: 'none' };
  }
}
